pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (20 - post_residual) as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.2 * next_item_size as f64;
        } else {
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global pressure: many open bins -> favor filling existing ones (avoid new bins).
    score += 0.15 * open_bins_count as f64;

    // Mean residual coupling: prefer bins with residual close to mean (balanced),
    // but extreme small residual bins should be drained first.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time horizon: early in stream, be more exploratory (favor new bins slightly);
    // late in stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 5.0 - t * 5.0;

    // New-bin candidate handling: empty bin gets a mild penalty so it's chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - (item_size as f64) / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * (item_size as f64);

    // Lookahead: penalize leaving a residual that exactly wastes next item's fit
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            // next item can still fit here: reward a bit
            score -= 3.0;
            // reward if next item would fill nearly perfectly after this one
            let two_step = post - next;
            score -= 2.0 * (1.0 - two_step / cap);
        } else {
            // dead space for the next item: penalize proportionally to gap
            let gap = next - post;
            score += 0.6 * gap.min(cap);
        }
    } else {
        // last item: prefer minimal post_residual strongly
        score += 0.0;
        score -= 5.0 * (1.0 - post / cap);
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin is costly
    if fitting_bins_count <= 1 {
        score -= 12.0;
    } else if fitting_bins_count > 4 {
        score += 1.5 * (fitting_bins_count as f64 - 4.0);
    }

    // Time horizon: early in stream, tolerate new bins more; late, consolidate
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 4.0 * (post / cap);       // early: penalize leftovers mildly
    score -= t * 6.0 * (1.0 - post / cap);          // late: reward dense packing

    // Global state: many open bins with low mean residual -> avoid fragmentation
    if open_bins_count > 3 && mean_residual < 20.0 {
        score += 3.0;
    }
    // Prefer bins with residual far from mean (balance across bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make empty bins moderately attractive only for large items
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / cap) > 0.6;
        if large { score -= 2.0; } else { score += 6.0; }
    }

    // Penalize tiny unusable residuals (< 10) as dead space
    if post_residual < 10 && post_residual > 0 {
        score += 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that can fit the lookahead item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when new-bin option exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 3.0 * (1.0 - progress);

    // Prefer bins tighter than the mean residual (fill fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score -= 20.0;
        if post_residual > 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // Gap <= 10 is essentially dead space (min item size ~10); gap <= 20 is risky.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score += 60.0; // worst kind of dead space
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Open-bins pressure: penalize spreading across many bins.
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // creates dead space relative to lookahead
    }

    // New-bin candidate: only attractive when all fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; slight penalty so we prefer decent existing fits.
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: open new bin
        }
    }

    // Late-stream tightening: as stream progresses, prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mild preference toward bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post-residual that exactly
    // matches (or closely matches) the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is extremely desirable.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            // Next item still fits after this placement: mild reward scaled by closeness.
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit in this bin: penalize wasted lookahead opportunity.
            score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "drier";
    // filling them is good, but leaving tiny unusable slivers is bad.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.5 * (mean_residual - post_f);
    } else {
        score += 0.3 * (post_f - mean_residual);
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_f > 0.0 && post_f < 10.0 {
        score += 12.0 * (10.0 - post_f);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 20.0 - 10.0 * pressure + 5.0 * progress;
        // If lookahead can pair with a fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0;
        }
    }

    // Mild reward for keeping the number of open bins from exploding.
    score -= 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward exact fit for the known next item (lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residual already below mean (denser bins).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized early,
    // but attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score = 100.0 + post_residual as f64;
        if fitting_bins_count <= 2 {
            score -= 30.0;
        }
        if mean_residual < 20.0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward zone" residuals: too small for medium items, likely dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: more open bins -> prefer filling existing ones,
    // penalize opening new bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small or the item is large relative to it.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild baseline so it usually loses to decent fits...
        score += 30.0 + progress * 10.0;
        // ...but wins when existing bins are badly fragmented.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
        }
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and post-residual is a tiny unusable sliver, penalize more.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let frac = post_residual as f64 / cap; // 0..1
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic classes

    // Reward small residuals (tight fits), strongest for class 0 (near-perfect fit).
    score -= (8 - class.min(7)) as f64 * 6.0;

    // Penalize residuals in the "dead zone" that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly or well into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // good chaining, decays with slack
        } else {
            // next item cannot use this bin's remainder: slight penalty scaled by leftover
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // (i.e., item is large relative to residuals) or many bins are open.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64; // mean residual minus empty-bin residual
        // Empty bin is attractive when mean residual of open bins is small (poor fits available)
        // or many bins already open (diversify residual classes).
        score = 60.0 + frac * 0.0;
        score -= mean_residual * 0.8;
        score -= open_bins_count as f64 * 1.5;
        // Large items prefer a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Progress: late in the stream, consolidation matters more; penalize new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        let _ = spread;
    }

    // Mild coupling: prefer bins whose residual deviates from the mean in a useful way
    // (placing into a below-mean residual bin concentrates usage).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small for the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual) * 3.0;
    }
    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: slight penalty so it only wins when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 12.0 + (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium gaps are partially usable but risky
        score += 8.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Non-linear tightness reward: tighter fit => bigger discount
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to this item (good relative fit)
    let rel_fit = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * rel_fit;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would strand this bin, mild penalty unless gap is large
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 10.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a poor candidate
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: keep it competitive only when item is large and no tight fits exist
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
