        // modulo resonance between next item and post residual
        if (next_item_size % 10) == (post_residual % 10) && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin is very tight
    if bin_residual == bin_capacity {
        // new empty bin: neutral baseline with slight exploration bonus early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = c * 0.55 - progress * 5.0;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0; // lookahead suggests fresh capacity is useful
        }
