    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits, with a smooth non-linear penalty on dead space.
    let mut score = pr;

    // Non-linear coupling: residual squared normalized by capacity, weighted by progress.
    // Early on, dead space matters less (more items to come that may fill it);
    // late in the stream, unusable residuals are heavily penalized.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.3 + 0.9 * progress);

    // Perfect fit reward (smooth exponential rather than hard threshold).
    if post_residual == 0 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // Next item fits here: slight reward scaled by how well it fits.
            let slack = (pr - ni) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // Next item won't fit in this residual: penalize proportional to gap.
            let gap = (ni - pr) / cap;
            score += 8.0 * gap * gap * cap * (0.4 + 0.6 * progress);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        // Many candidates: mild penalty to prefer the tightest ones via base term.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // the item is large relative to capacity or the stream is early and
    // residuals across bins are small (fragmented state).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0).min(1.0);
        let item_ratio = item_size as f64 / cap;
        // New bin appeal: high for big items, decays as stream progresses,
        // and decreases when open bins have plenty of room.
        score = 30.0 * progress + 20.0 * frag - 35.0 * item_ratio + 0.5 * open_bins_count as f64;
        // Large items early: opening fresh bins is good (keeps small residuals
        // for small items later).
        score -= 10.0 * item_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic-ish preference for small post residual, smoothed
    let mut score = 2.0 * x * x - 1.5 * x;

    // Non-linear coupling with stream progress: early on, tolerate loose fits;
    // later, penalize dead space more aggressively.
    let progress_coupling = (x * x) * (0.5 + 2.0 * progress * (1.0 - 0.5 * progress));
    score += 3.0 * progress_coupling;

    // Smooth interaction: post residual vs mean residual (prefer bins tighter than the mean)
    let mean_norm = mean_residual / cap;
    score += 0.8 * (x - mean_norm) * (1.0 + x * x);

    // Lookahead term: reward if next item fits the post residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = x - nx;
        let s = 1.0 / (1.0 + (-8.0 * fits).exp());
        score -= 1.2 * s;
        // penalize if post residual is just barely too small for next item (dead space risk)
        let near_miss = (-6.0 * (fits + 0.05)).exp() * (fits < 0.0) as i32 as f64;
        score += 0.6 * near_miss * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 + x);
    }

    // Mild penalty for many open bins (encourage consolidation), scaled smoothly
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 + x);

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * (1.0 - progress) - 0.5 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo classes of post_residual.
    // Residuals divisible by 10 are "harmonic" (easily re-filled by items
    // sized 10..80 on a 10-grid); odd/prime-ish leftovers are dead space.
    let pr = post_residual;
    let harmonic = (pr % 10 == 0) as f64;
    let semi = (pr % 5 == 0 && pr % 10 != 0) as f64;
    score -= harmonic * 6.0;
    score += semi * 2.0;

    // Integer-division thresholds: very small leftovers are wasted space.
    let q = pr / 10; // decile class of leftover
    if q == 0 {
        score += 12.0; // dead space (<10) penalty
    } else if q <= 2 {
        score += 4.0 * (3 - q) as f64;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact fill bonus when next item perfectly consumes leftover
            if next_item_size == pr { score -= 15.0; }
            else { score -= 3.0 + 0.1 * (pr - next_item_size) as f64; }
        } else {
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, opened only if open bins
    // are all poor fits. Penalize slightly so tight fits win, but keep
    // attractive when open-bin residuals are tiny/fragmented.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.25 * open_bins_count as f64
            - 0.05 * mean_residual
            + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big item coming: fresh bin is valuable
        }
    }

    // Mild preference for filling fuller bins (tightness coupling).
    score -= 0.05 * (cap - post_residual as f64);

    score
}

