    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (small post residual) more than linear
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        } else if (bin_residual as f64) >= next_item_size as f64 {
            // placing here prevents next item from using this bin
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill_ratio * (open_bins_count as f64).ln().max(0.0);

    // Time horizon: early in stream, allow new bins / looser packing; later, pack tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * fill_ratio;

    // Penalize bins far below mean residual (wasteful choice among open bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: mild penalty so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0;
        // but early in stream or with lookahead mismatch, opening is cheaper
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) < next_item_size as f64 {
            score -= 15.0;
        }
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pn = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 18.0 * pn * pn * (1.0 - t) - 10.0 * pn * (1.0 - pn) * t;
    score += 8.0 * pn * pn * pn * t;

    // Penalize near-full-but-wasteful residuals more as stream advances
    score += 6.0 * (pn - 0.5) * (pn - 0.5) * t;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let diff = pr - ni;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - (diff / cap)) * (1.0 + t);
        } else {
            score += 9.0 * ((-diff) / cap) * (1.0 + t);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pn);
    }

    // Discourage spreading across many bins with high mean residual
    score += 0.6 * (open_bins_count as f64).sqrt() * (mean_residual / cap) * (1.0 - pn) * t;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction buckets (1/8 of capacity).
    let eighth = bin_capacity / 8;
    let item_class = item_size / eighth.max(1);
    let next_class = if next_item_size == 0 { 0 } else { next_item_size / eighth.max(1) };

    // Harmonic class of the residual AFTER placement: small post_residual classes
    // (tight fits) are good -> subtract reward proportional to class depth.
    let post_class = post_residual / eighth.max(1);
    score -= (8 - post_class.min(8)) as f64 * 3.0;

    // Exact integer-division complement: residual that is a multiple of a common
    // item quantum (gcd-like 10) is reusable -> reward it.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Dead space: residual too small for any plausible item (below min quantum 10)
    // is waste -> penalize strongly.
    if post_residual < 10 {
        score += 25.0;
    }

    // Modulo coupling: if the next item's size divides the post_residual evenly,
    // this bin chains perfectly -> big reward.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual % next_item_size == 0 {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits but not perfectly: mild reward scaled by leftover harmony.
        score -= 4.0;
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize proportionally to the shortfall class.
        score += ((next_item_size - post_residual) / eighth.max(1)) as f64 * 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make opening a new bin expensive unless the current bin
    // would be left with severe dead space or the fit is very loose.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the item is huge (top harmonic class), a fresh bin is natural.
        if item_class >= 7 {
            score -= 35.0;
        }
    }

    // Progress-aware pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.05;

    // Mean-residual harmony: prefer bins whose residual is close to the mean
    // (keeps the fleet balanced and leaves uniform reusable gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let post = post_residual as f64;

    // Dead-space penalty: gaps too small to hold even the smallest future item
    // (sizes >= 1, but penalize gaps below next_item_size strongly).
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // unusable for the known next item: harsh penalty
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
        if post_residual < 10 {
            // tiny dead space, likely unusable forever
            score += 8.0;
        }
    } else {
        // perfect closure: strong reward
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading; penalize new-bin usage.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as open_bins_count grows,
        // but allow it when the item is large and fits poorly elsewhere.
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score += 6.0 + 0.8 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer filling it (lower post_residual there).
    let dev = mean_residual - post;
    score -= 0.15 * dev;

    // Slight preference for bins with small residual overall (best-fit bias).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect 2-step lookahead matches: post_residual ≈ next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: next item exactly fills leftover
        } else if gap <= 5.0 {
            score -= 40.0 - gap * 4.0;
        } else if post_residual > next_item_size {
            // next item fits but leaves more slack: mild reward scaled by fit tightness
            score -= (next_item_size as f64 / post_residual as f64) * 15.0;
        } else {
            // next item cannot use the leftover: penalize dead space, worse if large
            score += (post_residual as f64 - next_item_size as f64).min(50.0) * 0.6;
        }
    }

    // Penalize tiny unusable residuals (dead space), scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * (1.5 + 2.0 * progress);
    }

    // Reward using bins with large residuals relative to the mean (balance load)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discard new-bin option unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 60 {
            score -= 30.0; // big items are fine to start fresh bins
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0; // fresh bin supports a good chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 12.0; // tiny unusable sliver is wasteful
        } else {
            score -= 0.4 * dead; // but large leftover space is flexible
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0; // perfect two-item packing
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
        // If next item is large and won't fit here afterwards, slight penalty.
        if next_item_size > post_residual && next_item_size > bin_capacity / 2 {
            score += 5.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        score += 30.0;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Late in the stream, opening new bins wastes capacity: penalize more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If mean residual is high, existing bins have room: avoid new bin.
        score += 0.2 * mean_residual;
        // Large items justify fresh bins more than small ones.
        score -= 0.25 * item_size as f64;
    }

    // Prefer filling bins that are already quite full (consolidation).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill * fill;

    // Mild pressure to spread across bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling of residual waste with stream progress:
    // early on, prefer filling loosely (low penalty on residual);
    // late, residual waste is more costly.
    let progress_weight = 2.0 * progress * progress;
    score += progress_weight * pr * (1.0 - progress);

    // Non-linear interaction: tight fits (small post_residual) reward scaled by item fraction
    let tightness = 1.0 - norm_pr;
    let item_frac = item_size as f64 / cap;
    score -= 4.0 * tightness * tightness * item_frac * (1.0 + progress);

    // Lookahead: reward bins whose post_residual can fit the next item (smooth, not piecewise)
    if next_item_size > 0 {
        let next_frac = next_item_size as f64 / cap;
        let fit_margin = (pr - next_item_size as f64) / cap;
        // smooth sigmoid-like coupling via tanh of margin
        score -= 6.0 * next_frac * (fit_margin.tanh() * 0.5 + 0.5);
        // penalize leaving a residual just below next item (near-miss waste)
        let near_miss = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 3.0 * near_miss * (1.0 - near_miss) * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Mild penalty when bin residual deviates from mean residual (balance smoothing),
    // smoothly scaled by number of open bins
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev / (1.0 + open_bins_count as f64).ln().max(1.0);

    // New-bin candidate shaping: empty bin should only win when residual of it
    // is genuinely better; add a smooth opening cost decaying with progress
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress * 0.5);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = post / cap;

    // Penalize dead space in awkward harmonic classes (residuals that few item sizes can fill)
    // Items are 1..=100, so residuals in [1,100] may be fillable; larger residuals less "dead"
    if post > 0.0 && post < 50.0 {
        // small residual: risk of dead space; penalize unless next item fits exactly
        score += 15.0 * (1.0 - frac * 2.0);
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 200.0; // next item exactly fills this bin
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 30.0; // next item can still use leftover
        } else if next_item_size > 0 {
            score += 25.0; // leftover likely wasted
        }
    } else if post >= 50.0 && post < 100.0 {
        // mid-range residual: still quite usable, mild reward
        score -= 10.0;
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 10.0; // next item won't fit here anyway, fine
        }
    }

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // decade class
    match class {
        0 => score += 20.0,          // 0-9: near dead space
        1 => score += 8.0,           // 10-19
        2 | 3 => score -= 5.0,       // 20-39: good target zone
        4 | 5 => score -= 8.0,       // 40-59: very usable
        _ => {}
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // base penalty so open bins are preferred unless they're bad
        score += 60.0;
        // early in stream, new bins are cheap to open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // if many open bins with high mean residual, prefer packing into them
        if mean_residual > 50.0 {
            score += 20.0;
        }
        // if open bins are nearly full, opening a new bin is natural
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 25.0;
        }
        // if next item is large and current item is small, new bin keeps flexibility
        if next_item_size > 0 && next_item_size > 60 && item_size < 30 {
            score -= 15.0;
        }
    }

    // Slight preference to balance load across bins when many are open
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are almost unusable
    // (items are >= 1, but typical sizes create stranded slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last chance: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge and would
    // strand the current bin's residual badly.
    if bin_residual == bin_capacity {
        let stranded = bin_residual as f64 - item_size as f64;
        // Opening a new bin is only good if the current item is large (would
        // nearly fill a fresh bin) and residual elsewhere is fragmented.
        score = 150.0
            - 0.8 * stranded
            + 5.0 * open_bins_count as f64
            - 30.0 * fill_ratio;
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 10.0; // fresh bin could also host the next item
        }
    } else {
        // Open-bin pressure: prefer reusing bins when many are open.
        score += 1.5 * open_bins_count as f64;

        // Lookahead synergy: if next item fits the post residual, reward this placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 25.0; // would strand gap the next item can't use
        }

        // Prefer bins tighter than average (keep large residuals for later items).
        if (bin_residual as f64) > mean_residual {
            score += 4.0;
        } else {
            score -= 4.0;
        }
    }

    // Early in the stream, allow slightly more freedom to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: if the next item fits exactly into the post-residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to wasted potential.
        let gap = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
        score += 8.0 * (gap / bin_capacity as f64);
    }

    // Perfect fit reward: residual consumed entirely.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Compare post_residual against mean residual: leaving less than average is good.
    score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (dead space) unless next item may use them.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer tighter packing (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    let t = step_index as f64 / total_items.max(1) as f64;
    let horizon = (1.0 - t).clamp(0.05, 1.0);
    let usable = if post_residual < 10 { 0.0 } else { post_residual as f64 };
    score += 0.35 * usable * horizon;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; mild penalty if we leave awkward residue.
        score += 6.0 * horizon;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins -> consolidate; few -> spreading is ok.
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / 20.0)).min(3.0);
    score -= 2.0 * pressure * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual is below mean (fill emptier slots first when tight).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let best_open_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 18.0 * best_open_fit;
        score += 10.0 * (1.0 - horizon);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let post_residual = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Normalized post residual
    let pr = post_residual / cap;

    // Smooth non-linear penalty on wasted space: quadratic-quartic coupling
    let mut score = post_residual + 40.0 * pr * pr + 25.0 * pr * pr * pr * pr;

    // Stream-progress coupling: later in stream, punish residual more aggressively (smooth polynomial)
    let prog_term = 1.0 + progress * progress;
    score *= prog_term;

    // Interaction between post residual and mean residual: avoid bins far above/below mean
    let dev = (post_residual - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus (smoothly encoded): strongly reward the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // mild penalty scaled by abundance of alternatives
        score += 3.0 * ((fitting_bins_count as f64) - 1.0).sqrt();
    }

    // Lookahead coupling: reward bins whose post residual fits the next item (smooth gaussian-like)
    if next_item_size > 0 {
        let gap = post_residual - next_item_size as f64;
        if gap >= 0.0 {
            let x = gap / cap;
            score -= 20.0 * (-x * x * 8.0).exp();
        } else {
            // penalize leaving residual that is unusable by next item, smoothly
            score += 10.0 * (1.0 - (-(-gap / cap) * 4.0).exp());
        }
    }

    // Slight preference for consolidating into fewer bins as stream progresses
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left

    // Dead-space penalty: residuals that are tiny are nearly worthless
    if post_residual <= bin_capacity / 10 {
        score += 40.0;
    } else if post_residual <= bin_capacity / 4 {
        score += 18.0;
    }

    // Reward "perfect" fits: post_residual in friendly harmonic classes
    // (multiples of 10 and of capacity/2 are easiest to fill later)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual == bin_capacity / 2 {
        score -= 15.0;
    }
    if post_residual == 0 {
        score -= 60.0;
    }

    // Integer-division threshold classes on post_residual
    let class = post_residual / (bin_capacity / 5); // 0..=5 classes
    score += class as f64 * 4.0; // prefer bins in lower (tighter) classes

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match is gold
            if post_residual % next_item_size.max(1) == 0 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // last item: any bin that fits is fine, prefer tightest
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer using existing bins over opening new ones as stream progresses
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize mildly, more so early on
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 25.0 * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (fill emptier bins first
    // keeps tight bins for tight items)
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Modulo coupling between item size and residual class
    if (item_size + post_residual) % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit is the best possible outcome.
        score -= 200.0;
    } else {
        // Larger leftover space is mildly rewarded (still usable).
        score -= (post_residual as f64).sqrt() * 2.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / bins accumulate.
        score += 25.0 + 50.0 * progress + 1.5 * open_bins_count as f64;
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= 0.8 * open_bins_count as f64;
    }

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would be blocked by a tiny dead gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 55.0; // next item will perfectly close this bin
        } else if gap <= 5 {
            score -= 25.0;
        } else if gap <= 15 {
            score -= 8.0;
        } else {
            // next item cannot come close to filling leftover: penalize dead space
            score += (gap as f64 - 15.0).min(30.0) * 0.4;
        }
        // If next item is larger than post residual, it must go elsewhere;
        // mildly penalize leaving a residue nothing can use.
        if next_item_size as f64 > post_residual as f64 {
            score += 5.0;
        }
    }

    // Compare post residual to mean residual: leaving more than average waste is bad.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to remaining stream or fits are poor.
    if bin_residual == bin_capacity {
        score += 70.0;
        if item_size >= 50 {
            score -= 35.0; // large items are fine starting fresh bins
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Late in the stream, avoid opening new bins (unlikely to be filled).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual is already the base; amplify small dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fill is ideal
    } else if post_residual < 10 {
        score -= 25.0; // nearly perfect
    } else {
        // penalize large dead space non-linearly
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 30.0;
    }

    // Lookahead coupling: bonus if next item fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 4.0; // dead space unusable by next item
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: empty bin is a fallback; penalize it mildly so
    // decent fits in open bins win, but allow it when open-bin fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // prefer opening a new bin early in the stream when few bins exist
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Global residual pressure: if mean residual is low, squeeze existing bins harder.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Prefer bins whose residual is closest to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    // Mild consolidation pressure when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly convex so small residuals are favored increasingly
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of residual tightness with stream progress:
    // early on, prefer larger residuals (flexibility); later, prefer tight fits.
    let flex = norm_pr * (1.0 - norm_pr); // peaks at mid residual
    score -= 25.0 * flex * (1.0 - progress);
    score += 20.0 * flex * progress;

    // Dead-space penalty: quadratic in unusable residual relative to item sizes
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap
    } else {
        0.0
    };
    score += 40.0 * dead * (0.5 + 0.5 * progress);

    // Reward last-chance bins smoothly (avoid hard piecewise)
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 12.0 * last_chance * (1.0 - norm_pr);

    // Slight preference for bins tighter than mean residual
    score += 3.0 * ((pr - mean_residual) / cap);

    // New-bin candidate: penalize mildly, less as stream progresses
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter of the bin it falls in
    let quarter = bin_capacity / 4;
    let post = post_residual as u32;

    // Penalize dead space in the "useless" low quarter (0..25) more strongly,
    // reward residuals that stay in reusable harmonic bands (25..50, 50..75)
    if post < quarter {
        score += (quarter - post) as f64 * 0.7;
    } else if post < 2 * quarter {
        score -= 3.0;
    } else if post < 3 * quarter {
        score -= 6.0;
    }

    // Modulo-10 class: residuals divisible by 10 are "harmonic" with typical item sizes
    if post % 10 == 0 && post > 0 {
        score -= 2.5;
    } else if post % 5 == 0 {
        score -= 1.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post {
        if next_item_size == post {
            score -= 15.0; // perfect closure
        } else {
            score -= (next_item_size as f64) * 0.15;
        }
    } else if next_item_size > post && next_item_size > 0 {
        // next item cannot use the remainder: penalize proportionally to wasted space
        score += (post as f64) * 0.25;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: keep it neutral-ish, but prefer opening a new bin when
    // the item is large and current residuals are already fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = cap - item_size as f64 + fragmentation * 0.3 - progress * 5.0;
        if item_size > 3 * quarter {
            score -= 10.0; // large items deserve a fresh bin
        }
    }

    // Tie-break by tightness of fit
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post_residual gaps are "dead" if no
    // future item can plausibly fit. Penalize gaps below the smallest useful
    // size with a strong non-linear surcharge.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // Perfect fit: heavily reward exact closures.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Lookahead won't fit here: mild penalty unless residual is large
            // enough to be generically reusable.
            if post_residual < 40 {
                score += 6.0;
            }
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 20.0;

    // Open-bin pressure: with many open bins, prefer compacting into existing
    // ones; when this is the LAST fitting bin, strongly discourage opening a
    // new bin (i.e., favor this bin).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5;

    if fitting_bins_count == 1 {
        // This is the last chance bin before opening a new one.
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: make an empty bin moderately unattractive unless the
    // current item is large (would leave a big residual elsewhere anyway) or
    // the item barely fits any open bin.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        if big_item || fitting_bins_count == 0 {
            score -= 10.0;
        } else {
            score += 25.0 + 0.3 * mean_residual;
        }
    }

    // Prefer bins whose residual is below average (more filled bins) mildly.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; mild superlinear penalty on wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    if next_item_size > 0 {
        // Perfect 2-step fill: this bin will be exactly filled after next item.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits with small leftover -> strong lookahead reward.
        else if next_item_size <= post_residual {
            let after2 = post_residual - next_item_size;
            score -= 40.0 - 0.5 * after2 as f64;
            if after2 == 0 {
                score -= 25.0;
            }
        }
        // Next item will NOT fit here -> penalize leaving medium dead space.
        else {
            let dead = post_residual as f64;
            let rel = dead / (bin_capacity as f64);
            // Dead space that is too small for typical items is very bad.
            if dead < 10.0 {
                score += 15.0 * (10.0 - dead);
            }
            score += 20.0 * rel * rel;
        }
    } else {
        // Last item: just minimize waste.
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins whose post_residual is close to mean
    // (keeps residual profile homogeneous, avoids stranding outliers).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, use it before opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: discourage unless current bin is a poor fit
    // (item would leave a large awkward residual in an existing bin).
    if bin_residual == bin_capacity {
        score += 45.0;
        // Slightly cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If many bins already open and mean residual is large, opening new is worse.
        score += 0.15 * mean_residual;
        // If next item is large and would fit an empty bin well, mildly favor new bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // extra reward for near-perfect chain fit
            let chain_gap = post_residual - next_item_size;
            if chain_gap < 10 {
                score -= 10.0;
            }
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing current item blocks the next one in this bin
            score += 12.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer the one wasting least
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a bin is expensive; make the empty bin
    // attractive only when the item fits poorly everywhere else or bins are scarce.
    if bin_residual == bin_capacity {
        // base new-bin cost
        score += 45.0;
        // cheaper to open early in the stream (long horizon amortizes)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
        // if open bins are few, opening is natural
        if open_bins_count <= 2 {
            score -= 20.0;
        }
        // if no other bin fits (fitting_bins_count counts only open bins), opening is fine
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // large items prefer fresh bins (less fragmentation risk)
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Global pressure: if mean residual across bins is low, conserve existing bins harder.
    let mean_res_c = mean_residual.clamp(0.0, bin_capacity as f64);
    let scarcity = 1.0 - mean_res_c / (bin_capacity as f64);
    score += 8.0 * scarcity * (post_residual as f64 / 100.0);

    // Prefer bins whose residual is close to item (best-fit flavor) with non-linear coupling.
    let fit_gap = (bin_residual as f64 - item_size as f64) / 100.0;
    score += 20.0 * fit_gap * fit_gap;

    // Late in the stream, avoid opening new bins; consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.85 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Mild penalty on very large post-residuals that invite fragmentation
    if post_residual > 50 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits, with a smooth non-linear penalty on dead space.
    let mut score = pr;

    // Non-linear coupling: residual squared normalized by capacity, weighted by progress.
    // Early on, dead space matters less (more items to come that may fill it);
    // late in the stream, unusable residuals are heavily penalized.
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.3 + 0.9 * progress);

    // Perfect fit reward (smooth exponential rather than hard threshold).
    if post_residual == 0 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // Next item fits here: slight reward scaled by how well it fits.
            let slack = (pr - ni) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // Next item won't fit in this residual: penalize proportional to gap.
            let gap = (ni - pr) / cap;
            score += 8.0 * gap * gap * cap * (0.4 + 0.6 * progress);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        // Many candidates: mild penalty to prefer the tightest ones via base term.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // the item is large relative to capacity or the stream is early and
    // residuals across bins are small (fragmented state).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0).min(1.0);
        let item_ratio = item_size as f64 / cap;
        // New bin appeal: high for big items, decays as stream progresses,
        // and decreases when open bins have plenty of room.
        score = 30.0 * progress + 20.0 * frag - 35.0 * item_ratio + 0.5 * open_bins_count as f64;
        // Large items early: opening fresh bins is good (keeps small residuals
        // for small items later).
        score -= 10.0 * item_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward small, "closed" residuals ---
    // Residuals that are exact divisors of capacity (harmonic classes) are
    // highly reusable: 100, 50, 25, 20, 10, 5, 4, 2, 1.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut harmonic_bonus = 0.0;
    if post_residual > 0 {
        if cap % (post_residual as f64) == 0.0 {
            harmonic_bonus += 18.0; // perfectly reusable residual class
        } else if post_residual <= 5 {
            harmonic_bonus += 14.0; // near-closed bin
        } else if post_residual % 10 == 0 {
            harmonic_bonus += 8.0;  // decade-aligned residual
        }
    } else {
        harmonic_bonus += 22.0; // perfectly closed bin is ideal
    }
    score -= harmonic_bonus;

    // --- Lookahead coupling: does post_residual fit next_item_size? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving a residual that chains into the next item,
        // especially when the leftover after the chain is small/harmonic.
        let chain_left = post_residual - next_item_size;
        score -= 10.0 + 0.15 * (chain_left as f64).min(30.0);
        if chain_left == 0 {
            score -= 12.0; // perfect two-item closure
        } else if bin_capacity as u32 % chain_left.max(1) == 0 {
            score -= 6.0; // harmonic class after chaining
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize stranding a residual too small for the next item
        // unless it is already tiny (dead space anyway).
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
            if post_residual < 10 {
                score -= 4.0; // tiny dead space is acceptable
            }
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when existing residuals are poor
        // (fragmented) or no open bin fits well. Base cost keeps it from being
        // chosen when a decent fit exists.
        score += 30.0;
        // Penalize new bins when many open bins exist with usable space.
        score += 0.8 * open_bins_count as f64;
        // If mean residual is large and this item is small, prefer reusing.
        if mean_residual > item_size as f64 * 1.5 {
            score += 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Prefer filling bins with larger residual usage (tight fits).
        let tightness = item_size as f64 / cap;
        score -= 8.0 * tightness;
        // Prefer bins whose residual is below the mean (consolidate fullness).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // --- Integer-division threshold on post_residual: bucketize dead space ---
    // Discourage leaving residuals in awkward mid ranges (11..19, 31..39, etc.)
    let awkward = (post_residual / 10) % 2 == 1 && post_residual % 10 != 0 && post_residual > 10;
    if awkward {
        score += 5.0;
    }

    // Small tie-breaker toward earlier (presumably fuller) bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that still leave room for typical next items.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // prefer filling existing bins tighter.
    let pressure = open_bins_count as f64 * 0.5;
    if bin_residual < bin_capacity {
        score -= pressure * (item_size as f64 / bin_residual.max(1) as f64);
    } else {
        // New-bin candidate: penalize opening a bin unless current bins are quite full
        // or the fit elsewhere would be terrible.
        score += pressure * 2.0;
        if mean_residual > (bin_capacity as f64) * 0.35 {
            score += 40.0;
        }
    }

    // Late in the stream, tighten packing (favor tight fits even more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact match with next item ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item fills this bin exactly afterwards
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // If next item cannot fit in post_residual, this placement leaves dead space for the lookahead
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // --- Perfect fit now ---
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0; // tiny dead space is nearly perfect
    }

    // --- Relative to mean residual: prefer bins tighter than average ---
    score += (post_residual as f64 - mean_residual) * 0.3;

    // --- Last chance bin: strongly prefer using it to avoid opening a bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New bin candidate: penalize unless nothing fits well ---
    if bin_residual == bin_capacity {
        score += 35.0;
        // Open a new bin if the item is large and no open bin fits
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size < 30 && progress > 0.7 {
            score += 20.0;
        }
    }

    // --- Prefer filling larger residual bins with large items ---
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (20 - post_residual) as f64;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.2 * next_item_size as f64;
        } else {
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global pressure: many open bins -> favor filling existing ones (avoid new bins).
    score += 0.15 * open_bins_count as f64;

    // Mean residual coupling: prefer bins with residual close to mean (balanced),
    // but extreme small residual bins should be drained first.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time horizon: early in stream, be more exploratory (favor new bins slightly);
    // late in stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 5.0 - t * 5.0;

    // New-bin candidate handling: empty bin gets a mild penalty so it's chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: smooth polynomial in post_residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Progress coupling: later in stream, penalize large residuals more (tighten packing)
    let progress_coupling = progress * norm_pr * (1.0 - norm_pr) * 40.0;
    score += progress_coupling;

    // Interaction of post_residual with mean residual: prefer bins near mean deviation
    let dev = (pr as f64 - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // penalize creating residual that next item cannot use
        score += 5.0 * (1.0 - pr / (next_item_size as f64).max(1.0)).max(0.0);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Dead-space penalty grows when residual falls into "unusable" classes.
        // Class residual into deciles of capacity; small residuals (<10) are dead space.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 10.0;
        }
        // Modulo-10 harmonic: residuals that are multiples of 10 keep alignment
        // with typical item sizes, reward them mildly.
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else {
            score += (10 - (post_residual % 10)) as f64 * 0.8;
        }
    }

    // Pairing bonus: if next item exactly fills post_residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: reward proportional to how much would remain after.
        let next_post = post_residual - next_item_size;
        if next_post < 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving large trapped residual.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bins
    // would create bad dead space or are congested.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = (bin_capacity as f64) * 0.5;
        // If many open bins are underutilized, discourage a new bin.
        if mean_residual > 50.0 {
            score += 80.0;
        }
        // If this bin is the only fitting option elsewhere, opening is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer tighter (fuller) bins generally: reward low residual fraction.
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score -= (1.0 - residual_frac) * 30.0;

    // Late-stream consolidation: near the end, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 && post_residual >= 10 {
        score += 18.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    } else {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward using nearly-full bins (large bin_residual used well).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that barely fails the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: it should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, growing with stream progress.
        score = 45.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64);
        score += 2.5 * open_bins_count as f64;
        // If the next item is large, a fresh bin is more attractive.
        score -= 0.15 * next_item_size as f64;
        // If only one bin fits, avoid opening a new one.
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
