pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // Small dead space is nearly perfect.
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 12.0;
    }

    // Penalize creating dead space that no future item (min size 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder; slight penalty for tight fits that strand space.
            let stranded = post_residual as f64;
            if stranded > 0.0 && stranded < next_item_size as f64 {
                score += 0.15 * stranded;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins below mean residual (fill emptier bins first to consolidate).
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev;

    // Time horizon: early in the stream, be more selective (favor tight fits);
    // late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual >= item_size) as i32 as f64;

    // New-bin candidate handling: make empty bins attractive only when current
    // bin would leave unusable residue or when many bins are already open.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 0 && post_residual < 10;
        if bad_fit {
            score -= 35.0; // prefer fresh bin over creating dead space
        } else {
            score += 15.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: post_residual weighted by progress polynomial
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score *= 1.0 + 0.6 * progress_poly * norm_post;

    // Penalize large dead space quadratically, scaled by stream position
    score += 8.0 * norm_post * norm_post * (0.5 + progress) * cap;

    // Reward tight fits: low post_residual relative to item size
    score -= 20.0 * norm_item * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mild penalty early, stronger late (prefer consolidation over time)
    if bin_residual == bin_capacity {
        score += 10.0 * (0.3 + 0.7 * progress);
        // but allow new bin if post_residual after placement would be tiny relative to next item
        if next_item_size > 0 && (next_item_size as f64) > post + 0.5 * mean_residual {
            score -= 12.0;
        }
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - (gap / cap).abs()) * (1.0 - progress);
        } else {
            score += 4.0 * (-gap / cap);
        }
    }

    // Coupling with mean residual: prefer bins near the mean (balanced packing)
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "reusable"
    // class (divisible by 5, i.e. can host small items from a wide range) are
