    let post_i = post_residual as i64;
    let dead_space_penalty = if post_i == 0 {
        -30.0 // perfect fit: strongly reward
    } else if post_i % 10 == 0 {
        0.0 // clean class, mild reward
    } else if post_i % 5 == 0 {
        2.0
    } else {
        6.0 // awkward leftover
    };
    score += dead_space_penalty;

    // Lookahead: does the next item fit into this bin's post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact-chain reward scaled by how snug the chain is
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.08 * chain_slack;
            if post_residual == next_item_size {
                score -= 8.0; // perfect chaining
            }
        } else {
            // next item won't fit here; penalize more if leftover is tiny (wasted)
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins
    // are congested or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / 10.0;
        // base cost of opening a new bin
        score += 25.0;
        // but cheaper to open when many bins are open and mean residual is low
        score -= congestion * 2.0 + progress * 5.0;
        if mean_residual < item_size as f64 {
            score -= 10.0; // open bins can't help much
        }
    }

    // Prefer filling larger-residual bins when item is big (harmonic fraction of capacity)
    let item_frac = item_size as f64 / cap;
    if item_frac > 0.6 {
        score += 0.05 * (bin_residual as f64 - post_residual as f64);
    }

    // Small tie-breaker toward bins closest in residual to mean (balanced usage)
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small to hold the smallest item are worthless.
    let min_item = 1u32;
    if post_residual < min_item && post_residual > 0 {
        // Perfect fill is ideal, but a 1..3 gap is nearly dead too.
        score += 12.0;
    } else if post_residual > 0 && post_residual < 10 {
        // Small unusable sliver: heavy penalty.
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (small relative waste).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Dead-space penalty scales with how unusable the gap is for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Gap that can host the next item is valuable.
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins when waste is comparable.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when the item fits terribly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // But if the current bin would leave a large awkward residual, opening fresh is fine.
        if post_residual > 0 && post_residual < item_size.min(20) {
            score -= 20.0;
        }
        score += 0.5 * mean_residual; // existing bins have plenty of room; prefer them
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: waste below 20 is heavily discounted.
    if post_residual < 20 {
        score -= 30.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
    }
    // Penalize leaving a sliver that the next item cannot use (dead space risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last chance: if this is the only bin that fits, using it avoids opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it expensive, but cheaper when existing residuals
    // are large (poor fits likely) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0;
        score -= 0.15 * mean_residual;
        score -= 10.0 * progress;
        // If the item would leave a big hole in any existing bin, new bin is more attractive.
        if post_residual >= 40 {
            score -= 10.0;
        }
        // Don't open a new bin for a tiny item early on.
        if item_size < 30 && progress < 0.5 {
            score += 15.0;
        }
    }

    // Mild penalty for fragmenting bins that still have lots of room when many bins are open.
    if bin_residual != bin_capacity && post_residual > 50 && open_bins_count > 5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Smooth polynomial coupling: penalize large residuals more as stream progresses
    let norm_pr = pr / cap; // in [0,1]
    let coupling = (norm_pr * norm_pr) * (1.0 + 2.0 * progress) * cap;
    score += coupling;

    // Penalize bins with residual far above mean residual (dead space) — smooth quadratic
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Reward near-perfect fits with a smooth saturating bonus
    let fit_quality = 1.0 - norm_pr;
    score -= 6.0 * fit_quality * fit_quality;

    // Last-chance bin: strong smooth bonus to use it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item won't fit post-residual (smooth margin term)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            let g = gap / cap;
            score += 4.0 * g * g * cap;
        } else {
            // reward leaving room that exactly-ish fits next item
            let g = (-gap) / cap;
            score -= 3.0 * (1.0 - g) * (1.0 - g);
        }
    }

    // Mild pressure to prefer reusing bins over opening new ones as bins accumulate
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common
    // GCDs (10, 20, 25, 50) are more likely to be filled by future items,
    // so reward them; odd/prime residues create dead space, penalize them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 50 == 0 {
        score -= 25.0;
    } else if pr % 25 == 0 {
        score -= 15.0;
    } else if pr % 20 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    } else {
        score += 6.0; // non-round residue: poor future compatibility
    }

    // Small dead space (< 10, the minimum item size) is pure waste.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Complementary fit: does the next item land exactly (or near) in the
    // post-residual? Harmonic match between post_residual and next_item_size.
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 35.0; // next item fills this bin exactly
        } else if diff % 10 == 0 {
            score -= 10.0;
        } else {
            score += (diff as f64) * 0.15;
        }
    } else if next_item_size > pr {
        // Next item cannot use this bin's residue anyway; mildly neutral.
        score += 3.0;
    }

    // Tightness reward: item filling most of the bin is good.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 15.0;

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Brand-new bin candidate: only attractive when current bins are nearly
    // full on average or the item is huge and fits nothing well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual / bin_capacity as f64;
        let pressure = (1.0 - crowded).clamp(0.0, 1.0);
        // Base cost of opening a new bin, discounted by crowding pressure
        // and by how "harmonically awkward" the item is (large items).
        let awkward = (item_size as f64 / 100.0).powi(2);
        score += 70.0 - 55.0 * pressure - 20.0 * awkward + 10.0 * progress;
        // If open bins exist and fit the item comfortably, discourage new bin.
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit core),
    // modulated by harmonic class alignment of bin_residual.
    let gap = bin_residual as f64 - item_size as f64;
    score += gap * 0.05;
    if bin_residual % 10 == 0 {
        score -= 3.0;
    }

    // Early stream: consolidate into fewer bins to keep flexibility.
    if open_bins_count > (step_index as f64 / 20.0).ceil() as usize {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let mut score = post;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (or the lookahead item) are dead space.
    let min_useful = if next_item_size > 0 { next_item_size.min(10) as f64 } else { 10.0 };
    if post > 0.0 && post < min_useful {
        score += 40.0 + (min_useful - post) * 3.0; // unusable sliver penalty
    }

    // Perfect fit bonus: residual exactly consumed.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead synergy: if the next item fits exactly into the new residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // residual still usable by next item
    } else if next_item_size > 0 && post_residual > 0 {
        // residual too small for lookahead: mild penalty scaled by gap
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // New-bin candidate: empty bin should only win when the fit is clean
    // (large item leaving little waste) or all existing fits are poor.
    if bin_residual == bin_capacity {
        let waste_ratio = post / cap;
        score += 15.0 + waste_ratio * 60.0; // penalize opening a bin for small items
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Reward using bins whose residual is close to the item (best fit).
        let tightness = 1.0 - (post / (bin_residual.max(1) as f64));
        score -= tightness * 10.0;
    }

    // Mild preference for bins below mean residual (rebalance laggards).
    score += (post - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward a bin whose post_residual
    // exactly accommodates the next item (perfect chain), mildly reward
    // near-matches, and penalize dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Dead space: cannot host next item; penalize proportionally to waste.
            let waste = post_residual as f64;
            score += 40.0 * (waste / bin_capacity as f64);
        }
    }

    // Compare against mean residual: bins tighter than the mean are better
    // targets (they concentrate packing), loose bins are deprioritized.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when nothing fits well; make it
    // slightly worse than a decent existing fit so it wins only on poor fits.
    if bin_residual == bin_capacity {
        score += 80.0;
        // Late in the stream, opening fresh bins is riskier (fewer chances to fill).
        let progress = step_index as f64 / total_items as f64;
        score += 40.0 * progress;
    }

    // Prefer bins with small residuals overall (best-fit flavor) with a
    // non-linear squash so tiny residuals dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward tight fits (small post_residual relative to item size)
    let tightness = 1.0 - (item_size as f64) / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * (item_size as f64);

    // Lookahead: penalize leaving a residual that exactly wastes next item's fit
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            // next item can still fit here: reward a bit
            score -= 3.0;
            // reward if next item would fill nearly perfectly after this one
            let two_step = post - next;
            score -= 2.0 * (1.0 - two_step / cap);
        } else {
            // dead space for the next item: penalize proportionally to gap
            let gap = next - post;
            score += 0.6 * gap.min(cap);
        }
    } else {
        // last item: prefer minimal post_residual strongly
        score += 0.0;
        score -= 5.0 * (1.0 - post / cap);
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin is costly
    if fitting_bins_count <= 1 {
        score -= 12.0;
    } else if fitting_bins_count > 4 {
        score += 1.5 * (fitting_bins_count as f64 - 4.0);
    }

    // Time horizon: early in stream, tolerate new bins more; late, consolidate
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 4.0 * (post / cap);       // early: penalize leftovers mildly
    score -= t * 6.0 * (1.0 - post / cap);          // late: reward dense packing

    // Global state: many open bins with low mean residual -> avoid fragmentation
    if open_bins_count > 3 && mean_residual < 20.0 {
        score += 3.0;
    }
    // Prefer bins with residual far from mean (balance across bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make empty bins moderately attractive only for large items
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / cap) > 0.6;
        if large { score -= 2.0; } else { score += 6.0; }
    }

    // Penalize tiny unusable residuals (< 10) as dead space
    if post_residual < 10 && post_residual > 0 {
        score += 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Core: convex penalty on leftover space, sharpened as stream progresses.
    let mut score = pr.powf(1.4 + 0.6 * progress);

    // Non-linear coupling: dead space matters more when mean residual is low
    // (bins elsewhere are tight, so waste here is costly).
    let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += 12.0 * norm_pr * norm_pr * (1.0 + tightness);

    // Smooth progress-weighted quadratic term.
    score += 20.0 * progress * progress * norm_pr * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: reward leaving space the next item can use; penalize blocking it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let snug = 1.0 - ((pr - ni) / cap).abs();
            score -= 8.0 + 10.0 * snug * snug;
        } else {
            score += 6.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // New-bin candidate: keep it neutral-ish early, increasingly unattractive later,
    // unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.5 * progress) + 25.0 * progress;
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space.
    let q = bin_capacity / 4; // 25
    let post_class = post_residual / q; // 0..4
    let class_penalty: f64 = match post_class {
        0 => -30.0, // near-perfect fill
        1 => 0.0,   // leftover 25..49
        2 => 8.0,   // leftover 50..74
        _ => 18.0,  // large waste
    };
    score += class_penalty;

    // Fine-grained dead-space: small residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the NEXT item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic class match: next item leaves a class-0 residual again
            let post2 = post_residual - next_item_size;
            if post2 / q == 0 && post2 > 0 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers more
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are all poor fits or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        // base preference for reusing open bins
        score += 20.0;
        // but for very large items, a fresh bin is attractive
        if item_size * 4 >= bin_capacity * 3 {
            score -= 25.0;
        }
        // late in the stream, discourage opening extra bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
        // if many open bins have small residuals, new bin is fine
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Prefer tighter existing bins: closeness of fit rewarded.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    // Modulo harmonic: residuals divisible by common item classes (10s) are reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for any item
    // (sizes 1..=100, so anything < 1 is impossible; but treat tiny gaps
    // relative to typical item sizes as near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 250.0 * (10 - post_residual) as f64;
    }

    // Penalize moderate gaps that likely become dead space for large items.
    if post_residual >= 10 && post_residual < 25 {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad gaps.
    if bin_residual == bin_capacity {
        score += 120.0 + 5.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 400.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins.
    score += 8.0 * open_bins_count as f64;

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0;
        } else if post_residual > 0 {
            score += 30.0;
        }
    }

    // Late in the stream: tighten packing, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (mean_residual / bin_capacity.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-residual (best-fit core)
    score += post_residual as f64 * 0.05;

    // 2-step lookahead: reward exact pairing with next item (perfect fill later)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0; // exact match: this bin + next item fills perfectly
        } else if post_residual >= next_item_size {
            // next item fits here afterwards; reward closeness of the pair-fill
            let pair_waste = (post_residual as f64 - nxt).abs();
            score -= 40.0 / (1.0 + pair_waste);
        } else {
            // next item cannot follow in this bin: penalize proportionally to leftover
            score += 15.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce space
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Dead-space penalty: tiny unusable leftovers (cannot host min item 1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // opening a new bin wastes the residual of this empty slot's siblings;
        // make it unattractive unless it's a perfect fit for item + lookahead
        score += 35.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host the pair cleanly
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    // Late-stream consolidation: fewer open bins preferred near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (open_bins_count as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item (<= 50).
    if post_residual > 0 && post_residual < 20 {
        score += 12.0; // unusable sliver
    } else if post_residual >= 20 && post_residual < 40 {
        score += 4.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect follow-up pairing
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mildly penalize wasting large residuals
            score += 0.03 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; shrinks as stream progresses
        // (less point conserving late) and with congestion.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 18.0 + 20.0 * (1.0 - progress);
        if open_bins_count > 4 {
            open_cost += 2.0 * (open_bins_count as f64 - 4.0).min(10.0);
        }
        // If only this new bin fits (fitting_bins_count==1 includes us), make it cheap.
        if fitting_bins_count <= 1 {
            open_cost -= 30.0;
        }
        // Large items (>= 60) fit best in fresh bins.
        if item_size >= 60 {
            open_cost -= 8.0;
        }
        score = open_cost + post_residual as f64;
    }

    // Prefer bins whose residual is far below mean (consolidating small leftovers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild time horizon shaping: keep flexibility early, exploit late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;

    // Core: reward tight fits via non-linear polynomial in post_residual
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth quadratic coupling: post_residual vs stream progress
    score += 12.0 * pr_norm * (1.0 - progress) * pr_norm;
    score -= 15.0 * pr_norm * progress * (1.0 - pr_norm);

    // Cubic interaction: small post-residual late in stream is valuable
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm) * progress;

    // Penalize dead space relative to mean residual (smooth interaction)
    let dead = (pr as f64 - mean_residual) / cap;
    score += 6.0 * dead * dead * cap;

    // Last-chance bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * fit * (1.0 - progress);
    }

    // Lookahead coupling: smooth reward if next item fits post-residual
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap) * (1.0 - gap) * (0.5 + 0.5 * progress);
        } else {
            score += 3.0 * gap * gap * cap;
        }
    }

    // Mild penalty for bin proliferation early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residues mod 10 create "dead space" classes ---
    let r = post_residual % 10;
    let dead_penalty: f64 = match r {
        0 => -12.0,                    // perfectly harmonic residual (divisible into 10-blocks)
        1..=3 => 10.0 + 4.0 * r as f64, // tiny slivers are near-unusable
        4..=6 => 2.0,                   // mildly awkward
        _ => -3.0,                      // 7..=9 can still host a small item (>=10 not always, but mod-friendly)
    };
    score += dead_penalty;

    // Integer-division harmonic: how many full 10-units remain
    let quanta = post_residual / 10;
    score -= 2.5 * quanta as f64;

    // --- Coupling with the lookahead item (k=2) ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // This bin can also host the next item: strong reward for a chain placement.
        let chain_fit_quality = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.25 * chain_fit_quality;
        // Harmonic bonus if post_residual after the chain is again mod-10 clean
        let chain_res = (post_residual - next_item_size) % 10;
        if chain_res == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: penalize leaving a stranded residual
        score += 6.0 + 0.15 * post_residual as f64;
    }

    // --- Exact-fit reward ---
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for big items or when no good harmonic fit exists.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Prefer fresh bins for large items (little dead space created)
        score -= 10.0 + 25.0 * item_frac;
        // Late in the stream, prefer consolidation into existing bins
        score += 12.0 * progress;
        // If many bins are open with slack, discourage opening yet another
        score += 1.5 * open_bins_count as f64;
        // If mean residual across open bins is comfortable, prefer existing bins
        score += 0.2 * mean_residual;
    }

    // --- Mild pressure to keep mean residual balanced ---
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * deviation;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (<10) are unusable -> heavy penalty
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal
        score -= 50.0;
    } else {
        // Usable leftover: mild reward for tighter fit, scaled by usefulness
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leftovers too small for the lookahead item but large enough to matter
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 * (next_item_size - post_residual) as f64 / next_item_size as f64;
    }
    // Reward if leftover can exactly host the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of bins with poor residuals
    score += (open_bins_count as f64) * (mean_residual / bin_capacity as f64) * 2.0;

    // New-bin candidate: only attractive when current bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 - pressure.min(30.0);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big item coming: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly matches the next item (perfect 2-step chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // leftover that can still host the next item: mild reward, closer gap is better
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + gap);
        } else {
            // next item cannot fit in the leftover: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 0.6;
        }
    }

    // Prefer bins whose residual is already tight relative to the fleet mean
    score -= (mean_residual - post_residual as f64) * 0.35;

    // Last-chance bin: strongly encourage using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // when many bins fit, prefer the tightest one (already via post_residual)
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Penalize leaving very small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, slightly prefer opening fresh bins to build structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    } else {
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fits are excellent: reward small post_residual nonlinearly
    let tight_bonus = (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    score -= tight_bonus;

    // Penalize dead space that can never be used by typical items (post_residual too small)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0; // perfect pair
        } else if next_item_size as u32 <= post_residual {
            score -= 8.0; // next item can still go here
        } else {
            // next item won't fit: prefer larger post_residual to host it elsewhere later
            score += (next_item_size as f64 - post_residual as f64).max(0.0) * 0.3;
        }
    }

    // Brand-new bin candidate: only attractive when open bins are crowded or fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowding = mean_residual / bin_capacity as f64; // avg free space fraction
        let poor_fit = (post_residual as f64).max(0.0); // = capacity - item for new bin
        // early stream: open bins cheaply; late stream: pack tightly, avoid new bins
        score += 10.0 + progress * 30.0 - crowding * 20.0 - (poor_fit / bin_capacity as f64) * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced
        }
    } else {
        // Prefer bins whose residual is close to the item (minimize wasted capacity)
        let waste_frac = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += waste_frac * 20.0;

        // Spread-aware: if this bin is far below mean residual, using it balances load
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.05 * (1.0 - progress);
    }

    // Late stream: reward filling bins almost completely
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Smooth polynomial core: reward tight fits (small post_residual)
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Non-linear stream coupling: later in stream, prefer tighter packing
    let progress_coupling = 1.0 + 0.5 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Penalize post_residual that cannot fit typical future items (smooth dead-space term)
    let dead = ((40.0 - pr).max(0.0)) / 40.0;
    score += 12.0 * dead * dead * (0.5 + progress);

    // Lookahead: reward if next item fits in post_residual (smooth)
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 8.0 * fits * closeness;
        // Penalize wasting space when next item won't fit
        score += 5.0 * (1.0 - fits) * (item_size as f64 / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (1.0 - (mean_residual / cap).min(1.0));

    // New-bin candidate: neutral-ish, slightly penalized unless open bins have poor fit
    if bin_residual == bin_capacity {
        score = pr + 10.0 - 20.0 * (1.0 - (mean_residual / cap).min(1.0)) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space.
    // Class 0: perfect or near-perfect fit (post_residual <= 10) -> strong reward.
    // Class 1: small usable gap (11..=30) -> mild reward.
    // Class 2: dead zone (31..=60) -> penalty, hard to fill later.
    // Class 3: large residual (>60) -> essentially still a fresh bin.
    let post_class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else if post_residual <= 60 { 3 }
        else { 4 };

    match post_class {
        0 => score -= 200.0,
        1 => score -= 60.0 + (10 - post_residual) as f64 * 4.0,
        2 => score += 25.0 + (post_residual - 30) as f64 * 0.8,
        3 => score += 55.0 + (post_residual - 60) as f64 * 0.5,
        _ => {}
    }

    // Exact fit is gold.
    if post_residual == 0 { score -= 150.0; }

    // Lookahead: does the next item fit in the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item still fits -> good chaining.
            let slack = post_residual - next_item_size;
            score -= 20.0 + (slack as f64).min(15.0);
            // Perfect chain: next item exactly fills the bin.
            if slack == 0 { score -= 80.0; }
        } else {
            // Next item won't fit here; penalize more if we just created a dead zone.
            if post_class >= 2 { score += 15.0; }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual <= 60 {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open new bins early in the stream (many items left to use the space).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // If many bins are open, avoid adding more fragmentation.
        score += open_bins_count as f64 * 1.5;
        // But if the current item leaves a dead zone even in a fresh bin (huge item),
        // opening a new bin is still better than nothing.
        if post_residual > 60 { score -= 30.0; }
        // Lookahead synergy: fresh bin with lots of room can host the next item too.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: when open bins are mostly full (low mean residual),
    // opening a new bin is relatively more attractive; tight fits in existing bins
    // are relatively more valuable.
    let mean_r = mean_residual.max(0.0);
    if bin_residual != bin_capacity {
        score += (mean_r - post_residual as f64) * 0.15;
    }

    // Modulo/harmonic tie-breaking on post_residual: residuals that are multiples
    // of common small item sizes (10, 20, 25, 50) are more likely to be filled later.
    if post_residual > 0 {
        let harmonically_friendly = post_residual % 10 == 0 || post_residual % 25 == 0;
        if harmonically_friendly { score -= 12.0; }
        else { score += 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, reward heavily by lowering
        score -= 200.0;
    } else if post_residual <= 10 {
        // tiny dead gap: strongly penalize unless it exactly fits the lookahead item
        score += 25.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // lookahead can use the gap -> great placement
        }
    } else if post_residual <= 25 {
        // medium-small gap: moderate penalty, softened if lookahead fits
        score += 8.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Reward tight fits: ratio of item to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already low (mean_residual small => bins are nearly full).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (1.5 - mean_residual / bin_capacity as f64).max(0.0) * (2.0 + progress);

    // Last-chance bin: if this is the ONLY fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 20.0 * fit_ratio;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // neutral base for a fresh bin; make it competitive when open bins
        // would waste a lot of space (post_residual large on open bins).
        let waste_elsewhere = mean_residual - item_size as f64;
        if waste_elsewhere > 0.0 && waste_elsewhere < 15.0 {
            score -= 20.0; // open bins would leave tiny dead gaps anyway -> prefer new bin
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0; // big lookahead item benefits from a fresh bin
        }
        score += 5.0 * progress; // late in the stream, mildly prefer consolidating
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into
    // post_residual, this placement sets up a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 200.0;
        }
        // Penalize post_residual that is just barely too small for the
        // next item (dead space trap).
        if post_residual < next_item_size && post_residual >= next_item_size.saturating_sub(8) {
            score += 80.0;
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are
    // "tighter" — prefer filling them (lower score) since large residuals
    // elsewhere remain flexible.
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize very small unusable slivers (dead space), scaled by stream
    // progression — early on, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (20.0 - 10.0 * progress);
    }

    // Mild penalty for scattering across many open bins when this bin
    // leaves a large residual.
    if post_residual as f64 > mean_residual {
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit bonus: small dead space relative to capacity
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight * tight);

    // Lookahead coupling: reward bins whose post residual still fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // penalize leaving dead space the next item can't use
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize bins far from mean residual (fragmentation aversion)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Prefer fuller bins among many open bins
    score += 0.1 * open_bins_count as f64 * tight;

    // Time horizon: as stream nears end, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 {
            1.0 - mean_residual / (bin_capacity as f64)
        } else { 0.0 };
        score += 60.0 - 50.0 * crowding;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // new bin can host a pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;
    let fit_ratio = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 0.0 };

    // Smooth polynomial coupling: base cost from post residual, warped by progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Tight fits rewarded quadratically (small post residual)
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress * 0.5);

    // Dead-space penalty: residual too small for smallest plausible item
    let small_gap = (norm_pr * 10.0).floor() / 10.0;
    if small_gap < 0.1 && pr > 0.0 {
        score += 15.0 * (0.1 - small_gap) * 10.0;
    }

    // Lookahead coupling: reward if next item fits post residual, penalize otherwise
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += (1.0 - fits_next) * 10.0 * (0.5 + 0.5 * norm_next);
        score -= fits_next * 8.0 * (1.0 - norm_next);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - 0.5 * progress);
    }

    // Scarcity pressure: fewer fitting bins relative to open bins -> keep this bin attractive
    score -= 6.0 * fit_ratio * (1.0 - norm_item);

    // Mean-residual divergence: penalize bins far from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    // New-bin candidate: smooth penalty growing with number of open bins and progress
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // but allow opening when item is huge and no good fit exists
        score -= 14.0 * norm_item * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "nice"
    // residues (multiples of 10 / 25) are more reusable -> reward them.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect fit: best possible outcome
    } else if pr % 25 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward residue: dead-space risk
    };
    score += class_bonus;

    // Integer-division threshold: leftover must be able to host the next item.
    if next_item_size > 0 {
        if pr >= next_item_size {
            // lookahead fits: reward proportionally to tightness of pairing
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 - (slack / bin_capacity as f64) * 10.0;
            // harmonic bonus when next item exactly consumes leftover class
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this leftover -> penalize by gap size
            let gap = (next_item_size - pr) as f64;
            score += 4.0 + gap / 10.0;
        }
    }

    // Capacity fraction coupling: prefer bins whose residual fraction is small
    let frac = pr as f64 / bin_capacity as f64;
    score += frac * 15.0;

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        let decent_fits = if next_item_size > 0 {
            (pr >= next_item_size) as i32
        } else { 0 };
        let pressure = (fitting_bins_count == 0) as i32 + (decent_fits == 0) as i32;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening a bin costs more when many bins are already open late in stream
        score += 30.0 - 25.0 * pressure as f64 + open_bins_count as f64 * 2.0 - progress * 5.0;
    }

    // Slight preference for tighter existing bins relative to mean residual.
    score -= (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // A gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gaps that only tiny items could use: moderate penalty,
        // scaled by how close we are to the dead zone.
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (low post residual) extra.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize creating yet another open bin.
    // The new-bin candidate (bin_residual == bin_capacity) gets this pressure
    // so it only wins when open bins have terrible fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Extra penalty if some open bin could actually fit the item.
        if fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement strongly (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (i.e., filling a bin that is already below-average residual
    // drives consolidation).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space relative to bin capacity (normalized waste).
    let cap = bin_capacity as f64;
    score += 0.5 * (post_residual as f64 / cap) * 100.0;

    // 2-step lookahead: strongly reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect chaining bonus: next item exactly fills the leftover space.
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.6 * gap; // smaller gap => bigger reward
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally to waste.
        score += 0.3 * post_residual as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Reward tightening relative to mean residual (prefer bins below-average residual => tight fit).
    score -= 0.2 * (mean_residual - post_residual as f64);

    // Prefer filling nearly-full bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / cap);

    // Slight penalty for proliferating open bins when a good fit exists elsewhere.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.8 * tight * tight * (item_size as f64);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { 1.0 };
        score += dead * (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.1 * (next_item_size as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual can't hold next item: penalize proportionally to wasted space.
        score += 0.2 * (post_residual as f64);
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = mean_residual / (bin_capacity as f64);
        let crowd = (open_bins_count as f64).ln().max(1.0);
        // New bin penalized unless existing bins are fragmented / few fitting bins.
        let mut nb = 30.0 - 20.0 * pressure - 2.0 * crowd;
        if fitting_bins_count <= 1 {
            nb -= 20.0; // no real alternative, allow new bin
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            nb -= 3.0;
        }
        score += nb.max(-5.0);
    }

    // Time horizon: early in stream, be conservative (favor compacting); late, accept imperfect fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tight;

    // Global fragmentation: if mean residual is low, hoard remaining space.
    score += 0.3 * (mean_residual - post_residual as f64).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Normalized post-residual, quadratic coupling with stream progress
    let p_norm = post_residual as f64 / bin_capacity as f64;
    let poly = p_norm * p_norm * (1.0 + 2.0 * progress) + p_norm * (0.5 * progress);

    // Penalize large residuals more strongly as stream progresses (less time to reuse them)
    score += 30.0 * poly;

    // Reward tight fits: small post_residual gets a discount
    let tight = 1.0 - p_norm;
    score -= 20.0 * tight * tight * (1.0 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let fit_q = next_item_size as f64 / bin_capacity as f64;
        score += 0.3 * diff;
        score -= 15.0 * (1.0 - diff / bin_capacity as f64) * fit_q * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is high
    let mean_norm = mean_residual / bin_capacity as f64;
    score += 5.0 * mean_norm * mean_norm * (open_bins_count as f64).ln().max(1.0) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
        // But if the item nearly fills a fresh bin, opening is attractive
        score -= 8.0 * (item_size as f64 / bin_capacity as f64).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 classify dead-space quality
    let post_class = post_residual % 10;
    let post_band = post_residual / 10; // 0..10 harmonic bands

    // Reward small residuals, but with class-dependent bonuses:
    // residuals that are common "sum targets" (multiples of 10) are more reusable.
    match post_class {
        0 => score -= 6.0,
        5 => score -= 2.0,
        1 | 9 => score += 2.0,
        3 | 7 => score += 1.0,
        _ => {}
    }

    // Band shaping: mid residuals (30-60) are flexible; tiny (<10) nearly dead.
    if post_residual < 10 {
        score += 8.0;
    } else if post_band >= 3 && post_band <= 6 {
        score -= 3.0;
    }

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // next item fits: residual class of (post_residual - next_item_size)
            let nres = post_residual - next_item_size;
            if nres % 10 == 0 { score -= 8.0; }
            if nres < 10 { score += 5.0; }
        } else {
            // next item cannot use this bin's remainder: penalize slightly
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // prefer tighter bins among many candidates: small extra pressure
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so it is
    // chosen only when it clearly beats poor fits (large post_residual on opens).
    if bin_residual == bin_capacity {
        score += 15.0;
        // late in the stream, opening bins is cheaper (fewer future regret costs)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        // if next item is large, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: if this bin is far below mean residual, it's tight — reward
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.05;

    // Progress-aware tightening: as stream advances, demand tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize gaps too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 100.0; // tiny unusable gap
    }
    // Penalize any residual that cannot fit the lookahead item (dead space for k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    }

    // Reward tight fits (small post_residual relative to item)
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins, opening new is cheap
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    score += pressure * 2.0;

    // New-bin candidate handling: empty bin gets a moderate default so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score = 30.0 + pressure * 3.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room for lookahead pairing
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative: open a new bin
        }
    }

    // Prefer bins whose residual is above mean (keep balanced residuals usable)
    if (bin_residual as f64) < mean_residual - 10.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a perfect match with the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for next item: strong reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, penalize by slack distance (smaller is better).
            score -= (30.0 - diff.min(30.0)) * 0.8;
        } else {
            // Next item does NOT fit: penalize leaving unusable-for-next space.
            score += diff * 0.5;
        }
    }

    // Penalize large dead space relative to bin capacity (wasted space).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.0 {
        score += waste_ratio * waste_ratio * 40.0;
    }

    // Tight fits are good: small post_residual relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): discourage unless current open bins have
    // poor fits. Compare residual against mean residual of open bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // If mean residual of open bins is small (bins are tight), opening a new
        // bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 30.0;
        // Early in the stream, opening bins is cheaper (more items to come to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    } else {
        // Prefer bins with residual below mean (consolidate large gaps).
        let dev = bin_residual as f64 - mean_residual;
        score += dev * 0.15;
    }

    // Slight preference for fewer open bins overall (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical items are wasteful
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, encouraging spreading
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item can still fit here: mild reward proportional to leftover after next
            let post2 = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - post2 / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportionally to the gap
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.4 * gap;
        }
    }

    // Global state: compare bin residual to mean residual of open bins
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be conservative (favor new bins less);
    // late in the stream, prefer filling existing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    // Penalize opening new bins when many bins are already open and item fits poorly
    if bin_residual == bin_capacity {
        let new_bin_base = 15.0 + 0.5 * open_bins_count as f64;
        score += new_bin_base;
        // but if no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Non-linear coupling: prefer bins whose residual is just above item size (snug fit)
    let snug = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 5.0 * snug * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + progress) - norm_post * (0.5 + 0.5 * progress);

    let mut score = post;

    // Smooth progress-weighted dead-space penalty
    score += 12.0 * poly * cap;

    // Reward tight fits more as stream progresses
    let tightness = 1.0 - norm_post;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize when bin is the only fitting bin (last-chance pressure) smoothly
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - progress) * (post / cap);
    }

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * gap * gap;
        score += 5.0 * (1.0 - gap);
    }

    // Mild penalty for scattering across many open bins, smoothed by mean residual
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).abs();

    // New-bin candidate: penalize slightly so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // --- Harmonic class of post_residual (octaves of capacity/8) ---
    // Class 0: near-perfect fit (post_residual in [0, 12]) -> strong reward
    // Class 1: usable gap (13..=37) -> mild reward if next item fits
    // Class 2: dead zone (38..=74) -> mild penalty
    // Class 3: huge waste (75..=99) -> strong penalty
    let class = post_residual / (bin_capacity / 8);
    match class {
        0 => score -= 14.0 + 0.10 * (12 - post_residual.min(12)) as f64,
        1 => score -= 4.0,
        2 => score += 3.0,
        _ => score += 9.0,
    }

    // Fine-grained harmonic residue: reward post_residuals that are small
    // multiples of common item granularities (mod-10 classes).
    let m = post_residual % 10;
    if m == 0 && post_residual > 0 {
        score -= 2.5; // clean split: next small item may land exactly
    } else if m >= 7 {
        score += 1.5; // ragged edge, likely dead space
    }

    // Lookahead chaining: reward when the next item exactly/comfortably
    // fills the post_residual; penalize stranding the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 10.0; // perfect two-item chain
            } else if slack <= 10 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: residual becomes dead space
            let waste = next_item_size - post_residual;
            if post_residual > 0 && post_residual < 10 {
                score += 6.0; // tiny unusable crumb
            }
            if waste > 40 {
                score += 2.0 * progress; // late-stream waste hurts more
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0;
    }

    // New-bin candidate logic: opening a bin competes with existing bins.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: must open
        } else {
            // Prefer new bin only when the item is large (small post_residual)
            // and existing bins have poor average slack for it.
            let size_bonus = (item_size as f64 / bin_capacity as f64) * 12.0;
            score -= size_bonus;
            if (post_residual as f64) > mean_residual {
                score += 4.0; // existing bins fit better on average
            }
            if fitting_bins_count > 3 {
                score += 3.0; // plenty of alternatives, avoid bin proliferation
            }
        }
    } else {
        // Mild diversification pressure: many open bins with high mean
        // residual -> slightly prefer spreading load via tighter scoring.
        if open_bins_count > 6 && (post_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    // Late-stream tightening: as the stream ends, waste matters more.
    score += progress * (post_residual.min(50) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: small unusable gaps (below min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 50.0;
    }

    // Moderate dead space: penalize gaps smaller than next item or typical small items
    if post_residual > 0 && post_residual < next_item_size.max(10) {
        score += 30.0;
    }

    // Reward bin if residual can still host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open bin pressure: with many open bins, prefer filling existing ones
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: only attractive when current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Tightness reward: prefer bins where item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Late in stream: be more aggressive about compacting
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with little waste left afterward
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_waste = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - two_step_waste / bin_capacity as f64);
    }

    // Penalize dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward leaving space comparable to mean residual (harmonious sizing)
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early in stream: be pickier about small residuals (many items remain)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // Prefer keeping tight bins tight; spread usage across bins
    score += 0.1 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin consumed by this item
    let fill = item_size as f64 / bin_capacity as f64;
    let tight = 1.0 - post_residual as f64 / bin_capacity as f64;

    // Reward tight fits (subtract), with a non-linear bonus for near-perfect packing
    score -= 12.0 * tight * tight;

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_waste = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - next_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Post-residual cannot host the next item: penalize dead space more as stream progresses
        score += 6.0 * post_residual as f64 / bin_capacity as f64 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // Deviation from mean residual: prefer bins below mean residual (denser bins)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // New-bin candidate handling: only attractive when no good fit exists.
    // Penalize opening a new bin, more so late in the stream or when other bins fit.
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 20.0 * progress;
        let fit_pressure = if fitting_bins_count > 1 { 25.0 } else { 0.0 };
        // Slight relief if item is large (would leave big residual in existing bins)
        let large_relief = 10.0 * fill;
        score += open_penalty + fit_pressure - large_relief;
    }

    // Mild late-stream pressure to close bins tightly
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) - norm_pr * progress;
    score += 40.0 * poly;
    // reward tight fits, more so early in stream
    score -= (1.0 - norm_pr) * (1.0 - progress) * 10.0;
    // last chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // lookahead: penalize leaving residual too small for next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr < n {
            score += (n - pr) * 0.5;
        } else {
            let gap = pr - n;
            score -= 0.3 * (gap / cap) * (1.0 - progress);
        }
    }
    // penalize opening new bins when many bins already fit
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }
    // mean residual coupling
    score += 0.1 * (mean_residual - pr).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward (post_residual near zero).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Fraction of capacity left over.
        let frac = post / cap;
        // Penalize dead space quadratically when it falls in "unusable" classes.
        // Items are 1..100, so residual below ~10 is a near-dead class.
        if post_residual < 10 {
            score -= 50.0; // near-perfect fit, good
        } else {
            // Dead-space penalty grows with fraction, but discount residues
            // that match common item size classes (modular harmony).
            score += 30.0 * frac * frac;

            // Harmonic residue classes: residuals that are multiples of 10
            // or common size sums (20, 25, 30, 40, 50) are reusable.
            let r = post_residual;
            let harmonious = r % 10 == 0 || r % 25 == 0 || r % 20 == 0;
            if harmonious {
                score -= 15.0;
            } else {
                score += 10.0;
            }

            // Penalize residuals in awkward middle band (31..=49): hard to fill.
            if (31..=49).contains(&r) {
                score += 12.0;
            }
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / cap);
        if gap == 0.0 {
            score -= 100.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use leftover: penalize large leftovers more.
        score += 8.0 * frac;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // current bins would leave very poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.6;
        // Cheaper to open new bins early in the stream or when few bins open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        score -= 5.0 * open_bins_count as f64;
        // If the item is large relative to capacity, opening fresh is fine.
        if (item_size as f64) > 0.7 * cap {
            score -= 15.0;
        }
        // If next item is large too, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Mild preference to spread load when many bins are open and mean residual high.
    if open_bins_count > 2 && mean_residual > 50.0 && bin_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are worthless — hard penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0 - 0.6 * (post_residual as f64 - 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward absorbing the lookahead item exactly if it fits the post-residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
        if post_residual - next_item_size <= 10 {
            score -= 5.0;
        }
    }
    // Penalize if post-residual can't hold next item and is small anyway.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, favor consolidation
    // (larger fills of existing bins); when few, tolerate new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when the item is large
    // and existing residuals are all poor fits (small gaps).
    if bin_residual == bin_capacity {
        let poor_fits = (post_residual as f64).min(0.0) // placeholder no-op
            + if post_residual >= 0 { 0.0 } else { 0.0 };
        let _ = poor_fits;
        score += 30.0
            - 0.4 * item_size as f64
            - (fitting_bins_count as f64) * 4.0
            + mean_residual * 0.3
            + pressure * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 30.0 * match_quality;
        // Perfect two-item fill: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the leftover: dead space penalty, scaled by tightness
        let progress = step_index as f64 / total_items as f64;
        let dead = post_residual as f64;
        score += 4.0 + 10.0 * (dead / 100.0) * (0.5 + 0.5 * progress);
        // If next item is small, leftover may still combine later: soften slightly
        if next_item_size < 20 {
            score -= 2.0;
        }
    }

    // Penalize bins far below mean residual (poor fits relative to fleet average)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when item barely fits nowhere useful
    if bin_residual == bin_capacity {
        let tight_fit = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins generally; less so for huge items late in stream
        let progress = step_index as f64 / total_items as f64;
        score += 18.0 - 8.0 * tight_fit - 6.0 * progress;
        // If many bins already open, discourage further fragmentation
        score += 0.5 * open_bins_count as f64;
    }

    // Mild preference for tighter residual bins overall
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 {
        // Dead space usefulness: bonus if next item fits exactly-ish.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).recip().min(1.0);
        } else if next_item_size > 0 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits here after this placement, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Global state: many open bins with slack -> prefer reusing bins over new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins already have usable slack.
        if open_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 15.0 + 3.0 * open_bins_count as f64;
        } else if open_bins_count > 0 {
            score += 5.0;
        }
        // Late in the stream, opening a bin is fine (fewer wasted reopens).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    } else {
        // Reuse existing bins; mild penalty for very fragmented bin population.
        score += 0.05 * (open_bins_count as f64).log2().max(0.0);
        // Prefer bins below mean residual (tighter bins) slightly.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Early-stream exploration: encourage diversity of residual profiles.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Quadratic penalty on waste (post_residual), amplified late in stream
    let waste = post / cap;
    score += 30.0 * waste * waste * (0.5 + progress);

    // Reward tight fits: post_residual small relative to capacity
    score -= 12.0 * (1.0 - waste) * (1.0 - waste) * (1.0 - progress);

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Coupling with mean residual: prefer bins near mean (balanced packing)
    let dev = (post - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        // next item won't fit: penalize leaving awkward dead space
        score += 6.0 * (post / cap) * (post / cap);
    }

    // New-bin candidate: make empty bin attractive only when waste elsewhere is high
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 10.0 * (1.0 - waste);
        score += 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how well does leftover space
    // align with the small-item scale (sizes 1..100, small items ~1..30)?
    let r = post_residual;
    let class_penalty = match r {
        0 => -60.0,                     // perfect fit: best possible outcome
        1..=5 => -25.0,                 // near-perfect dead space is harmless
        6..=15 => -8.0,                 // usable by small items
        16..=30 => 5.0,                 // moderately awkward
        31..=50 => 12.0,                // awkward zone: hard to fill later
        _ => 20.0,                      // large leftover means we barely helped
    };
    score += class_penalty;

    // Modulo-arithmetic coupling: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are easier to close exactly later.
    let harmonic_bonus: f64 = if r == 0 { 0.0 }
        else if r % 10 == 0 { -6.0 }
        else if r % 25 == 0 { -4.0 }
        else if r % 5 == 0 { -2.0 }
        else if r % 3 == 0 { 1.0 }
        else { 3.0 };
    score += harmonic_bonus;

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r && r - next_item_size <= 10 {
            score -= 12.0;
        } else if next_item_size > r {
            // next item won't fit here; leftover becomes dead space
            score += (r.min(next_item_size)) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize the fresh bin mildly so it
    // only wins when existing bins score poorly (awkward residuals).
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    }

    // Progress-based pressure: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (post_residual.min(50) as f64) / 50.0;

    // Prefer bins whose residual is below the mean (tighter bins first),
    // leaving larger residual bins flexible for future items.
    score += ((mean_residual - bin_residual as f64).max(-50.0).min(50.0)) * 0.15;

    // Slight penalty for very tight current fit (waste avoidance).
    let tightness = (item_size as f64) / (bin_capacity as f64);
    if tightness > 0.7 {
        score -= 5.0 * (tightness - 0.7) / 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that can never host even the
    // smallest item (1..10) are worthless; penalize them hard.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space (< min item size): heavy penalty.
        score += 80.0;
    } else if post_residual <= 20 {
        // Marginal gap: only useful for tiny items; moderate penalty.
        score += 25.0;
    } else {
        // Usable gap: mild reward proportional to how well the next item fits.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0;
        }
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: slight penalty for blocking lookahead.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is
    // loose; encourage using existing bins when many are open.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Phase pressure: late in the stream, prefer consolidating (fill existing
    // bins tightly) rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual context: if this bin's residual is far below the mean
    // (it is the "cramped" bin), placing here is efficient consolidation.
    let residual_diff = mean_residual - post_residual as f64;
    score -= 0.5 * residual_diff.max(-50.0).min(50.0);

    // New-bin candidate guard: an empty bin should only win when no open bin
    // offers a decent fit (post_residual small) — penalize the empty-bin call
    // so it is chosen only for genuinely poor fits elsewhere.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: opening new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual closely
    // matches the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for the next item is a jackpot.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits too: reward closeness of the match.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leftover dead space,
            // more so when the dead space is small and thus unusable.
            let dead = post_residual as f64;
            score += dead * 0.5;
        }
    }

    // Prefer tight fits relative to the mean residual of open bins.
    let res = bin_residual as f64;
    score -= (res - mean_residual) * 0.3;

    // Strongly prefer the smallest residual bin that can still fit the item
    // (best-fit bias), amplified when this is the last fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += fitting_bins_count as f64 * 0.5;
    }

    // Penalize opening a new bin unless the current item fits poorly
    // everywhere: make the empty-bin candidate less attractive for good fits.
    if bin_residual == bin_capacity {
        // New bin: baseline cost plus penalty scaled by how tight the best
        // alternative fit would be (post_residual small => new bin is bad).
        score += 30.0;
        if post_residual > 0 {
            score += (bin_capacity as f64 - post_residual as f64) * 0.1;
        }
    }

    // Late in the stream, be more conservative: keep bins tight to avoid
    // sprawl of many nearly-empty bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early phase -> explore new bins; late phase -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let late = progress > 0.7;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    let tight_bonus = 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score -= tight_bonus * (0.5 + progress);

    // Penalize dead space that is too small for the smallest plausible item (1..100 range,
    // but small items are rare): residual in [1, 15] is near-waste.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if next item fits exactly in the post-residual, strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            // Next item cannot use leftover: penalize proportionally to wasted potential.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins with high mean residual: discourage fragmenting further,
    // encourage filling existing bins.
    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // New empty bin candidate: penalize unless it's early (exploration) or current
    // fit is terrible (item barely fits / big dead space).
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (item_size as f64 / bin_capacity as f64); // low = tight fit
        let poor_fit = fit_quality > 0.7; // item leaves > 70% unused... i.e. small item in fresh bin
        let big_item = item_size as f64 / bin_capacity as f64 > 0.6;
        let mut new_bin_penalty = 15.0;
        if progress < 0.25 { new_bin_penalty -= 6.0; }        // early exploration cheaper
        if late { new_bin_penalty += 8.0; }                   // late: consolidate instead
        if poor_fit && !big_item { new_bin_penalty += 10.0; } // don't waste a fresh bin on a small item
        if big_item && post_residual < 40 { new_bin_penalty -= 8.0; } // large item nearly fills bin
        score += new_bin_penalty;
    }

    // Mild preference for bins whose residual is close to item size (best-fit core),
    // scaled by how many alternatives exist.
    let abs_diff = (bin_residual as f64 - item_size as f64).abs();
    score += abs_diff * 0.15 * (1.0 + (fitting_bins_count as f64).ln().max(0.0));

    // Slight bias toward bins below mean residual (fill the emptier/older bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Quadratic waste penalty: small post-residuals are valuable, large ones are dead space
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits, more so as the stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (4.0 + 6.0 * progress);

    // Lookahead: penalize if next item cannot use the leftover space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap * (0.5 + progress);
        } else {
            score -= 3.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Penalize bins far from the mean residual (encourage uniform fill)
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = cap * (0.25 + 0.5 * crowding + 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 create dead-space classes.
    let residue_class = (post_residual % 10) as f64;
    // Residuals that are multiples of 10 are "harmonic" — easily filled by small items.
    let harmonic_bonus = if post_residual % 10 == 0 { 3.0 } else { residue_class * 0.4 };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual: tiny leftovers are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward (capacity fraction coupling).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead harmonic: does next_item_size divide/match post_residual class?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's leftover: penalize by overshoot class
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.3;
            if overshoot % 10.0 < 1.0 {
                score += 4.0; // near-harmonic overshoot wastes a whole class
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when the current
    // fit is poor (large post_residual relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // open a new bin if placing here would leave > 60% residual
        if fit_quality > 0.6 {
            score -= 35.0 * (fit_quality - 0.6) * 5.0;
        }
        // early stream: more room to consolidate later, slightly favor new bins
        score -= 10.0 * (1.0 - progress);
        // too many open bins: discourage opening more
        score += open_bins_count as f64 * 1.5;
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's fragmented.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Tight-packing reward: item fills most of the bin (capacity fraction > 0.8).
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item (<= 10) is dead space.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 35 {
        score += 4.0;
    } else {
        // Large residual after placement is good: reward keeping usable space.
        score -= 6.0;
    }

    // Perfect or near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Next item cannot use the leftover: mild penalty scaled by gap.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; discourage opening new bins when pressure is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64) * (0.5 + progress);
    score += pressure * 0.4;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: placing into a bin whose residual is far below
    // the mean (tighter bin) is preferred, spreading waste across bins evenly.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.2;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., many fitting bins means we should reuse existing ones).
    if bin_residual == bin_capacity {
        score += 15.0 + pressure * 0.6;
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Slight tie-break: prefer bins with larger residual before placement
    // (keeps small-residual bins for small items).
    score += bin_res_f * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // exact 2-step chain: place here
        } else if post_residual >= next_item_size {
            // next item still fits here; reward closeness to exact match
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item won't fit; penalize proportionally to wasted lookahead
            score += 0.5 * diff as f64;
        }
    }

    // Compare post_residual to mean residual: leaving near-mean residual is neutral,
    // far-from-mean residuals create imbalance; penalize excess dead space.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // slight reward for below-mean residual (tighter packing)
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0
            && next_item_size > 0
            && open_bins_count > 0
            && (post_residual as i64 - next_item_size as i64).abs() < 15;
        if good_fit_exists {
            score += 40.0; // keep existing bins when a decent fit exists
        } else if next_item_size == 0 {
            score += 10.0; // last item: prefer open bins slightly
        }
    }

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving small unusable gaps (dead space) that few future items can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size >= bin_residual {
            // Next item won't fit here anyway; mild bonus for using a big chunk now.
            score -= 8.0 * (item_size as f64 / bin_capacity as f64);
        } else {
            // Placing here blocks the next item in this bin: penalize.
            score += 12.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins for big items);
    // late in the stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (item_size as f64 / bin_capacity as f64);

    // Global state: many open bins with slack -> prefer consolidating into bins
    // with above-average residual.
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_diff * (1.0 - progress);

    // Prefer bins with larger residual when item is small (save small gaps in tight bins).
    if (item_size as f64) < 0.35 * bin_capacity as f64 {
        score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // New-bin candidate handling: only attractive when item is large or nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let large_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let crowd = (open_bins_count as f64).ln().max(0.0);
        if large_item || desperation > 0.0 {
            score -= desperation + 20.0 * (item_size as f64 / bin_capacity as f64);
        } else {
            // Discourage opening new bins early when open bins exist.
            score += 15.0 + 10.0 * (1.0 - progress) - 5.0 * crowd.min(3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual and fit quality
    let r = post_residual as f64 / cap;
    let fit = item_size as f64 / bin_residual as f64;

    // Non-linear polynomial coupling: post-residual shaped by progress
    let poly = r * r * (1.0 - r) * (2.0 - r);
    score += 60.0 * poly * (0.5 + progress);

    // Reward tight fits, stronger as stream progresses
    score -= 25.0 * fit * fit * (0.4 + 0.6 * progress);

    // Penalize dead space below smallest plausible item
    if r > 0.0 && r < 0.1 {
        score += 15.0 * (0.1 - r) / 0.1 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - r);
    }

    // Lookahead coupling: favor bins whose post-residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 12.0 * (1.0 - (post_residual as f64 - nx) / cap);
        } else {
            score += 8.0 * (nx - post_residual as f64) / cap;
        }
    }

    // Spread pressure: discourage bins far from mean residual
    score += 5.0 * ((post_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a bin unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * (1.0 - fit);
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 decile classes.
    // Residuals that fall in "useful" classes (small enough for common small items)
    // are rewarded; awkward mid-range dead space is penalized.
    let class = post_residual / (bin_capacity / 10).max(1);
    match class {
        0 => score -= 30.0,               // near-perfect fit
        1 => score -= 22.0,
        2 => score -= 14.0,
        3 => score -= 6.0,
        4 => score += 8.0,                // awkward dead zone ~40-50
        5 => score += 10.0,
        6 => score += 6.0,
        7 => score -= 4.0,
        8 => score -= 8.0,
        _ => {}                           // nearly empty bin: neutral
    }

    // Exact-fit multiples: post_residual divisible into clean harmonic slots
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % 10 == 0 && post_residual <= 50 {
        score -= 12.0;                    // clean class divisible by 10
    } else if post_residual % 10 != 0 && post_residual < 10 {
        score -= 15.0;                    // tiny sliver, essentially closed
    }

    // Lookahead coupling: does this post_residual admit the next item?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Harmonic match classes between leftover and next item
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;                // chains perfectly
        } else if gap <= 10 {
            score -= 25.0;
        } else if gap <= 20 {
            score -= 12.0;
        } else {
            score -= (gap.min(40) as f64) * 0.15;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to how stranded the space is
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
        if post_residual <= 15 {
            score -= 20.0;                // closing it out entirely
        }
    }

    // New-bin candidate: only attractive when existing bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / cap);
        score += 45.0 + pressure * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0;                // fresh bin pairs well with upcoming large item
        }
        if post_residual as f64 > cap * 0.5 && fitting_bins_count > 0 {
            score += 30.0;                // wasteful to open when decent fits exist
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / cap);

    // Deviation from mean residual: prefer bins whose leftover tracks the average
    score += ((post_residual as f64 - mean_residual) / cap).abs() * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 12.0; // gaps below ~12 units are likely unusable for typical items
    if post_residual > 0 {
        if (post_residual as f64) < dead_zone {
            score += (dead_zone - post_residual as f64) * 8.0;
        } else {
            // larger residuals are progressively less painful (usable space)
            score -= (post_residual as f64 - dead_zone) * 0.3;
        }
    } else {
        // perfect fill is strongly rewarded
        score -= 25.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the new residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item fits comfortably in residual: mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }
    // Next item would NOT fit here: residual risks becoming dead space; penalize proportionally.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins
    // (make existing bins cheaper relative to the new-bin candidate).
    score -= (open_bins_count as f64) * 1.5;

    // Mean residual coupling: if the fleet is already loose, prefer the bin that
    // tightens overall slack (low post_residual relative to mean).
    score += (mean_residual - post_residual as f64) * 0.4;

    // New-bin candidate handling: an empty bin gets a base cost that scales with
    // how well existing bins are doing; opening bins early is discouraged.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // but if the item is huge and would leave a tiny gap anywhere, new bin is fine
        if item_size >= bin_capacity - 5 {
            score -= 35.0;
        }
    }

    // Slight preference early in the stream to keep options open (mild).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual to next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect chaining: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits in the post residual: reward proportionally to fill
        if next_item_size <= post_residual {
            score -= 25.0 * (next / (pr + 1.0));
        } else {
            // Next item won't fit here: penalize small dead space more as stream progresses
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 15.0 * progress * (1.0 - pr / bin_capacity as f64);
        }

        // Two-item chain: could the item after next also matter? approximate with mean_residual coupling
        let mean_gap = (mean_residual - pr).abs();
        score += 0.3 * mean_gap;
    }

    // Last-chance bin: strong incentive to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if item is huge relative to mean residual (poor fits elsewhere)
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for fragmenting bins with large residual when many bins are open
    if open_bins_count > 3 && post_residual > 0 {
        score += 0.05 * (post_residual as f64) * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 12.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here anyway; mild penalty if we leave awkward residue.
        score += 3.0;
    }

    // Time horizon: early in the stream, prefer consolidating into open bins;
    // late in the stream, waste less concern on new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, reward late slightly.
        score += 18.0 * (1.0 - progress) - 5.0 * progress;
        // If many open bins already, discourage more sprawl.
        score += open_bins_count as f64 * 0.8;
    } else {
        // Existing bin: reward using bins with residual close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Penalize creating dead space below the smallest plausible item (1..=100 range guard).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Perfect fit jackpot.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, but with diminishing returns via quadratic coupling
    let mut score = pr * (1.0 + 0.35 * norm_pr);

    // Smooth stream-progress coupling: late in stream, tighter packing preferred
    score *= 1.0 - 0.25 * progress * (1.0 - norm_pr);

    // Penalize large dead space relative to mean residual (waste signal)
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space usable by next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 5.0 * (n - pr) / cap;
        }
    }

    // Mild penalty for opening a new bin when other bins fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    // Slight preference for fewer open bins (consolidation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod 10 bands (dead-space classes)
    let pr = post_residual;
    let class = pr % 10;
    // Penalize awkward residues that are hard to fill later
    let awkward = match class {
        1 | 2 | 3 | 6 | 7 | 8 => 3.0,
        4 | 5 => 1.5,
        _ => 0.0, // 0 or 9: perfectly closed or near-full
    };
    score += awkward;

    // Reward near-exact closure: post_residual in a "fillable" small band
    if pr > 0 && pr <= 10 {
        score -= 6.0;
    }
    if pr == 0 {
        score -= 12.0;
    }

    // Integer-division thresholds on post_residual (capacity fractions)
    let cap_frac = (pr * 4) / bin_capacity; // 0..=3 quartile class
    score += match cap_frac {
        0 => 8.0,   // >75% empty: wasted large space
        1 => 2.0,   // 50-75%
        2 => -1.0,  // 25-50%
        _ => -3.0,  // <25%: tight fit, good
    };

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 5.0;
            // harmonic match: next item lands on a class boundary
            if pr % next_item_size.max(1) == 0 {
                score -= 4.0;
            }
        } else {
            score += 4.0; // next item won't fit here -> dead space risk
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: prefer it only late or when bin is very loose
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size >= 60;
        if large_item || (progress > 0.8 && open_bins_count > 6) {
            score -= 2.0;
        } else {
            score += 15.0;
        }
    }

    // Mean residual coupling: penalize bins far above mean residual (fragmenting)
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Mild tightness reward relative to item size
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap that no future item (min size 1,
    // but practically small gaps) can use is pure waste. Penalize gaps below
    // a "usable threshold" harshly, proportional to how dead they are.
    let usable_threshold = 20u32;
    if post_residual < usable_threshold {
        // Dead space: the smaller the gap, the worse (relative waste).
        score += (usable_threshold - post_residual) as f64 * 8.0;
    }

    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0; // near-perfect fill, likely still usable by tiny items
    }

    // Reward leaving exactly enough room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 25.0; // exact lookahead fit
        } else if slack < usable_threshold {
            score -= 6.0;
        }
    }
    // Penalize if placing here kills the room needed by the next item
    // while this bin was one of few options.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor
    // filling existing bins; few open bins -> opening new bins is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: neutral base, plus pressure so it loses to
        // decent fits in open bins.
        score = bin_capacity as f64 * 0.5 + pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open a new bin
        }
    } else {
        // Existing bin: subtract pressure so it beats new-bin candidate.
        score -= pressure * 2.0;
        // Favor bins tighter than average (best-fit flavor).
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

