    // Relative residual vs mean: prefer bins already tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty for spreading across many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.05;

    // Slight preference for denser bins (larger item share of residual).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

