        }
    } else if fitting_bins_count > 1 {
        // Slight penalty for hoarding in one bin when alternatives exist,
        // encouraging spreading among good fits.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins unless they're bad.
        score += 30.0;
        // If mean residual across open bins is large, existing bins are roomy -> prefer them.
        score += 0.3 * mean_residual;
        // Early in stream, opening bins is cheap; late, avoid new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // Big items relative to capacity in a fresh bin are fine.
        score -= 0.2 * item_size as f64;
        // If next item is large and current item small, fresh bin keeps flexibility.
        if next_item_size >= 70 && item_size <= 30 {
