        }
    }

    // Small item into a large-residual bin: mild penalty to preserve big space for big items.
    if item_size <= 20 && bin_residual >= 60 && bin_residual != bin_capacity {
        score += 8.0;
    }

    // Prefer filling nearly-full bins: reward small post-residual relative to mean residual gap.
    let gap = mean_residual - bin_residual as f64;
    if gap > 0.0 {
        score += 0.15 * gap; // prefer bins tighter than average
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Smooth polynomial decay of post_residual's value as stream progresses
    score -= 30.0 * (1.0 - norm_pr).powi(2) * (1.0 - progress).powi(2);

