    }

    // Last-chance bonus, smoothed polynomial in fitting_bins_count
    let scarcity = 1.0 / (fitting_bins_count as f64).powi(2);
    score -= 25.0 * scarcity * (1.0 - fit_ratio * 0.5);

    // Mean residual alignment: prefer bins whose post-residual tracks the mean
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Mild new-bin penalty scaled by open bins and progress
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: how "usable" is the leftover? ---
    // Class A (0): perfect fit -> huge reward.
    // Class B (1..=10): small dead space -> mild penalty.
    // Class C (11..=40): still combinable with typical small items -> reward.
    // Class D (>40): large leftover, generally fine -> neutral.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score += 12.0;
    } else if post_residual <= 40 {
        score -= 8.0;
    }

    // Modulo-10 harmonic structure: residuals divisible by 10 pair better
    // with the integer item sizes (1..=100).
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 6.0;
    } else if m10 >= 5 {
        score += 3.0;
    } else {
        score += 1.0;
    }

    // Integer-division threshold: does the residual still admit at least one
    // item of the "harmonic half" class (size <= 50)?
    let half_class = post_residual / 50; // 1 => can host a mid-size item
    if half_class >= 1 {
        score -= 4.0;
    }

    // Lookahead coupling: can next_item_size fit exactly into the leftover?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Fractional coupling: how tightly does the next item fill it?
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 14.0 * fill;
            // Modulo match on decade classes (e.g. 30 leftover, 20 next).
            if post_residual % 10 == next_item_size % 10 && next_item_size >= 10 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this residual: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would create bad fits (large post_residual dead space).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 15.0 * progress;
        // If current item would leave a harmonically good residual in an
        // existing bin, opening new is worse; if it would strand space,
        // opening new is relatively better (handled implicitly by other terms).
        // Slight bonus if many bins are open already (consolidate pressure).
        if open_bins_count > 4 {
            score += 2.0 * (open_bins_count.min(20) as f64 - 4.0);
        }
    }

    // Mean-residual alignment: prefer bins whose residual is close to the
    // fleet mean (keeps residuals homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tight-fit reward: filling most of the bin now is good.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post residual (tight fit).
    score = post_residual as f64;

    // Dead space penalty: residual gaps too small for any item (min size 1,
    // but practically gaps below ~15 are hard to fill) are wasted.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        // The smaller the useless gap relative to threshold, the worse.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward if this bin can also host the lookahead item afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward when lookahead exactly fills the remaining gap.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot use the leftover: mild penalty scaled by gap size.
        let gap = post_residual as f64;
        if gap > 0.0 && gap < next_item_size as f64 {
            score += gap * 0.5;
        }
    }

    // Open bins pressure: discourage opening new bins when many are open,
    // encouraging consolidation into existing bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + 8.0 * open_bins_count as f64;
        // New bin is acceptable if item is large and fit is poor elsewhere:
        // penalize less when the item nearly fills the new bin.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    } else {
        // Reusing a bin reduces open-bin count pressure: small reward.
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin for a poor future fit.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Mean residual coupling: bins far below mean residual are "loose" targets;
    // prefer bins whose residual is close to (or below) the mean to balance loads.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Slight stream-phase modulation: early on, be a bit more conservative
    // about wasting space; later, consolidation matters more.
    let phase = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // ---- Aggressive 2-step lookahead matching ----
    if next > 0.0 {
        let diff = post - next;
        if diff == 0.0 {
            // Perfect match: next item exactly fills the residual space
            score -= 1000.0;
        } else if diff > 0.0 {
            // Next item fits with leftover; reward small leftovers only
            score -= 30.0 * (1.0 - diff / cap);
        } else {
            // Next item won't fit here; penalize the dead-space gap
            score += 20.0 + (-diff) * 0.5;
        }
    }

    // ---- Coupling with mean residual across open bins ----
    // Prefer bins whose post-residual sits favorably relative to the fleet mean
    let mean_norm = mean_residual / cap;
    let post_norm = post / cap;
    score += (post_norm - mean_norm) * 25.0;

    // ---- Last-chance bonus: only bin that can fit the item ----
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // ---- Stream progression: tighten packing later in the stream ----
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        } else if post_residual >= next_item_size {
            // Reward bins that can also host the next item.
            score -= 6.0 * ((post_residual as f64) / (bin_capacity as f64));
        }
    } else {
        // Last item: fill any bin as tightly as possible.
        score -= 40.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let open_frac = open_bins_count as f64 / ((total_items.max(1)) as f64).sqrt().max(1.0);
    if bin_residual < bin_capacity {
        score -= 5.0 * open_frac.min(3.0);
    } else {
        // New bin candidate: penalize mildly, less so early in the stream.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * (1.0 - t);
    }

    // Prefer bins with residual close to the mean (balanced packing),
    // but reward bins with below-mean residual (denser bins first).
    if bin_residual < bin_capacity {
        let denser = (mean_residual - bin_residual as f64).max(0.0);
        score -= 4.0 * (denser / (bin_capacity as f64)).min(1.0);
    }

    // Small absolute penalty for very tiny post_residual waste.
    if post_residual <= 2 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let itemn = item_size as f64 / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    let mut score = prn * prn * (1.0 + 2.0 * progress) * cap;

    // Smooth cubic coupling: large residuals are more tolerable early, costly late.
    score += prn.powi(3) * 40.0 * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth exponential bonus.
    score -= (1.0 - prn).exp() * 30.0 * (1.0 - progress);

    // Penalize when this bin's post residual cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) < nxt {
            score += 25.0 * (1.0 - prn) * (1.0 - 0.5 * progress);
        } else {
            // Smooth reward proportional to how well the lookahead fits.
            let slack = (pr as f64 - nxt) / cap;
            score -= 15.0 * (1.0 - slack).max(0.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Mild crowding penalty: prefer spreading when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * prn;

    // Deviation from mean residual: prefer bins whose residual is near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * 10.0 * (0.3 + progress);

    // New-bin candidate: smooth gating — prefer new bin only when fit is poor.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - itemn).exp() * (1.0 + 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: which "size class" (1-100 in coarse
    // buckets of 10) can still be absorbed by post_residual.
    let post_class = post_residual / 10;               // 0..=10
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size - 1) / 10 }; // 0..=9

    // Perfect fit is king: strongly reward zero (or class-zero) leftovers.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that the lookahead item cannot consume.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Reward bins whose leftover can host the next item,
                // scaled by how "snug" the fit would be (harmonic pairing).
                let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
                score -= 30.0 * snug;
            } else {
                // Dead space relative to lookahead: penalize, worse for tiny leftovers.
                score += 20.0 + 40.0 * (1.0 - post_residual as f64 / cap);
            }
        }

        // Harmonic class bonus: leftover in the same decade class as the next
        // item is a natural pairing (e.g. leftover 60 hosting item 55-64).
        if next_item_size > 0 && post_class == next_class + 1 {
            score -= 15.0;
        }
        // Leftovers in awkward classes (1..4 => 10-49 residual) tend to become
        // dead space; add a class-dependent penalty.
        if post_class >= 1 && post_class <= 4 {
            score += 8.0 * (5 - post_class) as f64;
        }
        // Large leftovers (>50) are flexible; small nudge toward using them.
        if post_residual > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < item_size.max(1) * 0 + bin_residual {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation onto tighter bins (low residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate: make an empty bin attractive only when the item is huge
    // (harmonic top class) or leftovers would be unusable; otherwise bias it out.
    if bin_residual == bin_capacity {
        if item_size > bin_capacity * 4 / 5 {
            score -= 20.0; // big items start fresh bins happily
        } else {
            score += 35.0; // discourage scattering small items into new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are wasted space -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }
    // Unusable gap relative to next item: if the next item cannot fit
    // into the post residual, this bin creates dead space for it.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if (next_item_size as f64) > gap {
            // dead space for the lookahead item; scale by tightness
            let tight = (next_item_size as f64 - gap) / bin_capacity as f64;
            score += 40.0 * tight;
        } else {
            // next item fits exactly-ish: reward good chaining
            let chain = 1.0 - ((next_item_size as i64 - post_residual as i64).abs() as f64) / bin_capacity as f64;
            score -= 15.0 * chain;
        }
    }

    // Reward tight fits (small post residual) non-linearly.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fit_quality * fit_quality;

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 5.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin; offset by how bad existing fits are.
        let badness = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score = 60.0 - 30.0 * badness;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0; // next item needs a full bin anyway
        }
    }

    // Slight stream-position modulation: later in the stream, be greedier
    // about tight packing since fewer future corrections remain.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_quality;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score += diff * 0.8;
        }
        // Penalize if next item cannot fit in the post residual (dead space for lookahead).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Reward if this placement still leaves room for the next item too.
        if post_residual >= next_item_size {
            score -= 10.0;
        }
    } else {
        // Last item: prefer tightest fit, small residuals are fine.
        score -= 5.0;
    }

    // Compare against mean residual: prefer bins that end below the mean residual
    // (i.e. we are consolidating space into fewer, tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent open bins exist (empty-bin candidate).
    if bin_residual == bin_capacity {
        // New bin is attractive only if item is large relative to capacity or
        // post residual would be small (near-perfect packing).
        score += 25.0;
        if item_size >= bin_capacity * 9 / 10 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) more than linearly.
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Lookahead: if the next item fits into the post-residual, this bin
    // stays useful — reward it. If next item barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 6.0 + 4.0 * (1.0 - (pr - nx) / cap);
        } else if nx <= pr + 12.0 {
            score += 4.0 * (nx - pr) / 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin for a poorly-fitting item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Time horizon: late in the stream, consolidation matters more —
    // favor filling existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 * progress + 0.02 * open_bins_count as f64;
    } else {
        score -= 5.0 * progress;
    }

    // Global state coupling: if mean residual is high (bins are loose),
    // prefer filling existing bins; if mean residual is low, new bins
    // become relatively more attractive.
    if bin_residual < bin_capacity {
        score -= 3.0 * ((mean_residual - pr) / cap).clamp(-1.0, 1.0);
    }

    // Perfect-fit extreme reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize creating large dead space that nothing typical can use.
    if pr > 0.0 && pr < 10.0 {
        score += 6.0 * (10.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual, but normalize softly.
    let mut score = post;

    // Smooth polynomial coupling: reward tight fits more strongly as the stream progresses.
    // tightness in [0,1]: 1 when item fills the bin exactly.
    let tightness = 1.0 - (post / cap);
    let progress_coupling = tightness * tightness * (0.5 + 2.0 * progress);
    score -= 3.0 * progress_coupling * cap * 0.1;

    // Penalize post-residuals that are too small to ever be useful (dead space),
    // with a smooth bump around the low-value region (below typical small item size 10).
    let dead = ((post - 8.0) / 10.0).exp().powi(2);
    score += 5.0 * dead * (1.0 - progress * 0.5);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (smooth ramp in fitting_bins_count).
    if fitting_bins_count >= 1 {
        score -= 20.0 * (1.0 / fitting_bins_count as f64);
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let slack_fit = 1.0 - (post - next_item_size as f64) / cap;
        score -= 4.0 + 6.0 * slack_fit * progress;
    } else if next_item_size > 0 {
        // Next item won't fit here; mildly penalize leaving a bad gap.
        score += 2.0 * (1.0 - (post / cap)) * (1.0 - progress);
    }

    // New-bin candidate: empty bin has large post-residual; make it attractive only
    // when open bins are crowded (mean residual low) or few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowd = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 15.0 * crowd * (0.3 + 0.7 * progress);
        score -= 10.0 / (1.0 + fitting_bins_count as f64);
    } else {
        // Prefer bins whose residual is below the mean (consolidate fullness).
        let fullness_gap = (mean_residual - bin_residual as f64) / cap;
        score -= 2.0 * fullness_gap;
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo classes mod 10 (common item sizes)
    let class = post_residual % 10;
    // Residuals that are "usable" harmonic classes (0, 10-ish, divisible by common sizes)
    if class == 0 {
        score -= 12.0; // perfect alignment: dead space is reusable
    } else if class <= 5 {
        score -= 4.0;
    } else {
        score += (class - 5) as f64 * 1.5; // odd leftovers are likely dead space
    }

    // Integer-division threshold: can post_residual hold common small sizes (10..30)?
    let div10 = post_residual / 10;
    let div20 = post_residual / 20;
    score += 6.0 - (div10.min(6) as f64);
    score -= (div20.min(3) as f64) * 1.2;

    // Lookahead coupling: harmonic class of next item vs post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: reward, especially if post_residual % next_item_size is small
            let rem = post_residual % next_item_size;
            score -= 8.0 - (rem as f64) * 0.5;
            if post_residual % next_item_size == 0 {
                score -= 6.0; // exact split is ideal
            }
        } else {
            // next item cannot use this residual: penalize proportional to overshoot class
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.8 + (gap / 10) as f64 * 1.0;
        }
    }

    // Capacity fraction thresholds on bin_residual
    let frac = bin_residual as f64 / bin_capacity as f64;
    if frac > 0.8 {
        score -= 5.0; // nearly full bin, good to close it out
    } else if frac < 0.3 {
        score += 3.0; // don't dump into a barely-used bin unless needed
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no good harmonic fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs().min(20.0);

    // Mild penalty for wasting large residual when many bins are open
    score += (open_bins_count as f64).ln() * (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual (fill fraction).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill * fill;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would NOT fit even in a fresh bin, no special concern;
    // but if next item fits only in a fresh bin, prefer keeping this bin tight.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Open bins pressure: discourage scattering across many bins.
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // bin fits are poor (large dead space) or next item needs fresh space.
    if bin_residual == bin_capacity {
        score += 12.0; // default mild penalty vs reusing bins
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        }
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 10.0; // big items fine in fresh bins
        }
    }

    // Mean residual coupling: when open bins are mostly empty, prefer reusing them.
    if bin_residual < bin_capacity && (mean_residual > 50.0) {
        score -= 4.0;
    }

    // Stream progression: later in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits (post_residual == next_item_size)
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        if diff == 0.0 {
            // Perfect chain: this bin's leftover exactly absorbs the next item
            score -= 60.0 + 0.5 * nr;
        } else if pr >= nr {
            // Next item still fits after this placement; the tighter, the better
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit in the leftover; penalize dead space proportionally
            score += 10.0 + 0.3 * (nr - pr);
        }
    }

    // Reward tight fits relative to current residual (small post_residual is good)
    score -= 0.4 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64);

    // Penalize creating unusable slivers (post_residual too small for the smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Compare against mean residual: bins with residual below mean are "tighter" and preferred
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Discourage opening a new bin when decent open bins exist, unless the item is huge
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 30.0 * (1.0 - fill_ratio);
        } else {
            score -= 5.0 * fill_ratio;
        }
    }

    // Late-stream consolidation: near the end, prefer closing out existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Penalize leaving dead space relative to typical small item sizes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 && post_residual > 0 {
        score -= 50.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 120.0 + next_item_size as f64 * 0.5;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // Dead space the next item cannot use; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so existing bins with decent fits win.
        score += 150.0;
        // But if many open bins are fragmented (high mean residual spread),
        // or the item fits nowhere well, opening a new bin is attractive.
        let poor_fit = (post_residual as f64) > item_size as f64 * 0.5;
        if poor_fit {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        score += 100.0 * progress;
        // If open bins are mostly full (low mean residual), new bin is natural.
        score -= (mean_residual / bin_capacity as f64) * 50.0;
    }

    // Prefer fuller bins: penalize bins with large residual only mildly,
    // so tight fits dominate but wasteful use of huge bins is discouraged.
    score += (bin_residual as f64) * 0.15;

    // Mild penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is below the mean (relatively full bins).
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_post * norm_post * (1.0 + progress * 2.0) - norm_post * (0.5 + progress);

    // Reward tight fits, more strongly later in the stream.
    let tight_fit = (1.0 - norm_post).powi(3) * (0.5 + progress);

    // Last-chance bonus: avoid opening a new bin when only one bin fits.
    let last_chance = if fitting_bins_count == 1 { -0.8 } else { 0.0 };

    // Penalize bins whose post-residual is awkward (small but nonzero).
    let dead_space = if post > 0.0 && post < 10.0 { 2.0 * (10.0 - post) / 10.0 } else { 0.0 };

    // Lookahead: reward residual that could still fit the next item.
    let lookahead = if next_item_size > 0 {
        if post >= next_item_size as f64 { -0.3 * (1.0 - post / cap) } else { 0.5 }
    } else { 0.0 };

    // Mild penalty for proliferation of open bins relative to mean residual.
    let spread = (mean_residual - post) / cap;
    let spread_pen = 0.2 * spread * spread;

    // New-bin candidate baseline: keep it slightly costly so existing bins are preferred
    // unless the fit is poor.
    let new_bin_bias = if bin_residual == bin_capacity { 1.5 } else { 0.0 };

    post + poly * 3.0 - tight_fit * 2.0 + last_chance + dead_space + lookahead + spread_pen + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize leftovers in "dead zones": small unusable slivers (1..=9) and awkward mid bands
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space sliver
    }
    // Modulo-10 harmonic band reward: leftovers divisible by 10 pair well with 10..80 items
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Integer-division threshold: leftover >= 40 is still "half bin" — mildly valuable
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 1.5;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect: next item also fits here
            score -= 8.0;
            // extra reward if next item exactly fills the bin (harmonic completion)
            if next_item_size == post_residual {
                score -= 15.0;
            }
            // reward if post_residual - next lands on a harmonic boundary (multiple of 10)
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize slightly if this bin would be left very empty
            score += 3.0;
        }
    } else {
        // last item: strongly prefer tightest fit (post_residual already does this)
        score -= 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make empty bin attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, scaled by how crowded the current state is
        score += 30.0 + 2.0 * open_bins_count as f64;
        // if mean residual is large, open bins are fragmented; new bin less bad
        if mean_residual > 30.0 {
            score -= 12.0;
        }
        // early stream: opening bins is fine
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins (lower mean residual context => keep tight packing)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // Gap <= 10 is essentially dead space (min item size ~10); gap <= 20 is risky.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score += 60.0; // worst kind of dead space
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 30 {
        score += 8.0;
    }

    // Open-bins pressure: penalize spreading across many bins.
    if bin_residual < bin_capacity {
        score += open_bins_count as f64 * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // creates dead space relative to lookahead
    }

    // New-bin candidate: only attractive when all fits are poor.
    if bin_residual == bin_capacity {
        // Neutral base; slight penalty so we prefer decent existing fits.
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: open new bin
        }
    }

    // Late-stream tightening: as stream progresses, prefer tighter fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mild preference toward bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chains the next item into this bin
            score -= 60.0 + (next_item_size as f64 / 100.0) * 40.0;
            // Bonus if next item exactly fills the bin afterwards
            if next_item_size == post_residual {
                score -= 200.0;
            }
        } else {
            // Dead space for the lookahead item: penalize small leftover gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 30.0; // tiny unusable sliver
            } else if gap < 20.0 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    let diff = post_residual as f64 - mean_residual;
    score += 0.25 * diff;

    // Mild penalty for opening a new bin when decent fits exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin attractive only if no open bin fits well
        if fitting_bins_count > 0 {
            score += 25.0;
        } else {
            score -= 10.0;
        }
    }

    // Slight stream-awareness: later in stream, avoid fragmentation more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Brand-new empty bin candidate
    if bin_residual == bin_capacity {
        let mut nb = cap * 0.55;
        // Large items are cheap to start a fresh bin for; small items should try open bins first
        nb -= item_size as f64 * 0.45;
        // If few bins can fit this item, opening a new bin is safer
        nb -= (fitting_bins_count as f64).min(4.0) * 3.0;
        // Late in the stream, avoid proliferating bins
        nb += progress * 12.0;
        // If open bins are on average roomy, prefer them
        nb += (mean_residual / cap).clamp(0.0, 1.0) * 8.0;
        return nb;
    }

    let mut score = post_residual as f64;

    // Best-fit core: tight placement is good
    score -= (1.0 - post_residual as f64 / cap) * 2.0;

    // Keep space usable for the lookahead item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0; // residual remains valuable
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.08; // dead space for next item
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mild global pressure: many open bins -> consolidate into emptier ones
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);

    // Penalize tight fits more strongly late in the stream (dead-space aversion)
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (1.5 + 2.0 * progress);

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 4.0 + 3.0 * (nx / cap);
        } else {
            score += 1.5 * (nx - pr) / cap;
        }
    }

    // Mild dispersion penalty: keep residuals near the mean to preserve flexibility
    score += 0.3 * (norm_pr * cap - mean_residual).abs() / cap;

    // Slight preference for consolidating into fewer bins
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: make it less attractive unless residuals are all large
    if bin_residual == bin_capacity {
        score += 6.0 - 3.0 * progress + mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted if bin is abandoned here

    // Class boundaries: residual in (0,10] is a "perfect harmonic" (near-perfect fill)
    if post_residual == 0 {
        score -= 50.0; // perfect fit, strongly reward
    } else if post_residual <= 10 {
        score -= 20.0; // near-perfect harmonic class
    } else if post_residual <= 20 {
        score -= 8.0;
    } else if post_residual <= 40 {
        score += 3.0;
    } else {
        score += 10.0; // large dead space, penalize
    }

    // Modulo-arithmetic harmonic classes: residuals divisible by small harmonics
    // pair well with typical item sizes (multiples of 5/10)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0; // residual aligns with decimal harmonic class
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    }

    // Lookahead coupling: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            // integer-division threshold: how many times next item divides residual
            let k = post_residual / next_item_size.max(1);
            score -= 4.0 * k as f64;
        } else {
            // next item cannot follow here; residual becomes dead space unless
            // some future item of harmonic class fits
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but prefer keeping
    // current stream tight when many bins already open
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.8 {
            score -= 15.0; // big item coming, fresh bin is good
        }
    }

    // Stream progression: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - frac);

    // Tie-break toward bins below mean residual (balance harmonic classes)
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight-but-usable fits get a graded bonus (best-fit flavor).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit here is poor; otherwise penalize opening extra bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        if fitting_bins_count > 1 {
            score += 30.0 + 2.0 * open_bins_count as f64;
        }
        // If next item is large and this item leaves a tight residual, opening
        // a fresh bin can be better.
        if next_item_size > 0 && post_residual < next_item_size && item_size >= 60 {
            score -= 20.0;
        }
        score -= pressure.min(10.0);
    }

    // Slight preference for filling fuller bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild open-bin pressure: discourage scattering across many bins.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // dead space for the known next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 2.5 * (bin_capacity as f64 - gap).max(0.0) * 0.1;
        // exact match for next item is excellent
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // penalize leaving dead space the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Reward tight fits relative to mean residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Penalize bins far below mean residual (fragmented bins)
    if (bin_residual as f64) < mean_residual {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Mildly discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 50.0 + 2.0 * open_bins_count as f64;
    }

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 18.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 8.0 * fit_ratio;
    }

    // Penalize dead space: small post_residual is good, but post_residual
    // that cannot fit a typical next item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // near-perfect fill bonus
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64;
    score += 0.15 * open_pressure * (1.0 - fit_ratio);

    // Global residual state: if mean residual is large, be pickier (avoid
    // scattering items); if mean residual is small, fill anything.
    let mr = mean_residual.max(0.0);
    score += 0.05 * (mr - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins clean); late in the stream, fill existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, discounted early.
        score = 55.0 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 3.0; // slight preference against opening unless needed
        }
        if fitting_bins_count <= 1 {
            score += 40.0; // never open when a last-chance bin exists
        }
    } else {
        // Late stream: reward using existing bins.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic-ish preference for small post residual, smoothed
    let mut score = 2.0 * x * x - 1.5 * x;

    // Non-linear coupling with stream progress: early on, tolerate loose fits;
    // later, penalize dead space more aggressively.
    let progress_coupling = (x * x) * (0.5 + 2.0 * progress * (1.0 - 0.5 * progress));
    score += 3.0 * progress_coupling;

    // Smooth interaction: post residual vs mean residual (prefer bins tighter than the mean)
    let mean_norm = mean_residual / cap;
    score += 0.8 * (x - mean_norm) * (1.0 + x * x);

    // Lookahead term: reward if next item fits the post residual (smooth sigmoid-like)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = x - nx;
        let s = 1.0 / (1.0 + (-8.0 * fits).exp());
        score -= 1.2 * s;
        // penalize if post residual is just barely too small for next item (dead space risk)
        let near_miss = (-6.0 * (fits + 0.05)).exp() * (fits < 0.0) as i32 as f64;
        score += 0.6 * near_miss * (0.5 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 + x);
    }

    // Mild penalty for many open bins (encourage consolidation), scaled smoothly
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 + x);

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * (1.0 - progress) - 0.5 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into residue classes mod 10
    // (item sizes are multiples of 10 in the canonical stream, so leftovers mod 10 == post_residual mod 10
    //  tells us which future item sizes can exactly fill the gap).
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.75; // penalize leftovers that no canonical item can exactly fill

    // Exact-fill harmonic bonus: leftover exactly matches a plausible item size class
    if post_residual > 0 && post_residual <= 80 {
        // leftover that is a "harmonically reachable" size (any multiple of 10 <= 80)
        score -= 4.0;
    }

    // Perfect fit: zero dead space is ideal
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: nonlinear in leftover fraction
    let frac = post_residual as f64 / cap;
    if frac > 0.0 {
        score += 12.0 * frac * frac; // quadratically punish growing dead space
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains perfectly into this bin -> strong reward
            score -= 8.0 + 0.05 * next_item_size as f64;
            if next_item_size == post_residual {
                score -= 10.0; // perfect chain: both items harmonically tile the bin
            }
        } else {
            // next item won't fit here; penalize more if leftover is awkwardly small
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap;
        }
    }

    // Last-chance logic: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin starts with full residual
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for very large items or when open bins are nearly full
        let mean_frac = mean_residual / cap;
        // default: discourage new bin mildly
        score += 6.0;
        if item_size >= 50 && mean_frac < 20.0 / cap {
            score -= 20.0; // big item, existing bins nearly exhausted -> open new bin
        }
        if open_bins_count == 0 {
            score -= 100.0; // must have at least one bin
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Prefer tighter existing bins: reward small residual before placement
        score -= 0.03 * bin_residual as f64;
    }

    // Congestion-aware tiebreak: many open bins -> favor filling them, not spawning more
    score += 0.15 * open_bins_count as f64;

    // Mean-residual harmonic alignment: favor bins whose residual is near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Gap is "unusable" if smaller than the smallest plausible item (<= 10) or
        // smaller than the lookahead item that could otherwise exploit it.
        let min_item = 10.0f64.min(bin_capacity as f64);
        if dead < min_item {
            score += 12.0 * (min_item - dead);
        } else if next_item_size > 0 && (dead as u32) < next_item_size {
            // Gap cannot host the next item either -> likely dead space.
            score += 4.0 * (1.0 - dead / 100.0);
        } else {
            // Usable gap: mild reward relative to tightness of fit.
            score -= 2.0 * (1.0 - dead / bin_residual.max(1) as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tight fit bonus: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening yet another bin
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 6.0 + 4.0 * pressure;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is near the mean (balanced consolidation),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Lookahead synergy: reward if the post-fit gap exactly accommodates next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward bins where the NEXT item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: reward proportionally to how snugly the next item fits.
            let leftover2 = post_residual - next_item_size;
            score -= 25.0 * (1.0 - leftover2 as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a mid-sized gap
            // that is neither empty nor usable (dead space).
            score += 15.0;
            if post_residual < 10 {
                score -= 10.0; // tiny gap is fine, effectively a perfect fit
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (i.e., item leaves large dead space in every open bin).
    if bin_residual == bin_capacity {
        let would_be_post = bin_capacity - item_size;
        let next_fits_new = next_item_size > 0 && would_be_post >= next_item_size;
        if next_fits_new {
            score -= 12.0; // fresh bin supports a clean 2-item chain
        } else {
            score += 25.0; // discourage scattering into new bins
        }
        if open_bins_count > 0 && post_residual >= 0 && bin_residual >= item_size {
            // penalize opening new bins early in the stream
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with a non-linear bias
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = 1.0 - (post / cap); // 1.0 = perfect fit
    score -= 40.0 * fit_ratio * fit_ratio;

    // Strongly penalize dead space that cannot fit even the smallest plausible item
    if post_residual < 10 {
        score -= 25.0; // nearly-full bin is great (close it out)
    } else if post_residual <= 20 {
        score += 8.0 * (1.0 - fit_ratio); // small awkward残 leftover
    }

    // Lookahead: reward if the next item fits exactly into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty for leaving a mid-sized hole
            score += 6.0 * (post / cap);
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // competition among bins: rely mainly on fit tightness
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well or we are early with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let urgency = (mean_residual / cap - 0.5).max(0.0); // high mean residual => open bins are full-ish
        let bias = 60.0 - 30.0 * poor_alternatives - 40.0 * urgency - 20.0 * (1.0 - progress);
        score += bias; // keep new bin attractive only under poor conditions
        // perfect-fit guard: never open a bin for a tiny item if it wastes capacity
        score += 0.5 * item_size as f64;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    if open_bins_count > 2 {
        let consolidation = (mean_residual / cap).clamp(0.0, 1.0);
        score -= 10.0 * consolidation * ((open_bins_count as f64).ln() + 1.0) * (1.0 - fit_ratio);
    }

    // Time horizon: late in the stream, be more conservative (prefer filling existing bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * progress * (1.0 - fit_ratio);

    // Mild preference toward bins with residual close to item_size (exactness)
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr as f64;

    // Quadratic/cubic dead-space penalties scaled by progress.
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    score += 8.0 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    score -= 25.0 * (1.0 - norm_pr) * fit * (0.6 + 0.8 * progress);

    // Penalize when the next item cannot use the residual (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = (nx / (pr + 1.0) as f64).min(1.0);
        score -= 10.0 * usable * (1.0 - progress);
        score += 6.0 * (1.0 - usable) * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Slight preference for bins below mean residual early (balance load),
    // above mean later (consolidate).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * (2.0 * progress - 1.0);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: prefer opening fresh bins when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        score -= 15.0 * fragmentation * (1.0 - progress);
        score += 10.0 * (1.0 - fragmentation) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that commonly pair with future items
    // (capacity 100 -> classes of 10). Small usable residues are valuable; large
    // residues are fine too; the "dead zone" (1..=9) is waste.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space: post_residual in 1..=9 is nearly unusable (min item 1,
    // but typical items are larger). Class-based penalty with modulo structure.
    let dead = if post_residual > 0 && post_residual < 10 { (10 - post_residual) as f64 * 4.0 } else { 0.0 };
    score += dead;

    // Reward exact/near-exact fills: harmonic class 0 (post_residual % 10 == 0)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Reward classes 10..=30 which pair well with mid-size items
    if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly prefer.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // next item leaves another residue; evaluate its class
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 10.0; }
            if nr < 10 { score += 3.0; } // creates new dead space
        } else {
            // next item cannot use this bin's remainder; slightly penalize tiny remainders
            if post_residual < next_item_size && post_residual < 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // base preference for opening new bin when few bins or late stream
        score = cap - item_size as f64;
        // penalize new bin when existing bins fit well (fitting bins exist and
        // current item is small enough that a poor fit isn't forced)
        if fitting_bins_count > 0 && item_size <= 50 {
            score += 25.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // new bin can hold item + next item tightly
        }
        // reward opening new bin late in stream when mean residual is low
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 15.0 && progress > 0.5 {
            score -= 10.0;
        }
    } else {
        // Mild preference for tighter fits among open bins: reward small post_residual
        // with a harmonic (inverse) coupling
        if pr > 0.0 {
            score -= 40.0 / pr.max(1.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=12) are nearly unusable -> heavy penalty.
    if post_residual >= 1 && post_residual <= 12 {
        score += 45.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: more open bins -> prefer reusing existing bins,
    // penalize opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in the post gap but the gap is small, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(15) {
        score += 6.0;
    }

    // Prefer bins tighter than the mean residual (good fits first).
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate harder.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-step fit: post_residual exactly matches the next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect fit: next item fits with a little slack left.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward decreases as slack grows; small slack (< 10) is valuable.
        score -= (20.0 * (10.0 - slack.min(10.0)) / 10.0).max(0.0);
    }
    // Dead space: post_residual too small for any plausible next item (items >= 1,
    // but typical items are >= 10). Penalize small nonzero leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // If next item cannot fit here, mild penalty so we prefer bins where chain continues.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare residual against mean residual of open bins:
    // prefer bins with below-average residual (tighter bins) to keep large residuals available.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin has a large post_residual, which
    // naturally scores high (bad). Give it a calibrated bonus only when open bins
    // are nearly full on average, so a new bin is opened only when necessary.
    if bin_residual == bin_capacity {
        if mean_residual < 15.0 {
            score -= 40.0; // open a fresh bin when existing ones are nearly exhausted
        } else {
            score += 50.0; // discourage wasting a fresh bin on a poor fit
        }
    }

    // Late in the stream, consolidate more aggressively (fewer wasted bins at the end).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: prefer small post_residual, but with a smooth non-linear penalty
    // that punishes both large leftover space and razor-thin residuals
    // (dead space that nothing can use).
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, keep bins roomy; late, squeeze harder.
    score += 40.0 * norm_post * norm_post * (1.0 + 2.0 * progress);

    // Reward tight fits: quadratic bonus when post_residual is small
    // relative to item size (smooth, non-piecewise).
    let tightness = 1.0 - norm_post;
    score -= 30.0 * tightness * tightness * norm_item;

    // Penalize unusable dead space: residuals smaller than the smallest
    // plausible item (~10) are worthless; use smooth saturation, not a cutoff.
    let dead = (10.0 - post).max(0.0) / 10.0;
    score += 25.0 * dead * dead;

    // Lookahead coupling: if the next item fits smoothly into the
    // resulting residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 8.0 * ((-gap) / cap) * (1.0 - progress);
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it mildly unattractive by default, but
    // attractive when open bins are all badly fragmented (high mean
    // residual spread vs this bin's residual).
    if bin_residual == bin_capacity {
        let fragmentation = ((mean_residual - post).abs()) / cap;
        score += 35.0 - 50.0 * fragmentation * fragmentation;
        // Late in the stream, opening fresh bins is cheaper.
        score -= 20.0 * progress;
    }

    // Mild penalty for proliferating many open bins.
    score += 1.5 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but penalize post_residuals that are "dead" (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space class: nothing (min size 1..10) may ever use it well
    }

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    score -= (quarter as f64 - class as f64).abs() * 0.05;

    // Reward leaving room for the lookahead item (harmonic pairing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let pair_waste = post_residual - next_item_size;
            score -= 8.0;
            if pair_waste < 10 {
                score -= 15.0; // perfect two-item chain
            }
        } else {
            score += 6.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = fitting_bins_count > 0 && (bin_residual - item_size) as f64 <= mean_residual;
        if good_fit_exists {
            score += 40.0; // discourage new bin when a fitting bin exists
        } else {
            score -= 20.0 * (1.0 - progress.min(1.0)); // early stream: open bins more freely
        }
        // Don't open a new bin if the next item is large and current fits fine
        if next_item_size > 0 && post_residual >= next_item_size && !good_fit_exists {
            score -= 5.0;
        }
    }

    // Integer-division threshold: post_residual in upper half of capacity is wasteful
    if post_residual > bin_capacity / 2 {
        score += 10.0;
    }

    // Slight preference for filling bins with low residual relative to the mean
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gap creation).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Penalize leaving residual that is just barely below the smallest item (1..100 range):
    // a residual of exactly small values wastes capacity.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open,
    // but allow opening a new bin when few bins exist or fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += bin_pressure * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this bin's post-fit
    // residual would be dead space AND the next item could use a full bin better.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Mild penalty so we only open new bins when open-bin placements are bad.
        score += 15.0;
        if next_item_size > 0 && next_item_size <= item_size {
            // Next item is small; a fresh bin is less attractive.
            score += 10.0;
        }
        if post_residual >= dead_threshold {
            // Fresh bin keeps large usable residual; slight reward if current
            // open bins are congested (mean residual low).
            if mean_residual < item_size as f64 {
                score -= 20.0;
            }
        }
    } else {
        // Reward placements that keep residual usable for the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize if post residual is large but mean residual is already high
        // (bins are getting empty-ish; better to consolidate).
        if post_residual as f64 > mean_residual + 30.0 {
            score += 8.0;
        }
    }

    // Slight preference for tighter fits overall (small post_residual relative to item).
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact match: place here so next item fills this bin
        } else {
            score += diff * 0.5; // near-miss penalty
        }
        // If next item fits exactly in the CURRENT residual (i.e. item + next fill bin)
        if next_item_size == item_size && bin_residual == next_item_size * 2 {
            score -= 25.0;
        }
    }

    // Dead-space penalty: tiny leftovers that nothing (min size 1..) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer tighter fits relative to the mean residual of open bins
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 + 30.0 * progress;
        // But if the item is large and would leave a very tight fit, allow new bin
        if post_residual == 0 {
            score -= 20.0; // perfect fill of a fresh bin is fine
        }
    }

    // Reward filling bins nearly exactly
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + (5 - post_residual) as f64 * 20.0;
    } else {
        // Penalize dead space that is too small for any plausible future item (sizes >= 1).
        // Dead space in (0, 10) is nearly unusable; dead space >= 10 may still host items.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 {
        // Slight penalty if this placement strands the next item in this bin.
        score += 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a new bin grows with number of open bins (fragmentation control).
        let mut new_bin_score = 260.0 + open_bins_count as f64 * 12.0;
        // Early in the stream, opening bins is cheaper (build a portfolio of bins);
        // late in the stream, consolidation matters more.
        new_bin_score *= 1.0 + 0.5 * (1.0 - progress);
        // If mean residual of open bins is large, we should use existing space instead.
        new_bin_score += mean_residual * 0.8;
        // If no other bin fits (fitting_bins_count == 1 refers to this new bin being counted),
        // opening is inevitable: soften the penalty.
        if fitting_bins_count <= 1 {
            new_bin_score -= 200.0;
        }
        score = new_bin_score;
    }

    // Mild preference for fuller bins among comparable residuals (tight-packing bias).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Small noise-free tie-breaker based on bin index proxy (residual ordering).
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear curvature
    let mut score = pr * (1.0 + 0.5 * x * x);

    // Smooth polynomial coupling of tightness with stream progress:
    // late in the stream, tighter fits matter more (dead space cost grows)
    let tightness = 1.0 - x; // how full the bin becomes
    score -= (progress * progress * (3.0 - 2.0 * progress)) * 30.0 * tightness * tightness * tightness;

    // Penalize residuals that cannot plausibly fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            let g = (gap / cap).min(1.0);
            score += 20.0 * g * g * (1.0 + progress);
        } else {
            // next item fits: reward, stronger when bin becomes near-perfect for it
            let fit_quality = 1.0 - ((-gap) / cap);
            score -= 10.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bonus: only one fitting bin -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize slightly unless residuals across open bins are large
    if bin_residual == bin_capacity {
        let waste = (mean_residual / cap).clamp(0.0, 1.0);
        score = 60.0 - 40.0 * waste * waste - 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins (fragmentation), smooth in count
    let frag = (open_bins_count as f64).ln() + 1.0;
    score += 0.5 * frag * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: exact-fit classes are golden.
    let class = post_residual / 10;
    match class {
        0 => score -= 60.0,          // perfect fit
        1 => score -= 35.0,          // tiny dead space
        2 => score -= 20.0,
        3 => score -= 10.0,
        4 => score -= 5.0,
        5 => score += 5.0,           // half-full leftovers are ambiguous
        6 => score += 10.0,
        7 => score += 15.0,
        8 => score += 22.0,
        _ => score += 30.0,          // nearly empty bin used wastefully
    }

    // Reward if the lookahead item fits exactly into the post-residual class.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 55.0;
        } else if gap <= 10 {
            score -= 30.0;
        } else if gap <= 20 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // leftover too small for anything useful: dead space penalty
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 + 1.0).ln();
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 25.0 * pressure; // prefer the last-chance open bin
        } else {
            score += 15.0 + 5.0 * pressure; // plenty of alternatives
        }
    }

    // Mild preference to fill bins that deviate above the mean residual
    // (consolidate space into fewer bins over the stream).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) > mean_residual {
        score -= 6.0 * (1.0 - progress);
    } else {
        score += 3.0 * progress;
    }

    // Exact modular harmony: post_residual divisible by common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let gap = post_residual as f64;
        let smallest_item = 1.0f64; // items can be as small as 1
        // gap below typical small-item threshold is nearly dead space
        if gap < 15.0 {
            score += (15.0 - gap) * 6.0; // steep penalty for tiny gaps
        } else {
            score += gap * 0.15; // mild penalty for larger leftover space
        }
        let _ = smallest_item;
    } else {
        // perfect fit reward
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin used
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new-bin candidate
        score += 18.0 + open_bins_count as f64 * 2.5;
        // but if the item fits poorly everywhere, new bin may be fine
        if post_residual as f64 > mean_residual {
            score -= 8.0;
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    } else {
        // existing bin: mild reward scaled by how much it exceeds mean residual usage
        score -= (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    }

    // Lookahead: if next item would fit the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // dead space relative to the next item
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match (post_residual == next_item_size) gets a strong bonus.
        if diff == 0.0 {
            score -= 40.0;
        } else if next_item_size as f64 <= post_residual as f64 {
            // Next item fits in the leftover space: proportional bonus, tighter is better.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize proportionally to wasted residual vs next item.
            score += 8.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    } else {
        // Last item: simply prefer minimal post residual.
        score -= 5.0;
    }

    // Compare against mean residual: bins already tighter than average are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating small unusable dead space (post_residual too small to be useful
    // for typical item sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference for keeping more open bins consolidated when many bins are open.
    if bin_residual != bin_capacity {
        score -= 0.1 * open_bins_count as f64;
    }

    // Mild stream-progression adjustment: later in the stream, tighten more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize leaving dead space that can't host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size as f64 {
            score += (next_item_size as f64 - post_residual as f64) * 0.8;
        } else {
            score -= 0.5; // next item fits here; slight bonus
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Reward using well-filled bins (low residual relative to mean).
    let fill = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= fill * 4.0;

    // Penalize bins far below mean residual (fragmented low-fill bins) mildly.
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Time horizon: early in stream, be more willing to open new bins
    // (score for empty new bin candidate stays high); late, consolidate.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus exploration discount early.
        score = bin_capacity as f64 * 0.9 - t * 10.0 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 2.0; // pairing large items together in fresh bin
        }
    }

    // Many open bins: discourage spreading; favor consolidation into existing bins.
    score += open_bins_count as f64 * 0.15;

    // Prefer placing larger items into tighter bins.
    score -= (item_size as f64) * fill * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let base = pr * pr / cap;
    let coupling = base * (0.5 + progress * (1.0 - progress) * 4.0);
    let mut score = pr + coupling;
    // penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) * (1.0 + progress);
        } else {
            score -= (pr - ni).min(40.0) * 0.3 * (1.0 - progress);
        }
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    }
    // discourage opening new bins when many open bins exist and fit is tight
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
    } else {
        score -= 3.0 * (1.0 - (pr - mean_residual).abs() / cap).max(0.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let frac = post_residual as f64 / cap; // 0..1
    let class = (frac * 8.0).floor() as i32; // 0..7 harmonic classes

    // Reward small residuals (tight fits), strongest for class 0 (near-perfect fit).
    score -= (8 - class.min(7)) as f64 * 6.0;

    // Penalize residuals in the "dead zone" that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly or well into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack.min(20.0); // good chaining, decays with slack
        } else {
            // next item cannot use this bin's remainder: slight penalty scaled by leftover
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // (i.e., item is large relative to residuals) or many bins are open.
    if bin_residual == bin_capacity {
        let spread = mean_residual - post_residual as f64; // mean residual minus empty-bin residual
        // Empty bin is attractive when mean residual of open bins is small (poor fits available)
        // or many bins already open (diversify residual classes).
        score = 60.0 + frac * 0.0;
        score -= mean_residual * 0.8;
        score -= open_bins_count as f64 * 1.5;
        // Large items prefer a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
        // Progress: late in the stream, consolidation matters more; penalize new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
        let _ = spread;
    }

    // Mild coupling: prefer bins whose residual deviates from the mean in a useful way
    // (placing into a below-mean residual bin concentrates usage).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward exact fit for the known next item (lookahead coupling).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins with residual already below mean (denser bins).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized early,
    // but attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score = 100.0 + post_residual as f64;
        if fitting_bins_count <= 2 {
            score -= 30.0;
        }
        if mean_residual < 20.0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post-residual that exactly
    // matches (or closely matches) the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is extremely desirable.
        if diff == 0.0 {
            score -= 60.0;
        } else if post_residual as f64 >= next_item_size as f64 {
            // Next item still fits after this placement: mild reward scaled by closeness.
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit in this bin: penalize wasted lookahead opportunity.
            score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 5.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "drier";
    // filling them is good, but leaving tiny unusable slivers is bad.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 0.5 * (mean_residual - post_f);
    } else {
        score += 0.3 * (post_f - mean_residual);
    }

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_f > 0.0 && post_f < 10.0 {
        score += 12.0 * (10.0 - post_f);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 20.0 - 10.0 * pressure + 5.0 * progress;
        // If lookahead can pair with a fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 6.0;
        }
    }

    // Mild reward for keeping the number of open bins from exploding.
    score -= 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, non-linear bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: many open bins with large mean residual -> prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins have big residuals (poor fits everywhere).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fit_everywhere = mean_residual > item_size as f64 + 15.0;
        let penalty = if poor_fit_everywhere && large_item > 0.6 {
            5.0 // opening a new bin is reasonable for big items with poor fits
        } else {
            45.0 + 20.0 * (1.0 - large_item)
        };
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: quadratic waste penalty scaled by stream progress
    let norm_pr = pr / cap;
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress) * cap * 0.1;

    // Reward tight fits smoothly: cubic decay of post_residual
    score -= 8.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Penalize leaving residuals that no plausible next item fits (smooth logistic gate)
    let next = next_item_size as f64;
    if next > 0.0 {
        let gate = 1.0 / (1.0 + (-(pr - next) / 10.0).exp());
        score += 5.0 * gate * (next / cap);
    }

    // Last-chance bonus: smooth interaction with fitting_bins_count
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 4.0 * last_chance * (1.0 - norm_pr);

    // Slight preference for consolidating into fewer bins early on
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (still useful for future items) are rewarded.
    let pr = post_residual;
    let class = pr / 10; // integer division threshold classes: 0..10
    // Reward small classes (tight fits), penalize mid-range dead space.
    match class {
        0 => score -= 18.0,                    // near-perfect fit
        1 => score -= 12.0,                    // very tight
        2 => score -= 7.0,                     // tight
        3 => score -= 3.0,
        4 => score += 1.0,
        5 => score += 4.0,                     // half-full leftover, mediocre
        6 => score += 5.0,
        7 => score += 4.0,
        8 => score -= 1.0,                     // large residual still flexible
        9 => score -= 2.0,
        _ => score -= 3.0,                     // empty-ish bin
    }

    // Modulo coupling: residues mod 5 that align with common item sizes
    // (items often cluster near multiples of 5/10) are more reusable.
    if pr % 5 == 0 && pr > 0 {
        score -= 2.5;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 5 {
                score -= 8.0;
            } else if slack <= 15 {
                score -= 3.0;
            }
        } else {
            // next item cannot use this residual: residual is dead-ish
            let miss = next_item_size - pr;
            if miss <= 10 {
                score += 6.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.35 * (0.5 + progress);

    // Residual vs mean: bins tighter than the mean are better targets.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive for large items that would leave
    // open bins too fragmented, or when no bin fits well.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Base penalty for opening a new bin.
        score += 14.0;
        // Large items justify fresh bins.
        if item_frac > 0.6 {
            score -= 10.0 * (item_frac - 0.6) / 0.4;
        }
        // If this is the only fitting option (or few fit), soften penalty.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // Early in the stream, fresh bins are cheaper.
        score -= (1.0 - progress) * 4.0;
        // If mean residual of open bins is small (all crowded), new bin helps.
        if mean_residual < item_size as f64 {
            score -= 6.0;
        }
    }

    // Guard against pathological negative domination: keep ordering sane.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // Gaps below the minimum plausible item size are almost certainly dead space.
    let min_item = 1u32;
    if post_residual < 20 && post_residual >= min_item {
        // Tight-dead-space penalty: smaller gaps are worse per unit.
        let deadness = (20 - post_residual) as f64 / 19.0;
        score += 18.0 * deadness * deadness;
    }

    // Reward near-perfect fills strongly (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Open-bin pressure: penalize spreading across many open bins; encourage
    // consolidating into existing bins rather than opening new ones.
    let open_pressure = open_bins_count as f64;
    if bin_residual != bin_capacity {
        // Existing bin: reward it relative to how many bins are open.
        score -= 2.0 + 0.35 * open_pressure.sqrt();
    } else {
        // New-bin candidate: base penalty that grows with open-bin count,
        // but shrinks if the current bin would leave a bad dead gap.
        let bad_fit = if post_residual < 20 && post_residual > 0 { 1.0 } else { 0.0 };
        score += 6.0 + 0.9 * open_pressure - 10.0 * bad_fit;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement; if next item would be blocked by a small gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual < 20 {
            score += 6.0;
        } else if next_item_size < post_residual {
            score -= 3.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — filling it is efficient (reward); a very loose bin
    // can absorb awkward sizes (mild reward for using it when gap is bad).
    let resid_f = bin_residual as f64;
    let dev = resid_f - mean_residual;
    if dev < 0.0 {
        score += 0.05 * dev; // negative dev lowers score -> favors tight bins
    }

    // Stream progression: late in the stream, be more conservative about
    // opening new bins and more aggressive about tight fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 4.0 * progress;
    } else {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward when the next item exactly fills the post residual (perfect 2-step packing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            // partial fit: reward proportional to how much of the leftover gets used
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * usage;
            // penalize remaining sliver after the 2nd item
            let sliver = post_residual - next_item_size;
            if sliver > 0 && sliver < 10 {
                score += 15.0; // tiny dead sliver is useless
            }
        } else {
            // next item can't use the leftover: penalize dead space
            score += 8.0;
        }
    }

    // Perfect bin closure bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small unusable residuals are dead space
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Compare residual against mean residual across open bins: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 10.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no future item (>=10, or 1 in general) can use
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 0 + 1 {
        score += 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Lookahead: reward leaving post_residual that can host the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // post_residual too small for next item: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Global state: with many open bins, prefer consolidation (low mean_residual bins)
    let mean_r = mean_residual.max(0.0);
    if (bin_residual as f64) < mean_r {
        score -= 6.0; // below-average residual bin: pack it tighter
    } else {
        score += 4.0;
    }

    // Time horizon: early in stream, keep bins flexible (mild penalty for very small leftovers);
    // late in stream, aggressive packing of tight bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0 * (1.0 - tightness);

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when many bins open / poor alternatives
        score += 30.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items with fresh space can help
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr_norm * (1.0 + 1.8 * progress * pr_norm + 0.9 * progress * progress);

    let mut score = poly * cap;

    // Penalize large dead space more than proportionally (cubic term).
    score += 12.0 * pr_norm * pr_norm * pr_norm * cap;

    // Reward tight fits: small post residual.
    score -= 6.0 * (1.0 - pr_norm).exp();

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        let diff = (pr as i64 - next_item_size as i64).abs() as f64;
        score -= 5.0 * (-diff / 20.0).exp();
        if next_item_size as f64 > pr {
            score += 3.0 * pr_norm; // post residual likely unusable
        }
    }

    // Mild pressure to close near-full bins relative to mean residual.
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: neutral baseline, slightly discouraged early, allowed late.
    if bin_residual == bin_capacity {
        score = cap as f64 * (0.9 + 0.4 * progress);
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact small remainders are valuable
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    }

    // Modulo-class penalty: dead space in awkward residue classes (e.g. 31..49, 51..69)
    let class = pr % 10;
    if pr > 20 {
        match class {
            0 => score -= 8.0,          // round remainder, reusable
            1 | 2 | 3 => score += 2.0,  // awkward slivers
            4 | 5 | 6 => score += 4.0,
            _ => score += 1.0,
        }
    }

    // Integer-division threshold: can post_residual host the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // reward chains that keep the next item in this bin
            score -= 15.0;
            // harmonic match: post_residual divisible by next item size class
            if next_item_size > 0 && pr % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else {
            // penalize creating dead space the next item cannot use
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only prefer it when the fit is terrible
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = cap_f * 0.85;
        if fitting_bins_count == 0 {
            score = 0.0; // must open anyway
        } else if next_item_size > 0 && item_size as f64 >= cap_f * 0.5 {
            // large item: fresh bin keeps future flexibility
            score -= 25.0;
        }
        if pr == 0 { score -= 5.0; }
    }

    // Progress coupling: late in stream, tighten packing (waste less)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 6.0;

    // Prefer filling bins far below mean residual (reduces fragmentation)
    let res_frac = post_residual as f64 / cap_f;
    if res_frac < mean_residual / cap_f {
        score -= 5.0;
    }

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Medium gaps are partially usable but risky
        score += 8.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Non-linear tightness reward: tighter fit => bigger discount
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to this item (good relative fit)
    let rel_fit = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * rel_fit;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would strand this bin, mild penalty unless gap is large
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 10.0;
    }

    // Mean residual coupling: if this bin is far below mean residual, it's a poor candidate
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: keep it competitive only when item is large and no tight fits exist
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits -> new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // residual that still accommodates the next item is good, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot fit here; penalize proportional to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(30.0);
        }
    } else {
        // last item: prefer minimal leftover
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: bins with residual below mean are tighter, prefer filling them
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Penalize dead space: residuals too small for any item (min size 1, but typical small items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Mild preference for consolidating when many bins are open
    score += (open_bins_count as f64) * 0.05;

    // Slight progression term: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (100.0 - post_residual as f64) * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact and near-exact fits are gold: strongly reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: mildly discourage, but allow when item is large
    // or when the next item would pair well with the fresh residual.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.15 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 10.0; // big items are hard to place later; give them a fresh bin
        }
        if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
            score -= 6.0; // next item can join this fresh bin
        }
    }

    // Lookahead coupling: reward when the next item exactly fills the resulting hole.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 12.0;
        } else if gap <= 3 {
            score -= 6.0;
        }
        if next_item_size as u32 > post_residual {
            score += 3.0; // next item won't fit here anyway; less concern about hole size
        }
    }

    // Time horizon: late in the stream, prefer denser packing (larger used space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Global state: prefer bins whose residual deviates favorably from the mean
    // (packing into below-average-residual bins keeps the pool of flexible bins).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Slight preference for bins that were already partially used when many bins open.
    if open_bins_count > 6 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: post-residual, with smooth polynomial coupling to stream progress
    let mut score = pr;

    // Reward low post-residual more strongly as stream progresses (tighten packing late)
    let tight_gain = (1.0 - x) * (1.0 - x) * (1.0 + 3.0 * progress) * 20.0;
    score -= tight_gain;

    // Penalize very small dead space that is hard to fill later (smooth cubic term)
    let dead = (x * (1.0 - x)) * (1.0 - x) * 15.0;
    score += dead;

    // Interaction with mean residual: prefer bins below mean residual (tighter than average)
    let mr = mean_residual / cap;
    score += (mr - x) * 10.0 * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 2.0 * progress);
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_gap = (pr - nxt) / cap;
            score -= (1.0 - fit_gap) * (1.0 - fit_gap) * 18.0;
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across many open bins early on
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: 8 classes of capacity/8
    let class = (post_residual * 8) / bin_capacity; // 0..=7
    let class_w = [0.0, 2.0, 6.0, 14.0, 26.0, 42.0, 62.0, 86.0][class as usize];
    score += class_w;

    // Exact-fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Small dead-space classes penalized more harshly than linear
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect harmonic match: next item fills a class exactly
            if post_residual % next_item_size == 0 {
                score -= 30.0;
            } else {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize wasted residual proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // next item is large: prefer bins with big residual
        if next_item_size >= 60 {
            score += post_residual as f64 * 0.3;
        }
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (post_residual as f64)).abs();
        let base = 120.0 - 60.0 * progress;
        // open new bin if mean residual is small (open bins nearly full)
        score = base + fragmentation * 0.5;
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference to fill bins below mean residual (balance avoidance of many half bins)
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins / reward filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 8.0 * pressure;
    } else {
        score -= 3.0 * pressure;
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Slight preference for bins below mean residual (fill emptier-relative bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the
    // post_residual, this placement is perfect.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards: mildly good, prefer leaving
            // a residual close to next_item_size.
            score -= 20.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += 15.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - post / cap;
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Next item won't chain here; mild penalty scaled by wasted potential.
        score += 8.0 * (1.0 - post / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: prefer new bins only when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Cost of opening a new bin, discounted early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 + 40.0 * progress;
        // If no open bin can fit at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If next item is large, a fresh bin preserves room for it.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    let consolidation = (mean_residual / cap) * (open_bins_count as f64).ln1p();
    if !is_new_bin {
        score -= 10.0 * consolidation * tightness;
        // Penalize placing into bins far from mean residual (imbalance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Late-stream pressure: near the end, prefer filling existing bins tightly.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * horizon * tightness;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a mild convexity
    // so very small residuals are disproportionately attractive.
    let mut score = post + 0.35 * (post * post) / cap;

    // Non-linear coupling with stream progress: late in the stream, tight
    // packing matters more, so amplify the tightness reward.
    score *= 1.0 + 0.8 * progress * (post / cap);

    // Lookahead synergy: reward when the next item can also fit the
    // resulting residual (smooth coupling, stronger later in stream).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let synergy = 1.0 - (fits_next / cap);
        score -= 6.0 * synergy * (1.0 - progress * 0.5);
    }

    // Dead-space penalty: residuals too small for typical future items
    // are wasteful; smooth quadratic in how close residual is to zero.
    let dead = ((20.0 - post).max(0.0)) / 20.0;
    score += 9.0 * dead * dead;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mildly prefer tighter fits via residual.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Some open bin fits: penalize opening a new bin, more so
            // when mean residual across open bins is still usable.
            let usable = (mean_residual / cap).min(1.0);
            score += 18.0 + 20.0 * usable;
        } else {
            // No open bin fits: opening a new bin is necessary.
            score -= 30.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Perfect fit dominates everything.
    if post_residual == 0 {
        return -1000.0;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item (<=10)
    // are pure waste, but tiny residuals are less bad than mid-size awkward gaps.
    if post_residual < 10 {
        score -= 40.0; // nearly-perfect fill, reward strongly
    } else {
        // Harmonic band penalty: quantize residual into eighths of capacity.
        let band = (pr / 12.5).floor(); // 0..8
        score += band * 3.0;

        // Modular coupling: residual divisible by common item sizes is reusable.
        let p = post_residual;
        if p % 10 == 0 { score -= 12.0; }
        else if p % 5 == 0 { score -= 6.0; }
        if p % 20 == 0 { score -= 6.0; }
        if p % 25 == 0 { score -= 5.0; }
    }

    // Lookahead coupling: does the residual exactly or closely fit the next item?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = pr - n;
            if slack == 0.0 { score -= 60.0; }
            else if slack < 10.0 { score -= 25.0; }
            else { score -= 10.0 * (1.0 - slack / cap); }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 8.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it mildly
    // unattractive unless existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        // if stream is late and many bins are open with mean residual that can
        // still absorb typical items, discourage new bins further
        if mean_residual > 30.0 {
            score += 15.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if next item is huge, a fresh bin has future value
        if next_item_size >= 60 {
            score -= 25.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    // Strict dead-space penalty: gaps too small to hold the NEXT item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to what the next item would need.
        let dead = (next_item_size - post_residual) as f64;
        score += 2.5 * dead;
        // Harsher if the gap is tiny (unusable for most items).
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Reward exact-ish fits strongly.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is near the mean (balanced packing) slightly.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: only attractive when the current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin by default.
        score += 12.0;
        // But if the item is huge and leaves a small gap anyway, a fresh bin is fine.
        if item_size >= 70 && post_residual <= 15 {
            score -= 14.0;
        }
        // Late in the stream with many open bins, avoid proliferation.
        if progress > 0.7 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // leftover after both placements
            let two_step = post_residual - next_item_size;
            score -= (bin_capacity as f64 - two_step as f64) * 0.5;
            if two_step == 0 {
                score -= 400.0;
            }
        } else {
            // next item cannot follow into this bin: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Penalize dead space relative to mean residual
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin unless fit is terrible
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
        if post_residual <= 10 {
            score -= 100.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 250.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0; // fresh bin can host a pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight packing non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to capacity (small unusable leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly-full is fine; tiny slivers are actually good
        score -= 25.0;
    }
    // Actually: tiny post_residual is desirable (perfect fit), reward it.
    if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 15 {
        score -= 8.0;
    } else if post_residual < 30 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item can use the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin; adjust with stream state.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 40.0;
        // Late in stream, prefer closing out existing bins.
        open_cost += 20.0 * progress;
        // Many open bins with slack -> avoid opening more.
        open_cost += (open_bins_count as f64).sqrt() * 4.0;
        // High mean residual means open bins have room; discourage new bin.
        open_cost += (mean_residual / bin_capacity as f64) * 15.0;
        // Large items relative to typical residual may justify a fresh bin.
        open_cost -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // If next item is huge, a fresh bin with room is attractive.
        if next_item_size >= 60 {
            open_cost -= 10.0;
        }
        score += open_cost;
    }

    // Mild global regularization: spread load when many bins are open.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time-horizon term: early stream, be conservative with tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 1.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, waste is more costly
    let late_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late_weight * pr_norm * cap * 0.35;

    // Penalize residual slightly above mean (dead space relative to fleet)
    score += (pr - mean_residual) * 0.15;

    // Reward near-perfect fits via smooth bell-shaped bonus around pr ~ 0..5
    let tight = (pr / 6.0).exp() * (1.0 - pr_norm);
    score -= tight * 8.0;

    // Last-chance bin: strong smooth reward decaying with fitting options
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress * 0.5);
    } else {
        score += (fitting_bins_count as f64 - 1.0).ln().max(0.0) * 1.2;
    }

    // Lookahead: bonus if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits_next = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).unsigned_abs()) as f64;
        score -= fits_next * 6.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild penalty for proliferating open bins, smoothed by progress
    score += (open_bins_count as f64).sqrt() * (0.4 + 0.6 * progress);

    // New-bin candidate: make it unattractive unless post-residual is huge
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: class 0 (perfect fit) strongly rewarded.
    let class = post_residual % 10;
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if class == 0 {
        score -= 60.0;   // round leftover, reusable by many sizes
    } else if class <= 2 {
        score += 15.0;   // tiny dead space, nearly unusable
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: can next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: leftover divisible by next item is ideal.
            if post_residual % next_item_size == 0 {
                score -= 45.0;
            } else {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize more if the waste is large relative to capacity.
            let waste_frac = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 30.0 * waste_frac;
        }
    } else {
        // Last item: any placement is fine, prefer tight fill.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer filling bins with low residual relative to the mean (tight bins first).
    let tightness = (bin_residual as f64 - mean_residual).max(0.0);
    score += 0.3 * tightness;

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size > bin_capacity / 2;
        if big_item && fitting_bins_count <= 1 {
            score -= 50.0; // large item, poor fits elsewhere: open fresh bin
        } else {
            score += 25.0 + 20.0 * progress; // keep open bins utilized
        }
    }

    // Mild penalty for accumulating many open bins with scattered residuals.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward filling bins tightly relative to capacity.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: penalize bins when many bins are open,
    // encouraging consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (0.5 + progress);
    score += 15.0 * pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere (large dead space elsewhere) or few bins are open.
    if bin_residual == bin_capacity {
        score += 35.0 * pressure + 10.0;
        // Allow new bin if next item is large and this placement leaves a big gap.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Penalize bins whose residual deviates far below mean (fragmented bins).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: item exactly fills the bin
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if the next item exactly matches the post-residual,
    // this placement chains into a perfect fill later -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item can still fit after this one: mild reward, tighter is better
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot fit in the leftover space: dead space penalty
            score += 0.8 * (next_item_size - post_residual) as f64;
        }

        // Combined tightness: both this item and the next one fill the bin
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    }

    // Compare against mean residual of open bins:
    // bins with residual below the mean are "tighter" -> prefer using them.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when many open bins exist and the fit
    // is loose (large post_residual) - avoid bin proliferation.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline slightly worse than a decent fit
        score += 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // new bin leaves room for the next item: soften the penalty
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 15.0; // nothing else available
        }
    }

    // Late-stream urgency: as the stream progresses, waste less space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tight_bonus = 60.0 * (-post_residual as f64 / (item_size as f64 + 1.0)).exp();
    score -= tight_bonus;

    // Penalize creating dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasteful
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.5 * next_item_size as f64;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0; // blocks the next item
        }
    }

    // Penalize opening a new bin when open bins can already fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items as f64 + 1.0);
        score += 30.0 + 20.0 * (1.0 - progress);
        // If mean residual across bins is large, opening new bin is very wasteful.
        score += 0.3 * mean_residual;
        // Many open bins => prefer consolidation.
        score += 2.0 * open_bins_count as f64;
    } else {
        // Reward using bins whose residual deviates from mean (reduce fragmentation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.15 * dev;
    }

    // Mild preference for filling larger-residual bins early in the stream.
    score -= 0.05 * bin_residual as f64 * (1.0 - step_index as f64 / (total_items as f64 + 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let post_norm = post / cap;
    let p2 = post_norm * post_norm;
    let p3 = p2 * post_norm;
    let g = progress * progress;
    // Early stream: prefer tight fits (low post_residual); late stream: tolerate larger residuals less strongly
    let coupling = post * (1.0 - 0.8 * g * p2) + 60.0 * g * p3;
    score += coupling;

    // Penalize residuals too small for the smallest plausible item, smoothly
    let dead = (15.0 - post).max(0.0);
    score += dead * dead * (0.5 + 2.0 * g);

    // Lookahead: reward bins that leave room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = (post - nxt) / cap;
            score -= 25.0 * (1.0 - fit_quality * fit_quality) * (1.0 - 0.5 * g);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 * (1.0 - 0.5 * g);
    }

    // Mild preference for consolidating into fewer bins early on
    score -= (open_bins_count as f64).recip() * 5.0 * (1.0 - g);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod 10 buckets
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Reward residuals that are "harmonic" with typical item granularity (multiples of 10)
    if pr % 10 == 0 {
        score -= 6.0;
    } else {
        score += class * 0.35; // penalize off-class dead space
    }

    // Integer-division thresholds on post_residual: dead zones
    if pr < 10 && pr > 0 {
        score += 40.0; // unusable sliver
    } else if pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: does post_residual fit next item nicely?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nxt = next_item_size as f64;
            // reward if next item divides residual nearly perfectly
            let diff = (pr as f64 - nxt);
            score -= 10.0 * (1.0 - diff / cap);
            if pr % next_item_size == 0 {
                score -= 5.0; // harmonic division
            }
        } else {
            // next item won't fit here: residual likely wasted
            score += (next_item_size as f64 - pr as f64) * 0.25;
        }
    }

    // Last-chance bonus: avoid opening a bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // baseline: same as fresh residual
        let pressure = mean_residual / cap;
        if pressure < 0.25 && open_bins_count > 2 {
            score -= 12.0; // open bins are nearly full, new bin is fine
        } else {
            score += 20.0; // prefer filling existing bins
        }
    }

    // Mild tightness reward: filling bins tighter than the mean
    let prf = pr as f64;
    if prf < mean_residual {
        score -= (mean_residual - prf) * 0.2;
    }

    // Stream progression: be greedier early, more conservative late
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zones: residuals that are too small to be useful later.
    // Items are 1..100, so a residual < 10 (or < smallest plausible next item)
    // is nearly unusable dead space -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // this placement keeps a useful bin alive; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would NOT fit in post residual but would fit an empty bin,
    // mildly penalize leaving awkward gaps.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins (penalize new-bin candidate relatively less when few bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large.
        score += 10.0 + 2.0 * open_bins_count as f64 + 0.05 * mean_residual + 10.0 * progress;
    } else {
        // Existing bin: reward slightly when bin pressure is high (consolidation).
        score -= 0.5 * bin_pressure.min(10.0);
    }

    // Late in the stream, avoid opening new bins even more (endgame consolidation).
    if progress > 0.8 && bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else {
        // Non-linear penalty for unusable dead space: small residuals are
        // increasingly worthless since item sizes can be large.
        let small_item_floor = 1u32;
        let _ = small_item_floor;
        let waste = post_residual as f64;
        score += (waste * waste) / bin_capacity as f64;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this placement chains perfectly -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item still fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a residual that
            // neither closes the bin nor serves the next item.
            score += 150.0;
        }
    }

    // Compare post residual against mean residual across open bins:
    // leaving this bin below-average residual concentrates waste.
    let mean_r = mean_residual;
    if (post_residual as f64) < mean_r * 0.5 {
        score += 100.0;
    } else if (post_residual as f64) > mean_r {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
        if post_residual > bin_capacity / 2 {
            score += 250.0; // bad fit cancels the last-chance bonus
        }
    }

    // Early in the stream, prefer opening fresh bins to build flexibility;
    // later, consolidate to avoid bin proliferation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well
        // or stream is early and bins are few.
        score -= 120.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        if open_bins_count > 3 && progress > 0.3 {
            score += 200.0;
        }
        // Don't open a new bin when next item is small enough to reuse.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill of the bin after placement
    let post_frac = post_residual as f64 / bin_capacity as f64;
    let item_frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits strongly (non-linearly): small post_residual is good
    score -= (1.0 - post_frac).powf(2.5) * 60.0;

    // Penalize dead space that is too small to be useful (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact / near-exact closure of a bin
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits into the resulting residual, reward;
    // if next item is large and would not fit, penalize wasting this bin's space.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += 0.25 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Many open bins with high mean residual -> encourage consolidating into
    // existing bins rather than spreading; scale with open_bins_count.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure * post_frac * 10.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let openness = (1.0 - progress).powf(1.5);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted early, penalized late.
        score = bin_capacity as f64 * (0.85 + 0.6 * progress) - 30.0 * openness;
        // If no open bin fits well, opening a new bin is fine
        if item_frac > 0.7 {
            score -= 20.0 * progress;
        }
    } else {
        // Existing bin: late-stage tight packing bonus
        score -= 20.0 * progress * (1.0 - post_frac);
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap;

    // Deviation from mean residual: prefer bins that are already fuller than average
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer minimal post residual, mildly normalized
    let mut score = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight packing (small post_residual) matters more.
    let tightness = 1.0 - (pr / cap);
    let progress_coupling = progress * tightness * tightness * tightness;
    score -= 0.9 * progress_coupling;

    // Quadratic dead-space penalty: small residuals that are hard to reuse.
    let dead = if pr > 0.0 { (pr / cap).powi(2) } else { 0.0 };
    score += 0.6 * dead;

    // Reward last-chance bins (avoid opening a new bin needlessly).
    if fitting_bins_count == 1 {
        score -= 0.8;
    }

    // Penalize spreading across many open bins slightly, scaled by progress.
    score += 0.05 * (open_bins_count as f64) * progress / 100.0;

    // Reward bins whose residual is below the mean (compactness pressure).
    score += 0.3 * ((pr - mean_residual) / cap);

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 0.7 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use at all.
        score += 0.25 * (next_item_size as f64 / cap);
    }

    // New-bin candidate handling: make fresh bin less attractive when any
    // open bin fits, more attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 1.5 + 0.5 * progress;
        } else {
            score -= 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residue mod capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (post_residual % (bin_capacity / 4)) as f64;
    let eighth = (post_residual % (bin_capacity / 8)) as f64;

    // Reward residuals that fall on "harmonic" grid points (multiples of small divisors),
    // since future items drawn from arbitrary integer distributions more often fit them.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 5 == 0 { score -= 4.0; }
    score -= (c / 8.0 - eighth) * 0.05; // closeness to eighth-grid

    // Penalize dead space: residuals too small for the smallest plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0; // likely dead space
    }

    // Lookahead coupling: harmonic relation between post_residual and next_item_size
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 500.0; // next item fits exactly
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 20.0;
            if gap < 10 { score += 25.0; } // creates a sliver for the item after next
            // integer-division threshold classes
            let cls_next = next_item_size / 20;
            let cls_post = post_residual / 20;
            if cls_next == cls_post { score -= 10.0; } // same harmonic band
        } else {
            // next item won't fit here; mild penalty scaled by overflow size
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // modulo resonance between next item and post residual
        if (next_item_size % 10) == (post_residual % 10) && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer existing bins unless current bin is very tight
    if bin_residual == bin_capacity {
        // new empty bin: neutral baseline with slight exploration bonus early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = c * 0.55 - progress * 5.0;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0; // lookahead suggests fresh capacity is useful
        }
    }

    // Mild regularization toward bins below mean residual (consolidate fullness)
    score += (mean_residual - pr).max(0.0) * 0.1;

    // Late-stream tightening: prefer tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (<10, minimum item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps that only fit the smallest items are nearly dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
