    // Reward a bin whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys the only bin that could host the next item.
            score += 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: must overcome its inherent freshness advantage.
        score += 40.0 + bin_pressure;
        // Opening a new bin is more attractive early in the stream.
        score -= 30.0 * (1.0 - progress);
        // Attractive if mean residual of open bins is small (poor spread overall).
        score -= (mean_residual / 10.0).min(30.0);
    } else {
        // Using an existing bin slightly relieves pressure when many bins are open.
        score -= (bin_pressure * 0.3).min(20.0);
        // Prefer bins tighter than the mean residual (better-packed bins).
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

