    // Aggressive 2-step lookahead: if next item fits into the post residual, big reward
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64) >= next {
            // next item fits after this placement: reward proportional to how snugly
            let slack = (post_residual as f64) - next;
            if slack == 0.0 {
                score -= 800.0; // perfect 2-item chain
            } else if slack <= 10.0 {
                score -= 400.0;
            } else {
                score -= 200.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
