            score += 0.5 * (post_residual as f64 - next).max(0.0);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins can fit the item
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // only attractive if the item is large or no good fit exists
        let waste = (bin_capacity as f64 - item_size as f64);
        score += 50.0 + 0.3 * waste;
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) > bin_capacity as f64 {
            score -= 100.0; // large pair: opening fresh bin is fine
        }
    }

    // Late in the stream: consolidation pressure, avoid leaving many small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 100.0;

