}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead chaining: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(bin_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Fragmentation pressure: penalize leaving residuals in the "awkward" band
    // (too small for typical items, too large to ignore).
    let awkward = (post_residual as f64 / 20.0).sin().abs();
    if post_residual > 0 && post_residual < 10 {
        score += 6.0 + awkward;
    }

    // New-bin candidate: only attractive when existing bins are fragmented
    // or we are early in the stream with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 + 15.0 * progress;
        score -= (open_bins_count as f64).min(10.0);
        score -= fragmentation.min(30.0) * 0.3;
    } else {
        // Mild reward for packing into already-open bins vs opening new ones.
        score -= 3.0;
    }

    // Global balance: prefer bins whose residual deviates favorably from the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
