    // Tight fit reward: strongly favor bins whose post residual is small,
    // with a smooth quadratic coupling in the normalized fill ratio.
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill;

    // Perfect fit bonus (post_residual == 0): smooth exponential reward.
    score -= 40.0 * (-post / 6.0).exp();

