    let dead = ((cap * 0.2 - post).abs() / (cap * 0.2)).min(1.0);
    score += 15.0 * dead * dead * (1.0 - fill);

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 12.0 * (1.0 - post / cap) * (1.0 - progress);
        } else {
