            // smoothly scaled by how close the next item is to fitting.
            let gap = (next - post) / cap;
            score += 10.0 * gap * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, prefer packing into existing bins to close them out;
    // early on, allow opening bins that leave a versatile residual.
    let versatility = (post / cap - 0.5).abs();
    score += 8.0 * versatility * progress;
    score -= 6.0 * (1.0 - progress) * (1.0 - versatility);

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.5 * open_bins_count as f64 * fill;

    // Discourage opening a new bin when the mean residual across open bins
    // is still large enough to accommodate the item.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * mean_residual;
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
