        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: base penalty, discounted for large items (leaving small residual)
    if bin_residual == bin_capacity {
        score += 35.0 - 0.35 * item_size as f64;
        // If existing bins are fragmented, opening fresh is attractive
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 22.0;
        }
        // If next item is bigger than current, a roomy fresh bin helps
        if next_item_size > item_size && next_item_size > 0 {
            score -= 12.0;
        }
        // Many open bins: avoid proliferation
        score += 0.6 * open_bins_count as f64;
    }

    // Late-stream consolidation pressure: prefer reusing bins as stream nears end
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_residual as f64 * 0.35;

    // Mild preference for fuller bins overall
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64).recip() * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    // Gaps below the minimum item size (1..10) are pure waste; gaps just above
    // small item sizes are risky. Use a non-linear dead-space penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 25.0 - (post_residual as f64) * 0.8;
    }

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: discourage spreading across many bins when residual
    // is already fragmented; encourage using existing bins when open_bins_count
    // is high relative to stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).powi(2) * 0.05 * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post_residual, reward this placement;
    // if next item cannot fit, penalize leaving a gap that blocks it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps bin states balanced), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate handling: an empty bin should only win when the fit
    // here would be poor. Give empty bins a moderate base so tight fits in
    // existing bins beat them.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward (post_residual == 0 leaves no dead space)
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: exact match between post_residual and next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // next item fills this bin exactly -> chain of perfect fits
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how tight the fit is
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalty scaled by leftover gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Penalize creating small unusable dead space (relative to item size scale)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is nearly unusable
    }

    // Compare against mean residual: favor bins that are tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty unless current bins are poor fits
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if post_residual >= next_item_size && next_item_size > 0 {
            score += 10.0; // don't open new bin if an open bin chains with next item
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for bins among many open bins that are already tight
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest conceivable item (1..100).
    if post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    } else if post_residual > 0 {
        // Wasted fraction penalty, scaled by how much of the bin remains unusable.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * waste * waste;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving a large awkward residual.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins with below-average residual (consolidate emptier space usage),
    // i.e. placing into a bin whose residual is larger than average is cheaper.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    // Mildly discourage proliferating open bins early in the stream;
    // later in the stream, allow more freedom to open new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax late; also penalize more when many bins already open.
        score += 18.0 * (1.0 - 0.5 * progress) + 0.3 * open_bins_count as f64;
        // If the fit into an existing bin would be very loose (large post_residual),
        // opening a fresh bin becomes attractive: reduce the new-bin penalty.
        if post_residual as f64 > 0.5 * bin_capacity as f64 {
            score -= 12.0;
        }
        // If next item is large and current item is large, a fresh bin pairs them well.
        if next_item_size > 0 && post_residual < next_item_size && item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Existing bin: slight bonus late in stream to close out bins.
        score -= 3.0 * progress;
    }

    // Small global load-balancing term: many open bins with high mean residual
    // suggests fragmentation; prefer placements that reduce it (tight fits already do).
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) coupling to stream progress.
    // Early on, larger residuals are acceptable (future items can fill them);
    // late in the stream, dead space is costly, so the quadratic penalty ramps up.
    let base = pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth interaction: item tightness (how well item fills the bin)
    let tightness = 1.0 - norm_pr; // fraction of residual consumed
    let fit_bonus = -40.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize leaving residual that neither the next item nor typical items can use.
    // Smooth dead-space term: residual far from next_item_size and small is bad.
    let next = next_item_size as f64;
    let dead = if next > 0.0 {
        let gap = (pr - next).abs();
        -12.0 * (1.0 - gap / cap).max(0.0) * (1.0 - progress)
    } else {
        0.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how much slack would remain).
    let last_chance = if fitting_bins_count == 1 {
        -30.0 * (1.0 - 0.5 * norm_pr)
    } else {
        0.0
    };

    // Mild penalty when many bins are open and mean residual is high:
    // encourage consolidating into bins that reduce dispersion.
    let consolidation = 3.0 * (open_bins_count as f64).ln() * (mean_residual - pr).abs() / cap;

    // New-bin candidate: empty bin gets a moderate default score so it wins only
    // when open bins would create severe dead space (large post_residual late in stream).
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        cap * (0.35 + 0.4 * progress) + 5.0 * (1.0 - tightness)
    } else {
        0.0
    };

    base + fit_bonus + dead + last_chance + consolidation + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" residue classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    if pr > 0 {
        // Penalize dead space: leftover too small for the smallest plausible item.
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 25.0;
        }
        // Reward leftovers divisible by common size classes (harmonic fit).
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 40, 50, 80] {
            if pr % m == 0 {
                harmony += 12.0;
            }
        }
        score -= harmony;
        // Integer-division threshold: leftover in a "high band" is flexible.
        let band = pr / 25; // 0..4
        score -= band as f64 * 5.0;
    } else {
        // Perfect fill: strongly reward.
        score -= 100.0;
    }

    // Lookahead coupling: does the leftover accommodate next_item_size exactly?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score += 15.0; // leaves near-dead space after next item
            }
            score -= 8.0;
        } else {
            score += 10.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // but allow it when this item would waste an open bin badly.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score += 20.0;
        if waste > 60 {
            score -= 35.0; // big item: fresh bin is efficient
        }
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer tight bins relative to fleet mean residual.
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.5 * slack;
        if slack == 0.0 {
            score -= 30.0; // perfect chain fit
        }
    }
    // Penalize if next item would leave this bin nearly wasted.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating (favor existing bins over new).
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).min(20.0) * 0.8;
    } else {
        // New-bin candidate: penalize more when few bins are open or residual spread is high.
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt();
        if mean_residual > 0.0 && mean_residual < 10.0 {
            score += 15.0; // open bins are nearly full anyway, a new bin is fine
        } else {
            score += 5.0;
        }
    }

    // Prefer tight fits relative to mean residual.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Early stream: be slightly conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fills (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits here later; reward proportionally to tightness
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 300.0 * tightness;
        } else {
            // next item cannot use the leftover; penalize dead space relative to gap
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare residual to mean residual across open bins: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a brand-new bin when open bins exist and fit is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // New bin attractive only if item is large and no tight fit exists.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 150.0 - 100.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild late-stream pressure to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fill
    } else if post_residual < 30 {
        score -= 8.0 * (1.0 - progress);
    } else {
        score += 0.15 * post_residual as f64;
    }

    // Lookahead: if the next item fits into post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 45.0 * chain;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; penalize wasting a big residual.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Global pressure: many open bins -> consolidate into existing bins.
    score -= 3.0 * open_bins_count as f64 * (mean_residual / bin_capacity.max(1) as f64).min(1.0);

    // New-bin candidate handling: fresh bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin only when item is huge or no good existing fit exists.
        let huge = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = fitting_bins_count <= 1 && fit_ratio < 0.5;
        if huge || poor_fit {
            score -= 30.0;
        } else {
            score += 90.0; // keep items in open bins when they fit reasonably
        }
    } else {
        // Existing bins with residual close to item size are ideal.
        let slack = (bin_residual - item_size) as f64;
        score += 0.05 * slack * (1.0 - progress);
    }

    // Late in the stream, favor exactness over spreading.
    if progress > 0.8 {
        score += 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Mild bonus for balancing mean residual (avoid extreme outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = post;

    // Smooth polynomial coupling: mid-range residual penalized more as stream progresses
    let quad = x * x;
    let cubic = quad * x;
    score += (quad * 30.0 + cubic * 40.0) * (0.5 + progress);

    // Reward tight fits (small x) more strongly later in the stream
    score -= (1.0 - quad) * 10.0 * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Dead-space penalty: post residual too small for typical future items
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.0;
    }

    // Lookahead: if next item fits exactly into post residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 8.0;

    // New-bin candidate: make it attractive only when open-bin fits are poor
    if bin_residual == bin_capacity {
        // New empty bin: neutral residual, penalize slightly so it only wins when needed
        score = cap * 0.6 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual) already favored via post_residual.

    // Harmonic class logic: classify post_residual into residue classes mod 10 and mod 25.
    // Residuals that are "harmonically useful" (multiples of 10, or small enough to
    // plausibly host a future item from a 1..100 distribution) get rewarded.
    let pr = post_residual;
    let mod10 = pr % 10;
    let mod25 = pr % 25;

    // Reward residuals that are multiples of 10 (common item-size alignments).
    if mod10 == 0 {
        score -= 4.0;
    } else {
        // Penalize awkward off-alignment residuals proportional to distance from a
        // multiple of 10.
        let dist = mod10.min(10 - mod10) as f64;
        score += dist * 0.6;
    }

    // Reward residuals that are multiples of 25 (quarter-capacity harmonics).
    if mod25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Dead-space penalty: residuals too small for any item (size >= 1 always fits,
    // but very small residuals are still low-value; scale by fraction of capacity).
    let frac = pr as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.05 {
        score += 6.0; // near-dead space
    }

    // Integer-division thresholds: residual "tiers".
    let tier = pr / 25; // 0..4
    match tier {
        0 => score += 2.0,      // 0..24: cramped
        1 => score -= 1.0,      // 25..49: decent
        2 => score -= 2.0,      // 50..74: good
        3 => score -= 1.5,      // 75..99: large but maybe wasteful
        _ => score -= 0.5,      // near-full residual (new bin)
        _ => {}
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // Reward proportional to how well next item fits; penalize large slack.
            score -= 5.0 - slack.min(5.0) * 0.5;
        } else {
            // Next item won't fit here: mild penalty if this bin is the only option.
            if fitting_bins_count == 1 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && pr < bin_capacity {
        score -= 2.5;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are fragmented
        // (mean residual low relative to this fresh capacity) or few bins fit item.
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 8.0 * (1.0 - fragmentation);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    if open_bins_count > 0 {
        let mean_frac = mean_residual / bin_capacity as f64;
        if mean_frac > 0.5 && pr < (mean_residual as u32) {
            score += 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 {
        let dead_threshold = 10.0f64; // smallest item size
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 12.0;
        } else {
            // Superlinear penalty on tight-but-wasteful residuals
            score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);
        }
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: prefer bins that reduce fragmentation when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the actual future demand
        score += (post_residual as f64 - (next_item_size as f64).min(post_residual as f64)) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Mean residual alignment: prefer bins below mean residual (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can accommodate the next item: reward proportionally
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.25;
    } else if next_item_size > 0 {
        // Dead space: next item cannot fit here, penalize unusable leftover
        let dead = next_item_size as f64 - post_residual as f64;
        score += dead * 0.6;
    }

    // Relative to mean residual: bins tighter than average are better to fill
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Late in the stream: prefer closing out bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New empty bin candidate: penalize so it is chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is large and next item is large too, fresh bin is reasonable
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good, but heavily
    // penalize leaving awkward small dead space (1..=9) that nothing fits into.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 25.0; // dead space trap
    } else {
        // prefer larger usable leftovers, mildly
        score -= 0.15 * pr;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the remainder
            score -= 20.0 * (n / pr);
        } else {
            // next item won't fit here; mild penalty proportional to overflow
            score += 0.10 * (n - pr);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item
    // is large and remaining stream is short / few fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // opening a new bin is fine early or when item is big; penalize otherwise
        score += 30.0
            - 0.25 * item_size as f64
            - 20.0 * progress
            - 40.0 * scarcity;
    }

    // Global state coupling: when mean residual across open bins is high,
    // encourage consolidating into existing slack.
    score += 0.05 * mean_residual;

    // Late in the stream, favor tighter packing to close out bins.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (1.0 - pr / bin_capacity as f64);

    // Slight preference for bins with more residual among many open bins
    // to avoid fragmentation when bin count is large.
    score += 0.02 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let t = progress;
    let poly = norm_pr * (1.0 + 0.8 * t * t + 0.4 * t * norm_pr);

    let mut score = poly;

    // Penalize large dead space more than linearly (quadratic waste term).
    score += 0.5 * norm_pr * norm_pr * cap;

    // Reward tight fits: small post_residual gets a bonus, amplified mid-stream.
    let tight = 1.0 - norm_pr;
    score -= 3.0 * tight * tight * (0.5 + t);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * t;
    }

    // Lookahead: reward bins whose post_residual can still fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 2.0 * (pr - nxt) / cap;
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    } else {
        // Last item: fill any residual as much as possible.
        score -= 5.0 * tight;
    }

    // Mild penalty for bins already much emptier than average (preserve spread).
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev.abs();

    // New-bin candidate: prefer it only when residuals are badly fragmented late.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0);
        score = cap + 20.0 * t * (1.0 - frag) - 5.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 60.0; // near-perfect, dead space tiny
    } else if pr % 10 == 0 {
        score -= 25.0; // harmonic class: multiple of 10, re-usable by common sizes
    } else if pr % 5 == 0 {
        score -= 10.0;
    } else {
        score += 15.0; // awkward residue class
    }

    // Integer-division thresholds: how many "typical" items still fit.
    let slots = pr / 10;
    score -= slots as f64 * 6.0;

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward proportional to how well it couples
            let next_post = pr - next_item_size;
            if next_post == 0 {
                score -= 120.0;
            } else if next_post % 10 == 0 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: penalize leaving a large unusable gap
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Fresh-bin candidate: only attractive when the item is large relative
    // to capacity or existing bins are crowded/tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        let tight = mean_residual < item_size as f64 * 1.2;
        if large_item > 0.6 || tight || open_bins_count == 0 {
            score -= 30.0 + 40.0 * large_item + 20.0 * progress;
        } else {
            score += 50.0; // prefer existing bins early on
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small for the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual) * 3.0;
    }
    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: slight penalty so it only wins when fits are truly bad.
    if bin_residual == bin_capacity {
        score += 12.0 + (post_residual as f64 / bin_capacity as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: does the next item fit exactly in the post residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chained perfect fit
        } else if post_residual >= next_item_size {
            // next item fits; reward tighter leftover after that hypothetical placement
            let second_left = post_residual - next_item_size;
            score -= 60.0 + (second_left as f64).min(30.0);
        } else {
            // dead space relative to next item: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64) * 0.8;

    // Last-chance bin (only fitting bin): avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it attractive only when current bins would waste a lot.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55 - (fitting_bins_count as f64) * 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin guarantees fit for next item
        }
        if fitting_bins_count > 0 {
            score += 40.0; // discourage opening when other bins fit
        }
    }

    // Late in the stream, prefer consolidating (fewer open bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement
    // (chaining two items into one bin region).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }
    // If next item is large and would not fit anywhere after this placement,
    // slight penalty for wasting space the next item could have used.
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 6.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current fit is poor (large post_residual) or few bins fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 25.0;
        // More attractive when many open bins already exist and mean residual is high
        // (fragmented state, better to start clean).
        score -= 0.15 * open_bins_count as f64;
        score += 0.10 * (mean_residual - post_residual as f64);
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If item fits perfectly, opening a new bin is fine.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Discourage leaving residuals that are too small for the smallest possible item
    // (dead space), but less harsh late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - progress);
    }

    // Mild preference for bins already below the mean residual (balancing load).
    score += 0.05 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };

    // Base: prefer tight fits (low post_residual), with a convex penalty on dead space.
    let mut score = post * (1.0 + 0.9 * post / cap);

    // Quadratic coupling of post_residual with stream progress:
    // early on, tolerate larger post_residual; late, penalize it heavily.
    let coupling = 1.0 + 1.6 * progress * progress;
    score += coupling * post * post / cap;

    // Cubic interaction: waste is worse when bins are plentiful and stream is mature.
    let bins_norm = (open_bins_count as f64).ln().max(0.0);
    score += 0.35 * bins_norm * progress * post;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 12.0 * (5.0 - post as f64);
    }

    // Last-chance bonus: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: penalize if next item can't use the resulting residual.
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += 4.0 + 0.25 * ((next_item_size as f64) - post);
    } else if next_item_size > 0 {
        // reward leaving a residual that exactly or nearly fits the next item
        let gap = ((post - next_item_size as f64) as u32) as f64;
        score -= 6.0 * (1.0 - gap / cap).max(0.0);
    }

    // New-bin candidate: bias toward it when its residual is high relative to mean.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * progress * mean_residual;
    } else {
        // Prefer bins whose residual is below mean (smaller bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild item-size interaction: large items prefer the tightest possible fit.
    score -= 0.05 * item * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 captures
    // "dead space" classes that small future items (sizes 1..100) may or may not fill.
    let pr = post_residual as u32;
    let dead_class = pr % 10;                       // 0 => perfectly harmonic leftover
    let harmonic = (pr % 20 == 0) || (pr % 25 == 0) || (pr % 50 == 0);

    // Reward leftovers that lie on fine-grained harmonic divisors of capacity:
    // they are likely reusable by later items.
    if harmonic { score -= 6.0; }
    if dead_class == 0 && pr > 0 { score -= 3.0; }
    // Penalize awkward dead classes (1..9 units of unusable sliver).
    if pr > 0 && dead_class > 0 { score += (dead_class as f64) * 0.4; }

    // Fractional fill: strongly reward high occupancy of this bin.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * fill * fill;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin gives a tight fit, or the item is huge relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = item_size as f64 / cap;
        // Base penalty for wasting a fresh bin.
        score += 28.0;
        // Reward opening a new bin for very large items (they pair badly with leftovers).
        score -= 26.0 * tightness * tightness * tightness;
        // If many bins already fit the item, opening new is wasteful.
        if fitting_bins_count > 1 { score += 10.0 * (fitting_bins_count.min(5) as f64); }
        // Early in the stream, opening bins is cheaper (future items can use them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead (k=2): if the next item fits exactly into the post residual,
    // this placement is excellent (perfect pairing).
    if next_item_size > 0 {
        if next_item_size == pr { score -= 20.0; }
        else if next_item_size <= pr {
            let nr = pr - next_item_size;
            // Harmonic remainder after the follow-up placement.
            if nr % 10 == 0 { score -= 8.0; } else { score += 1.5; }
        } else {
            // Next item won't fit here: mildly penalize leaving large gaps.
            if pr > next_item_size / 2 { score += 2.0; }
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below the mean
    // (compact the fullest bins first), penalize outliers with excess space.
    if (bin_residual as f64) > mean_residual {
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    } else {
        score -= 0.03 * (mean_residual - bin_residual as f64);
    }

    // Modulo threshold on post_residual: leftover in [10,20) is a "sweet spot"
    // for typical small items; leftover in [1,10) is nearly dead.
    if pr >= 10 && pr < 20 { score -= 4.0; }
    if pr > 0 && pr < 10 { score += 5.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1) are pure waste, but residuals that are
    // small-yet-usable (<= 10) are "dead zones" for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver -> strong penalty
    }

    // Reward tight fits (post_residual near zero but not a sliver).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Encourage filling large fractions of the bin.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill_ratio;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the one with best fit quality.
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is close to
    // the item need (balanced depletion).
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_gap;

    // Lookahead: if the next item fits exactly in post_residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chaining
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit here -> residual likely wasted
        }
    }

    // New-bin candidate: only attractive when all open bins are crowded or
    // this item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.1;
        if crowded || open_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 55.0; // discourage opening bins when fits exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leftover space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward: this bin can also host the next item (2-step lookahead match).
            let waste_after_next = post_residual - next_item_size;
            score -= 12.0 + 0.25 * (waste_after_next as f64).min(40.0);
        } else {
            // Penalize dead space relative to next item size.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits (small post residual) with extra bonus.
    if post_residual < 10 {
        score -= 8.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residuals below the mean (consolidate large holes).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild penalty for the brand-new empty bin candidate unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if the current item is large and would leave a big hole elsewhere,
        // opening a fresh bin becomes attractive.
        if item_size > 60 && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer closing out bins (avoid many tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual small relative to capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 20.0;

    // Perfect fit gets extra bonus
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 5 {
        score -= 8.0;
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra reward if next item fills post residual well
            let next_fill = next_item_size as f64 / post_residual as f64;
            if next_fill > 0.8 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize slightly more if post residual is wasted
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins among many open bins (best-fit style)
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fullness * 5.0;

    // Global state: if many open bins with large mean residual, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when mean residual across open bins is large
        score += mean_residual * 0.3;
        // Early in stream, opening bins is cheaper; late in stream, prefer consolidation
        score += (1.0 - progress) * 5.0;
        score += open_bins_count as f64 * 0.5;
    } else {
        // Using an existing bin reduces fragmentation when many bins are open
        score -= open_bins_count as f64 * 0.2 * (1.0 - progress);
    }

    // Mild time-horizon scaling: as stream progresses, tighten packing discipline
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = pr_norm.powf(1.5) * 100.0;

    // Smooth polynomial coupling: post-residual squared interacts with stream progress.
    // Early in the stream, larger residuals are more tolerable (more items coming to fill);
    // late in the stream, dead space is penalized more heavily.
    let dead = pr_norm * pr_norm;
    score += dead * (1.0 + 3.0 * progress) * 50.0;

    // Reward bins whose residual is close to the mean residual (harmonization),
    // penalize outliers, with smooth quadratic term.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 30.0 * (0.5 + progress);

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // strongly reward this bin (chaining placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let waste_after_next = pr - nxt;
            let chain = 1.0 - (waste_after_next / cap);
            score -= chain * chain * 40.0;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot
            let over = (nxt - pr) / cap;
            score += over * over * 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (large post-residual).
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - pr_norm);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation risk)
    score += pr_norm * (open_bins_count as f64).ln().max(0.0) * 4.0;

    // New-bin candidate: neutral-ish baseline so it wins only when fits are bad
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * progress + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "harmonically useful"
    // (divisible by common small sizes) deserve reward.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 5 == 0 { harmonic_bonus += 2.0; }
        if pr % 20 == 0 { harmonic_bonus += 3.0; }
        if pr % 25 == 0 { harmonic_bonus += 2.5; }
        if pr % 50 == 0 { harmonic_bonus += 4.0; }
    }
    score -= harmonic_bonus;

    // Dead-space penalty: leftover too small for the smallest plausible item (1..100 range)
    // but nonzero -> unusable dead space.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next item fits: leftover after that pair
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 { score -= 8.0; }
        if pr2 == 0 { score -= 15.0; }
        if pr2 > 0 && pr2 < 10 { score += 6.0; }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize placing into bins when many bins fit (prefer tightest naturally via post_residual).
    if fitting_bins_count > 4 {
        score += 2.0 * (fitting_bins_count as f64 - 4.0);
    }

    // New-bin candidate handling: empty bin gets baseline; discourage early in stream
    // when open bins exist and fit, encourage late when residuals are fragmented.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open new bin
        }
        if next_item_size > 0 && next_item_size > mean_residual.max(1.0) {
            score -= 10.0; // open bins too full for next item
        }
    }

    // Mild tie-break: prefer bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the min item size (1..100 range, use 10 as dead-zone)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead); // unusable sliver is worthless
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead: reward if the next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size >= post_residual && post_residual > 0 {
            score += 10.0; // dead space relative to next item
        }
    }

    // Mean residual coupling: prefer bins far from mean residual (diversify gap sizes)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: make it unattractive unless this bin is a terrible fit
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: strongly reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // perfect chain: next item exactly consumes leftover
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 - gap * 0.4;
            if post_residual == next_item_size {
                score -= 25.0; // perfect pair closure
            }
        } else {
            // next item won't fit here; penalize creating stranded residual
            let stranded = post_residual as f64;
            let nxt = next_item_size as f64;
            // worse if stranded space is small (unusable) but nonzero
            if stranded < 10.0 {
                score += 15.0;
            } else if nxt > bin_capacity as f64 {
                // next item larger than capacity edge case: neutral
            } else {
                score += stranded * 0.15;
            }
            // compare against mean residual: leaving below-average residual is bad
            if stranded < mean_residual {
                score += (mean_residual - stranded) * 0.2;
            }
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin, more so when many bins are open
        score += 60.0 + (open_bins_count as f64) * 2.0;
        // but if the only alternative leaves large dead space, allow new bin
        if fitting_bins_count == 0 {
            score -= 80.0;
        } else if fitting_bins_count == 1 && post_residual as f64 > 40.0 {
            // existing fit is poor (large post residual), new bin competitive
            score -= 30.0;
        }
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 10.0;
    }

    // Slight penalty for very small unusable leftovers overall
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: tiny residuals that few future items can use.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item would be blocked by a small post-residual, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let chain_fit = nxt / post_residual as f64;
            score -= 12.0 * chain_fit;
        } else {
            score += 0.15 * nxt;
        }
        // Perfect chain: next item exactly fills the bin.
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly and the stream is early/mid (long horizon left).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Penalty grows with progress (late in stream, prefer consolidation).
        score += 15.0 + 55.0 * progress;
        // If this bin is a last resort, opening new bin is fine.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Early stream with many items left: cheaper to open bins.
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins with residual below the mean (consolidate emptier space).
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev;

    // Mild penalty for proliferating open bins when many can fit the item.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: minimize leftover space, with a non-linear (quadratic) penalty on
    // large post-residuals so that near-perfect fits are strongly favored.
    let mut score = pr + 12.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: as the stream progresses, tight fits matter more
    // (fewer chances to fill residual space later).
    let urgency = 1.0 + 3.0 * progress * progress;
    score *= urgency;

    // Reward bins whose residual after placement can host the lookahead item
    // (smooth logistic-style coupling rather than a hard threshold).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = pr - nxt;
        let s = 1.0 / (1.0 + (-compat / 8.0).exp());
        score -= 6.0 * s;
    }

    // Penalize wasting a scarce fitting opportunity: if this is the only bin
    // that fits, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild reward for placing into bins that are already relatively empty
    // (consolidating residual capacity), scaled by open-bin pressure.
    let openness = open_bins_count as f64 / (1.0 + open_bins_count as f64);
    score -= 4.0 * openness * (bin_residual as f64 / cap);

    // Penalize deviating from the mean residual: keeps residual distribution
    // homogeneous, avoiding many half-empty bins plus one nearly-full bin.
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate (empty bin): add a smooth offset that grows with the
    // item's smallness (small items in a fresh bin waste more capacity) and
    // with stream progress, so late-stream we prefer existing bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - norm_item) + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets (1/4, 1/3, 1/2 of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let third = cap / 3.0;
    let half = cap / 2.0;

    // Dead-space penalties: leftovers that are hard to fill later.
    if pr > 0.0 && pr < quarter {
        // Tiny sliver: nearly dead space -> heavy penalty, scaled by sliver smallness
        score += (quarter - pr) / quarter * 30.0;
    }
    if pr >= quarter && pr <= third {
        // Sweet spot: a 25-33% leftover is very reusable -> reward
        score -= 12.0 * (1.0 - (pr - quarter) / (third - quarter + 1e-9)).abs().min(1.0) * 0.5;
        score -= 10.0;
    }

    // Integer-division harmonic classes on post_residual (buckets of 10).
    let bucket = post_residual / 10;
    match bucket {
        0 => score += 8.0,        // 0..9 : near-perfect fill
        1 => score -= 4.0,        // 10..19: classic reusable gap
        2 => score -= 2.0,        // 20..29: decent
        3 => score += 1.0,        // 30..39: mediocre
        4 => score += 3.0,        // 40..49: wasteful
        _ => score += 6.0,        // >=50: very wasteful placement
    }

    // Perfect / near-perfect fit bonus (post_residual exactly 0 or a small modulus class)
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0; // round-number leftover pairs well with round item sizes
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly-ish: strong reward, tighter if near-exact
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap).max(0.0);
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Next item won't fit: penalize proportionally to overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot / cap * 10.0;
        }
    } else {
        // Last item: only care about closing bins tightly
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, grows with stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 20.0 * progress;
        // If many bins are open and mean residual is large, discourage new bins
        score += open_bins_count as f64 * 2.0;
        score += (mean_residual / cap).max(0.0) * 15.0;
        // But if the new bin would fit the next item exactly after this item
        // (harmonic pairing), soften the penalty.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 12.0;
        }
    }

    // Mild pressure against leaving many bins half-open when residuals are scattered
    if (pr - mean_residual).abs() < 5.0 && open_bins_count > 3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1, but practically small gaps < ~20 are hard to fill)
    if post_residual > 0 {
        if post_residual < 20 {
            score += 60.0 * (20.0 - post_residual as f64) / 20.0; // unusable sliver penalty
        } else if post_residual < 40 {
            score += 20.0 * (40.0 - post_residual as f64) / 40.0;
        }
    } else {
        score -= 80.0; // perfect fill is excellent
    }

    // Reward tight fits relative to item size
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // brand-new bin candidate: base cost + pressure term
        score += 25.0 + 8.0 * open_bins_count as f64;
        // If only one fitting bin exists, strongly prefer using it over new bin
        if fitting_bins_count <= 1 {
            score += 40.0;
        }
        // Lookahead: if next item could combine with current in a fresh bin, slightly favor it
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Last-chance bin bonus: avoid wasting the only fitting bin
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // If post_residual exactly matches next item, big reward
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        }
        // Mild pressure to close bins: prefer bins with small residual among many open bins
        score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Deviation from mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Late-stream conservatism: fill existing bins harder near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild normalization.
    let cap = bin_capacity as f64;
    score = (post_residual as f64) * (1.0 + 0.3 * (post_residual as f64 / cap));

    // 2-step lookahead: strongly reward when post_residual exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly after this placement: big reward.
            score -= 40.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for next item: penalize dead space,
            // more so if the dead space is large relative to capacity.
            score += 10.0 * (diff / cap);
        }
    }

    // Compare post_residual against mean residual: keep residuals balanced,
    // but reward being below the mean (efficient packing).
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or current bins are nearly full (mean residual small).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // high = lots of slack available
        score += 20.0 + 25.0 * pressure;
        if next_item_size > 0 && (next_item_size as f64) > (post_residual as f64 + item_size as f64) {
            score -= 15.0; // fresh bin helps the lookahead item
        }
    }

    // Late in the stream, tighten packing further (less room for slack).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: bonus if the next item can fit in the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 4.0;
        }
    }

    // Global state: with many open bins, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln() * 3.0 * (0.5 + progress);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals balanced), unless it's a very tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tightness);

    // New-bin candidate: penalize opening a new bin, more so as bins accumulate.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: polynomial coupling of post_residual with stream progress.
    let mut score = norm_pr * (1.0 + 0.8 * progress) + 0.35 * norm_pr * norm_pr;

    // Tight fits rewarded, stronger late in the stream.
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strong reward, decaying with progress.
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - progress) + 2.0;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - nxt / cap);
        } else {
            score += 1.5 * (nxt - pr) / cap;
        }
    }

    // Prefer bins deviating favorably from mean residual (pack fuller-than-average bins).
    score += 0.5 * ((pr as f64) - mean_residual) / cap;

    // Mild penalty for proliferating bins.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: penalize unless residuals everywhere are tiny.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * (1.0 - progress);
        if mean_residual < 8.0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Harmonic classes: bins whose residual falls into "dead" classes
    // (residuals that few item sizes can ever fill) get penalized.
    let r = post_residual;
    let dead = if r == 0 { 0.0 }
        else if r < 10 { 60.0 }              // unusable sliver
        else if r % 10 == 0 { -6.0 }         // clean class, easy to fill
        else if r % 5 == 0 { -2.0 }
        else { 8.0 };                        // awkward remainder class
    score += dead;

    // Reward leaving room for the lookahead item (exact or harmonic match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 30.0; // perfect two-item packing
        } else if slack % 10 == 0 {
            score -= 12.0;
        } else if slack < 10 {
            score += 10.0; // leaves dead sliver after next item
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Bin can't host the next item; mild penalty unless it's the only fitting bin.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // badly fragmented (large mean residual dispersion) or this is a big item
    // that would leave a nasty class behind.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let big_item = item_size > bin_capacity / 2;
        let mut new_bin_score = 55.0;
        if big_item { new_bin_score -= 18.0; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_score -= 10.0; // fresh bin can host the pair
        }
        if fragmentation > 30.0 { new_bin_score -= 12.0; }
        new_bin_score += 10.0 * (1.0 - progress);
        score += new_bin_score;
    }

    // Slight preference for denser bin populations when many bins are open.
    if bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals that can still host typical items (>= 10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just below the next item (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, opening is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when many bins are open (consolidation pressure).
        score = bin_capacity as f64 * 0.5 + 20.0 * (open_bins_count as f64).ln().max(0.0);
        if post_residual < 10 {
            score += 0.0; // empty bin post_residual == capacity - item, handled naturally
        }
        if fitting_bins_count == 1 {
            // An open bin is the last chance; strongly prefer it over a new bin.
            score += 120.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Roomy pairing possible; opening a new bin is mildly attractive.
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Dead space: post_residual too small for the next item (unusable in lookahead)
    if next_item_size > 0 && post_residual < next_item_size {
        // penalize relative to how close it came to fitting the next item
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.8;
        // extra penalty if post_residual is a small dead zone (< 10)
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // If post_residual can still fit the next item comfortably, mild reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Compare against mean residual: placing into a bin with residual well below mean
    // concentrates fullness (good), placing into a much-larger-residual bin is wasteful
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(30.0) * 0.3;
    } else {
        score += (res - mean_residual).min(30.0) * 0.2;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item nearly fills it
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 80 {
            score -= 40.0; // big item into fresh bin is fine
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 12.0;
    }

    // Late in stream: be more aggressive about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on post_residual so near-exact fills dominate.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids wasted residual in the current bin).
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else {
        // Mild scarcity pressure proportional to how few bins can host the item.
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score -= 12.0 * scarcity;
    }

    // Penalize bins whose residual is far above the item (bad fit leaves dead space),
    // but reward bins whose residual is close to item_size.
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * fit_gap;

    // Lookahead: if next item can fit into post_residual, reward this placement
    // (chains two items into one bin).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - 0.05 * slack; // prefer chaining with small remaining slack
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item could have fit the pre-placement residual; penalize blocking it.
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when the current item is large relative
    // to capacity and no good open-bin fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize opening new bins mildly; less so late in the stream or for big items.
        score += 30.0 - 20.0 * fill_ratio - 10.0 * time_frac;
        // If many open bins already, discourage proliferation.
        score += 0.8 * open_bins_count as f64;
    }

    // Global state: if mean residual is large, prefer consuming the fullest bins
    // (bins with residual below mean are closer to closure).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Small late-stream nudge to close out bins tightly.
    let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * time_frac * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic polynomial in post-residual, modulated by stream progress
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * cap * (0.5 + progress)
        - 25.0 * norm_item * (1.0 - norm_pr) * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit a plausible next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as u32) < next_item_size {
            score += 15.0 + 20.0 * progress * (nx / cap);
        } else {
            score -= 8.0 * (1.0 - (nx / cap)) * (1.0 - norm_pr);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count <= 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Discard fragmentation relative to fleet mean residual
    score += 10.0 * (mean_residual / cap - norm_pr).abs();

    // Mild penalty for proliferating bins early
    score += 2.0 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    // New-bin candidate: make empty bin less attractive unless item is large
    if bin_residual == bin_capacity {
        score += 20.0 - 18.0 * norm_item + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "friendly"
    // to common item sizes (divisible by small harmonics) are less dead.
    let dead = post_residual == 0;
    if dead {
        score -= 1000.0; // perfect fill, always best
        return score;
    }

    // Fraction of capacity wasted
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac; // penalize big gaps superlinearly

    // Harmonic divisibility bonus: how many harmonics of post_residual
    // can host plausible future items (mod arithmetic on residual).
    let mut harmonic_bonus = 0.0;
    for h in [10u32, 20, 25, 33, 50] {
        if post_residual >= h {
            harmonic_bonus += 1.0;
        }
    }
    score -= 6.0 * harmonic_bonus;

    // Next-item lookahead: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0; // next item can't follow here
        }
    }

    // Last-chance bin: only fitting bin -> avoid opening new bin unless fit is terrible
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins unless stream is early
    // or current fit is bad. Empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 80.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 30.0; // big items fine in fresh bins
        }
    }

    // Prefer tighter bins when many are open (contain bin proliferation)
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * waste_frac;

    // Mean residual coupling: if mean residual is large, packing into
    // existing bins is easy; slight penalty for leaving this bin loose.
    if mean_residual > post_residual as f64 {
        score += 2.0;
    }

    // Small residual granularity: residuals < 10 are near-dead
    if post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.14;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect packing (small dead space).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item exactly fills the post-residual, big reward.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if lookahead_gap == 0.0 {
            score -= 80.0; // perfect chain: next item fills this bin exactly
        } else if lookahead_gap <= 5.0 {
            score -= 30.0;
        } else {
            score += lookahead_gap * 0.4; // penalize residuals unusable by next item
        }
        // If next item is huge and won't fit anywhere else, keep space flexible:
        if next_item_size >= 70 && post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // penalize dumping into very roomy bins unless it's a large item.
    let residual_dev = post_residual as f64 - mean_residual;
    score += residual_dev * 0.25;
    if item_size >= 60 {
        score -= 20.0; // big items should go into roomy bins aggressively
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else {
            score += 70.0; // prefer existing bins when they can fit
            // Exception: very large item leaving tiny post-residual in a fresh bin is fine
            if item_size >= 90 {
                score -= 90.0;
            }
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;
    score -= (open_bins_count as f64) * 0.5; // mild pressure to consolidate

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no future item (1..100) could reuse well
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let waste = post_residual as f64 - nxt;
            score -= 18.0 * (1.0 - waste / cap);
        } else if nxt > post_residual as f64 && post_residual > 0 {
            score += 8.0; // blocks the next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // many alternatives: mild penalty for hogging a scarce-fit bin
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // current bins fit poorly or lookahead demands space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 45.0 * (1.0 - 0.5 * progress);
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            open_cost -= 20.0; // no open bin can host the next item
        }
        if post_residual as f64 >= item_size as f64 * 0.5 {
            open_cost += 10.0; // fresh bin will likely be half-empty
        }
        score += open_cost;
    } else {
        // Reward filling already-open bins, more so when many are open
        score -= 2.0 * (open_bins_count as f64).ln() * (item_size as f64 / cap);
    }

    // Global balance: prefer bins whose residual is near the mean (spread waste evenly)
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Time horizon: late in stream, be greedy about tightness
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with quadratic shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Non-linear progress coupling: late in the stream, tighten more aggressively
    let late = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += late * 25.0 * norm_pr;

    // Penalty for large dead space relative to the next item (wasted capacity)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += 0.5 * gap * gap / cap;
    } else {
        score += 0.3 * pr * pr / cap;
    }

    // Last-chance bin bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * late;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins that keep residuals balanced
    score += 0.2 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so we only open when truly necessary,
    // with a smooth escape hatch when existing fits are very poor
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (1.0 - norm_pr) * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity split into quarters
    let item_class = item_size / 25;
    let post_class = post_residual / 25;

    // Reward when post_residual lands in a "useful" harmonic class
    // (large-enough leftovers that future items can fill them)
    if post_class >= 1 {
        score -= 6.0 * post_class as f64;
    } else if post_residual > 0 {
        // tiny dead space: penalize proportionally
        score += 4.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Modulo coupling: item + next_item_size sums that align with capacity
    // fractions get a lookahead reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_sum = item_size + next_item_size;
            let pair_mod = pair_sum % 25;
            if pair_mod == 0 {
                score -= 12.0; // pair sums to a quarter-boundary: likely chained fit
            } else if pair_mod >= 20 {
                score -= 5.0;
            }
            // can next item also fit here? then prefer keeping room
            score -= 3.0;
        } else {
            // next item won't fit here; leftover must serve others
            if post_residual < 10 && post_residual > 0 {
                score += 8.0; // stranded sliver
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins slightly; worse late in stream or when few bins fit
        let mut new_bin_penalty = 10.0 + 15.0 * progress;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        } else if fitting_bins_count == 1 {
            new_bin_penalty += 20.0; // definitely use the existing last-chance bin
        }
        // large items prefer fresh bins (avoid fragmenting)
        if item_class >= 3 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty;
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate penalty for gaps below typical small-item sizes.
    if post_residual > 0 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (best-fit flavor).
    score -= 2.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual is below mean (fill emptier-relative bins less).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item nearly fits, slight penalty for blocking it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: mild penalty so it's only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly (or nearly)
    // matches the next item's size, penalize dead space that cannot serve the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item => strong reward
        score -= 40.0 / (1.0 + diff);
        // Penalize residuals too small for next item (wasted dead space)
        if (post_residual as i64) < (next_item_size as i64) {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
        // Penalize large leftover relative to mean residual (fragmentation)
        if post_residual as f64 > mean_residual {
            score += 0.3 * (post_residual as f64 - mean_residual);
        } else {
            score -= 0.15 * (mean_residual - post_residual as f64);
        }
    } else {
        // Last item: minimize post residual (fill as tightly as possible)
        score -= 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for filling already-open bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress;

    // Penalize very tight fits that leave unusable slivers (< 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 20.0 + 0.2 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small dead space bonus: residual below smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, big reward (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Penalize leaving residual that next item cannot use if it's awkwardly small.
            if post_residual < next_item_size && post_residual < 20 {
                score += 10.0;
            }
        }
    } else {
        // Last item in stream: just minimize waste, prefer tightest fit.
        score -= 10.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading; few open bins -> new bin ok.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open and mean residual is high.
        score += 30.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        // Late in stream, opening new bins is cheaper than fragmenting.
        score -= progress * 15.0;
    } else {
        // Existing bin: reward using bins with below-average residual (balance preservation).
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.2;
    }

    // Mild preference for reusing bins over opening new ones early.
    if open_bins_count > 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let tightness = 1.0 - pr / cap;

    // Core: reward tight fits with a smooth polynomial of post_residual
    let mut score = pr * (1.0 - 0.6 * tightness * tightness);

    // Non-linear coupling of tightness with stream progress: late in stream,
    // prefer filling bins nearly perfectly (dead space costs more).
    score -= 12.0 * tightness.powi(3) * (progress * (1.0 - progress) * 4.0);

    // Smooth interaction: item size relative to residual, penalize big gaps
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 8.0 * gap * gap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - progress * 0.5);
    }

    // Penalize opening new bins when many bins are already open and residual is plentiful
    let new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if new_bin {
        score += 10.0 + 5.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        // but allow opening when mean residual across bins is small (nothing fits well)
        score -= (mean_residual / cap).powi(2) * 15.0;
    }

    // Mild normalization against mean residual state
    score += 0.02 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: modulo classes of post_residual.
    // Residuals divisible by 10 are "harmonic" (easily re-filled by items
    // sized 10..80 on a 10-grid); odd/prime-ish leftovers are dead space.
    let pr = post_residual;
    let harmonic = (pr % 10 == 0) as f64;
    let semi = (pr % 5 == 0 && pr % 10 != 0) as f64;
    score -= harmonic * 6.0;
    score += semi * 2.0;

    // Integer-division thresholds: very small leftovers are wasted space.
    let q = pr / 10; // decile class of leftover
    if q == 0 {
        score += 12.0; // dead space (<10) penalty
    } else if q <= 2 {
        score += 4.0 * (3 - q) as f64;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // exact fill bonus when next item perfectly consumes leftover
            if next_item_size == pr { score -= 15.0; }
            else { score -= 3.0 + 0.1 * (pr - next_item_size) as f64; }
        } else {
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, opened only if open bins
    // are all poor fits. Penalize slightly so tight fits win, but keep
    // attractive when open-bin residuals are tiny/fragmented.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.25 * open_bins_count as f64
            - 0.05 * mean_residual
            + (step_index as f64 / (total_items.max(1) as f64)) * 5.0;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big item coming: fresh bin is valuable
        }
    }

    // Mild preference for filling fuller bins (tightness coupling).
    score -= 0.05 * (cap - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that can fit the lookahead item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when new-bin option exists.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 3.0 * (1.0 - progress);

    // Prefer bins tighter than the mean residual (fill fuller bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        score -= 20.0;
        if post_residual > 30 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (2-step lookahead archetype)
    if post_residual == 0 {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 800.0;
    }

    // Reward when next item fits into post_residual (2-step chain)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (next_item_size as f64 / bin_capacity as f64) * 60.0;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use
        score += (next_item_size as f64 - post_residual as f64).min(50.0) * 1.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 2.0;

    // Penalize small unusable residuals (< 10, min item size)
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Last-chance bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Mildly discourage opening new bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 25.0 + 50.0 * progress;
        // Allow new bin if current bin would leave large dead space
        if post_residual > 40 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: prefer reusing open bins when the fit there is decent.
        score += 12.0;
        // If the item fits the empty bin perfectly, opening a new bin is great.
        if post_residual == 0 {
            score -= 20.0;
        } else if post_residual <= 5 {
            score -= 10.0;
        }
        // Late in the stream, waste matters more: make new bins slightly less attractive
        // unless the fit is perfect (already handled above).
        score += 8.0 * progress;
        // If many bins are open with slack, discourage opening yet another.
        score += 0.6 * open_bins_count as f64 * (mean_residual / cap).max(0.0);
        // Lookahead: if the next item would fit in the leftover of this fresh bin,
        // opening it is more attractive.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 4.0;
        }
        return score;
    }

    // --- Existing bin handling ---
    // Reward tight fits beyond the raw best-fit term.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 6.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Dead-space penalty: small residuals (<10) are nearly unusable given item >= 1,
    // but with unknown distribution keep a mild penalty proportional to waste.
    score += 0.05 * post_residual as f64 * (1.0 + progress);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer bins that keep more usable residual
        // relative to the mean slack across bins.
        score += 0.5 * (mean_residual - post_residual as f64).max(-5.0).min(5.0);
    }

    // Lookahead (k=2): reward placements that leave room for the next item,
    // with a bonus that grows with how snugly the next item would fit.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            let snug = 1.0 - (next_item_size as f64 / post_residual as f64);
            score -= 3.0 + 4.0 * snug;
        } else {
            // Penalize placements that leave a residual the next item cannot use,
            // scaled by how much slack is wasted.
            let waste = post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0);
            score += 0.4 * (waste / cap) * 10.0;
        }
    }

    // Stream-horizon coupling: early on, keep bins flexible (favor larger residuals);
    // late in the stream, prioritize closing bins tightly.
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / cap);
    score -= progress * 3.0;

    // Mild preference to fill bins that are already partially loaded (bin consolidation).
    score -= 0.3 * (cap - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight post-residual preferred (quadratic to sharpen small residuals)
    let mut score = post * post / cap;

    // Non-linear coupling of post-residual with stream progress:
    // late in stream, tighten further (dead space matters more)
    score += post * (1.0 - progress) * (post / cap);

    // Reward near-perfect fits via smooth sigmoid-like term on fit ratio
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio * fit_ratio;

    // Penalize leaving residuals that cannot host the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0);
        let waste = if post < next_item_size as f64 { post } else { 0.0 };
        score += 1.5 * waste + 0.3 * gap * (gap / cap);
    }

    // Last-chance bonus: smooth exponential reward when few fitting bins
    let scarcity = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 6.0 * scarcity * (1.0 - post / cap);

    // Prefer bins below mean residual early, above mean late (smooth coupling)
    score += 0.5 * (bin_residual as f64 - mean_residual) * (progress - 0.5);

    // Mild penalty for spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with slight late-stream penalty
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Leftovers that form "harmonic" fractions
    // (C/4, C/3, C/2) are more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Distance to the nearest harmonic fraction of capacity.
    let fractions = [cap / 4.0, cap / 3.0, cap / 2.0, 2.0 * cap / 3.0, 3.0 * cap / 4.0];
    let mut min_dist = f64::MAX;
    for f in fractions.iter() {
        let d = (pr - f).abs();
        if d < min_dist {
            min_dist = d;
        }
    }
    score += 0.6 * min_dist;

    // Integer-division class of post_residual: dead space below the smallest
    // item band is nearly unusable; penalize strongly.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 40.0;
    } else if post_residual <= bin_capacity / 8 {
        score += 12.0;
    }

    // Modulo-arithmetic harmony: if post_residual is divisible by a small
    // modulus matching common item classes, reward it (future items often
    // sum into such residuals).
    let pr_u = post_residual;
    if pr_u >= 10 && (pr_u % 10 == 0 || pr_u % 20 == 0 || pr_u % 25 == 0) {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a perfect harmonic match; reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: prefer bins where the joint leftover is harmonic.
        let joint = post_residual - next_item_size;
        if joint % 10 == 0 {
            score -= 6.0;
        }
        score += 0.3 * (joint as f64);
    } else if next_item_size > 0 {
        // Next item cannot use this residual; penalize proportionally.
        score += 0.5 * (next_item_size as f64 - pr).max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless residual would be tiny).
    if fitting_bins_count == 1 && post_residual >= dead_threshold {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; bias
    // it so it wins only when the item is large relative to typical
    // residuals, or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / 10.0;
        // Opening a new bin is attractive for big items or crowded states.
        score -= 8.0 + 6.0 * (item_size as f64 / cap) + 3.0 * crowd.min(3.0) + 4.0 * progress;
        // But discourage opening when mean residual is large (plenty of room).
        score += 0.25 * mean_residual.max(0.0);
    }

    // Mild preference for tighter fits among open bins (waste minimization).
    score += 0.05 * (bin_residual as f64 - pr);

    // Progress-based tightening: as the stream nears its end, prioritize
    // closing out bins (minimize post residual more aggressively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.4 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: prefer consolidating into fewer bins.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: mild penalty so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if all open bins would leave tiny dead space, allow opening a new bin.
        if fitting_bins_count > 0 && post_residual < 10 {
            score -= 60.0;
        }
    }

    // Slight preference for tighter bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but reward exact matches for lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // 2-step lookahead: reward bins whose leftover can host the next item,
        // strongest when post_residual == next_item_size (perfect chain).
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to wasted lookahead potential.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.35 * miss.min(40.0);
    }

    // Relative-to-mean coupling: bins tighter than average are valuable, use them first.
    let resid = post_residual as f64;
    let dev = resid - mean_residual;
    score += 0.20 * dev.max(-50.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the fit here
    // is poor or the item is large (keeps big residual bins flexible).
    if bin_residual == bin_capacity {
        let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
        // Empty bin starts with a handicap; removed when the item is big.
        score += 20.0 - 25.0 * fit_quality;
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else if post_residual == 0 {
        // Perfect fill: huge reward.
        score -= 60.0;
    }

    // Small penalty for leaving dead space below the minimum item size (1..100 interface).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical future item.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
            (post_residual as f64) * (1.0 + (next_item_size as f64 - post_residual as f64) / 100.0)
        } else {
            0.0
        };
        score += 0.35 * dead;
    }

    // Lookahead synergy: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer fuller ones.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state coupling: when open bins have large mean residual, prefer
    // spreading load (favor bins above mean residual slightly).
    let diff = (bin_residual as f64) - mean_residual;
    score -= 0.10 * diff;

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize using bins less); late in stream, consolidate tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - t) * (post_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * t * tightness;

    // Many open bins: encourage closing bins by filling them.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * tightness;

    // New-bin candidate: penalize opening a fresh bin unless residuals are poor.
    if bin_residual == bin_capacity {
        let avg_fill = mean_residual / (bin_capacity as f64);
        score += 18.0 - 30.0 * (1.0 - avg_fill).min(1.0);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + 0.5 * x * x * x * progress;
    score += 8.0 * poly;

    // Reward tight fits, more aggressively as stream progresses
    let tight = 1.0 - x;
    score -= tight * tight * (1.0 + 6.0 * progress);

    // Penalize dead space relative to mean residual
    let dead = (post - mean_residual) / cap;
    score += 4.0 * dead * dead.abs();

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: favor residual that can still fit the next item
    if next_item_size > 0 {
        let fits_next = if (post as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 2.5 * fits_next * (1.0 - progress);
    } else {
        // Last item: strongly favor minimal residual
        score -= 5.0 * tight;
    }

    // Slight penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "useful" for
    // typical future items (multiples of common size classes) get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (pr / cap);
    score -= 0.9 * tightness * tightness * cap * 0.1;

    // Penalize "dead zone" residuals: too small to fit typical items
    // (items between 1 and 100; residuals below ~15 are nearly useless).
    if post_residual < 15 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Harmonic / modulo logic: residuals divisible by common item classes
    // (10, 20, 25, 50) are more likely to be filled exactly later.
    let harmonic_bonus: f64 = if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        9.0
    } else if post_residual % 20 == 0 {
        7.0
    } else if post_residual % 10 == 0 {
        5.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but consider leftover quality.
            let next_left = post_residual - next_item_size;
            if next_left < 10 {
                score -= 18.0;
            } else if next_left % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
        } else {
            // Next item won't fit here; mildly penalize unless this bin
            // would otherwise be stranded.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize placing into a fresh empty bin unless the item is large
    // (large items deserve their own bin; small items should fill leftovers).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if item >= 60.0 {
            score -= 15.0;
        } else {
            score += 10.0 + 20.0 * (1.0 - item / 100.0);
        }
    }

    // Prefer bins below the mean residual when item is small (consolidate
    // small items into emptier bins), above mean when item is large.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    if item < 40.0 {
        score += 5.0 * dev;
    } else {
        score -= 5.0 * dev;
    }

    // Mild pressure to use many open bins down as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 1000.0; // truly unusable sliver (defensive)
        }
        // Penalize gaps too small for the smallest plausible item (1..100 unknown dist):
        // treat gaps below ~15 as "dead" but scale with how dead they are.
        let dead_threshold = 15.0f64;
        if (post_residual as f64) < dead_threshold {
            let deadness = (dead_threshold - post_residual as f64) / dead_threshold;
            score += 300.0 * deadness;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 200.0;
    }

    // Reward tight fits generally (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 50.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }
    // If next item cannot fit in post_residual but could fit in a larger residual,
    // mildly penalize wasting space the lookahead could have used.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 30.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> discourage new bins, encourage filling existing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow early when mean residual is low.
        score += 80.0 + 40.0 * pressure * (0.5 + 0.5 * progress);
        // If existing bins fit poorly (high mean residual implies fragmentation),
        // a fresh bin becomes more attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 60.0;
    } else {
        // Existing bin: reward using it more when many bins are open.
        score -= 10.0 * pressure;
    }

    // Mild preference for filling bins that are already mostly full.
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits into post_residual with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 40.0).max(0.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual cannot host next item: penalize dead space, worse if small.
        score += 12.0 * (1.0 - post_residual as f64 / 30.0).max(0.0);
    }

    // Tight fit now (very small post residual) is good unless it blocks next item.
    if post_residual <= 5 {
        if next_item_size == 0 || post_residual != next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the current mean residual (good fill).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Prefer opening new bins early in the stream when the fit is loose.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 40 {
        score += (1.0 - progress) * 10.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual, relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residual too small to hold typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here after placement; slight penalty if we leave large gap
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a penalty so we prefer existing bins,
    // unless existing fits are very poor (high post_residual) or none fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalty shrinks late in stream when consolidating matters less
        let new_bin_penalty = 55.0 * (1.0 - 0.3 * progress);
        // If post_residual of a new bin (capacity - item) is small, item nearly fills a bin -> good
        let fullness = item_size as f64 / bin_capacity as f64;
        score += new_bin_penalty - 35.0 * fullness * fullness;
        // If many open bins with high mean residual, opening new bin is wasteful
        score += 0.15 * mean_residual;
    } else {
        // Prefer bins whose residual is close to item size (best-fit flavor)
        let gap = (bin_residual - item_size) as f64;
        score += 0.05 * gap;
        // Mild load-balancing: prefer bins below mean residual slightly
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        }
    }

    // Time horizon: late in stream, be more conservative about new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Quadratic waste penalty: small residuals are dead space.
    score += 12.0 * norm_post * norm_post;

    // Tight fits rewarded, scaled by stream progress.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Smooth cubic coupling of post_residual with progress.
    score += 18.0 * norm_post * norm_post * norm_post * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_post);
    }

    // Lookahead: if next item fits in post_residual, reward leaving this residual.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize opening a new bin when it wastes capacity,
    // but relax penalty as stream progresses (fewer chances to consolidate).
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
        score += 30.0 - 15.0 * progress - 8.0 * open_pressure;
        // If item is large relative to capacity, new bin is fine.
        score += 10.0 * (item_size as f64 / cap);
    }

    // Mild dispersion penalty: keep residuals near the mean balanced.
    score += 3.0 * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how it decomposes relative to capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // residual as fraction of capacity

    // Penalize residual proportionally (dead space), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += frac * 30.0 * (0.5 + progress);

    // Perfect fit reward: post_residual in harmonic class 0 mod 10 (typical item quantum).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual == 0 {
        score -= 40.0; // exact fill
    }

    // Class check: does the post-residual align with the lookahead item (exact future fit)?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 8.0;
            }
            // penalize leaving a sliver that nothing small can use
            if slack < 10 {
                score += (10 - slack) as f64 * 2.0;
            }
        } else {
            // next item cannot fit here; residual is dead unless another item lands
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: only exact fill matters
        if post_residual > 0 {
            score += 10.0;
        }
    }

    // Integer-division thresholds on post_residual: classify residual bands.
    let band = post_residual / 25; // 0..4 harmonic bands
    match band {
        0 => score += 5.0,          // tiny sliver: mostly dead space
        1 => score -= 3.0,          // 25-49: usable for mid items
        2 => score -= 6.0,          // 50-74: very usable
        _ => score -= 2.0,          // 75+: nearly empty bin
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.6 {
            score -= 35.0;
        } else {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: neutral baseline, slightly better when many bins
    // are open and mean residual is high (fragmentation present).
    if bin_residual == bin_capacity {
        score = 55.0 + frac * 10.0;
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big item coming: fresh bin is attractive
        }
    }

    // Mild tie-breaker toward filling fuller bins first when scores are close.
    score -= (bin_residual as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post-residual gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 12.0 - slack as f64;
            } else {
                score += 0.15 * slack as f64;
            }
        } else {
            // next item won't fit here; a leftover gap that is too small hurts more
            if post_residual < next_item_size && post_residual < 15 {
                score += 10.0;
            }
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (tighter bins) for tighter fits.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a bin; reduced late in the stream pressure
        score = bin_capacity as f64 - 5.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 40.0; // opening a bin is fine if it's the only option anyway
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // exact match for next item is excellent
        score -= 80.0 * (1.0 - gap / 60.0).max(0.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't fit here: dead space penalty scaled by wasted capacity
        let dead = next_item_size as f64 - post_residual as f64;
        score += 0.8 * dead.min(60.0);
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize leaving awkward small residuals that nothing can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // New-bin candidate: only attractive when open bins are very tight or item is huge
    if bin_residual == bin_capacity {
        let tightness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // open new bin only if existing bins have little room relative to item
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - tightness);
        score += 200.0 - 250.0 * pressure;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 60.0;
        }
    }

    // Slight preference to fill earlier bins as stream progresses
    score += 0.05 * (step_index as f64 / total_items.max(1) as f64) * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.15;
    } else {
        score -= 30.0; // perfect fit is excellent
    }

    // Reward filling a bin deeply relative to capacity.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 12.0;
        } else {
            // next item cannot use this residual: slight penalty for wasted space
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Attractive when item is large and residuals are fragmented.
        let large_item = item_size as f64 / bin_capacity as f64;
        if item_size as f64 > mean_residual {
            score -= 25.0 * large_item;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins with small residuals -> reuse instead.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score = -100.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate fragmented space).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress + 0.6 * progress * norm_pr);

    // Penalize large dead space quadratically as stream advances
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Reward tight fits (small post residual), stronger late in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 20.0 * (0.5 + progress);

    // Last-chance bin bonus: strongly favor when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Lookahead: favor leaving room for the next item
    let nis = next_item_size as f64;
    if nis > 0.0 {
        if pr >= nis {
            score -= 8.0 * (pr - nis) / cap;
        } else {
            score += 6.0 * (nis - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);

    // Prefer bins whose residual is below the mean (consolidating fullness)
    score += (mean_residual - pr) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and integer-division tiers
    let r = post_residual;
    let residue = (r % 10) as f64;
    let tier = (r / 10) as f64;

    // Penalize awkward residues (dead space hard to fill with 1..100 items)
    let awkward = match r % 10 {
        0 => -6.0,   // perfectly aligned residual
        1 | 2 | 8 | 9 => 4.0, // tiny slivers
        3 | 7 => 1.5,
        _ => 0.0,
    };
    score += awkward;

    // Tier coupling: large aligned residuals are valuable, tiny tiers are dead space
    if tier >= 5.0 {
        score -= tier * 0.8;
    } else if tier <= 1.0 && r > 0 {
        score += 8.0;
    }

    // Lookahead harmony: does next_item_size divide/fit the post residual nicely?
    if next_item_size > 0 && r > 0 {
        let fits_next = next_item_size <= r;
        if fits_next {
            let slack = (r - next_item_size) as f64;
            score -= 10.0 - slack * 0.25; // reward exact/near-exact next fit
            if r % next_item_size == 0 {
                score -= 6.0; // divisor harmony
            }
        } else {
            score += 5.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = (bin_capacity - item_size) as f64;
        score = 60.0 + fit_quality * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
        if open_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mean residual drift: prefer bins near the mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late stream: tighten packing as we approach the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize residuals too small for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (penalize the empty-bin candidate implicitly via residual, but also
    // add pressure proportional to open bins when the fit is loose).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 10.0 + 2.0 * (open_bins_count as f64) * (0.5 + 0.5 * progress);
    } else {
        // Slight reward for using existing bins when bin count is high.
        score -= 0.5 * (open_bins_count as f64).min(20.0);
    }

    // Prefer bins with residual above the mean (consolidating space).
    score += 0.1 * ((post_residual as f64) - mean_residual);

    // Reward leaving room for the next item if it fits exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 10.0; // next item will nearly perfectly fit here
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is an excellent pairing.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 150.0;
        } else if gap <= 5 {
            score -= 90.0;
        } else {
            // Smaller leftover after the hypothetical next placement is better.
            score -= 40.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // Penalize when next item cannot fit here (dead space risk), scaled by
    // how large the unusable leftover is.
    else if next_item_size > 0 {
        let waste = post_residual as f64;
        score += 0.3 * waste;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // Penalize opening a new empty bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        // New bin baseline: prefer it only if no good alternative exists.
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild preference for tighter bins overall.
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // New-bin candidate: penalize unless it's genuinely useful.
    if bin_residual == bin_capacity {
        // Opening a new bin is bad when an open bin fits decently.
        score += 250.0;
        // But if this bin is the last chance, opening is fine.
        if fitting_bins_count == 1 {
            score -= 300.0;
        }
        // Late in the stream, avoid spawning bins with tiny leftover demand.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 120.0 * progress;
        }
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size > bin_capacity / 2 && next_item_size > 0 {
            score -= 60.0;
        }
    }

    // Dead-space penalty: leftover that can't fit the next item is wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward leaving room exactly for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }

    // Reward snug fits (little waste relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Penalize bins far below mean residual (fragmenting a nearly-full bin is fine,
    // but choosing a much-emptier bin wastes global capacity).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Slight preference for tighter global packing early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress + 0.6 * progress * norm_pr);

    // Penalize dead space that cannot fit a typical future item (smooth polynomial).
    let dead = if pr > 0.0 { (norm_pr * norm_pr * (norm_pr - 1.0) + norm_pr) } else { 0.0 };
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits: post residual near zero gets a strong discount.
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (1.0 + 0.5 * progress);

    // Lookahead: if next item fits the post residual exactly, reward strongly.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let fit_quality = 1.0 - (pr - ns) / cap;
            score -= 15.0 * fit_quality * fit_quality;
        } else {
            score += 5.0 * ((ns - pr) / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty for bins that deviate from mean residual (prefer balanced packing).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: slightly discourage when good open bins exist, encourage late.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small leftover" classes are rewarded (waste minimization).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual;

    // Class-based adjustment via integer division thresholds
    let class = pr / eighth; // 0..=8 harmonic class of leftover
    match class {
        0 => score -= 25.0,               // near-perfect fit
        1 => score -= 15.0,               // very tight leftover
        2 => score -= 8.0,                // good leftover
        3 => score -= 3.0,                // moderate
        5 => score += 6.0,               // awkward mid leftover
        6 => score += 10.0,
        _ => {}                           // class 4, 7, 8 neutral
    }

    // Reward tight fits more strongly as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - pr) as f64 * 0.25 * progress;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this is a harmonic chain — reward it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let nxt_class = (pr - next_item_size) / eighth;
            if nxt_class <= 1 {
                score -= 10.0;
            } else {
                score += 2.0 * nxt_class as f64;
            }
        } else {
            // next item cannot use this leftover: penalize large leftovers
            score += 4.0;
        }
    }

    // Penalize bins whose residual deviates wildly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Modulo-10 structure of post_residual: multiples of 10 pair well with
    // typical item granularities.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Slight bias against opening new bins when many bins are already open
    // and this bin is empty (only when it's genuinely a fresh bin candidate).
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        if mean_fill > 0.6 * bin_capacity as f64 {
            score += 12.0; // open bins are well filled; prefer them
        } else {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Strong penalty for leaving a gap that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.5 * (0.5 + progress);

    // Prefer bins tighter than the mean residual (compactness).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when the fit here is poor.
    if bin_residual == bin_capacity {
        if post_residual as f64 >= mean_residual {
            score -= 20.0;
        } else {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Aggressive 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap < 1.0 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else {
            // penalize mismatch proportionally, scaled by how big the next item is
            score += gap * (0.25 + nxt / (2.0 * cap));
        }
        // if next item cannot fit here, this bin leaves dead space for the chain
        if post < nxt {
            score += 15.0 * (nxt - post) / cap;
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "odd" bins;
    // filling them is good (reduces fragmentation), leaving them empty is bad.
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev; // lower post than mean => lower score => favored

    // Last-chance bonus: only this bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist elsewhere.
    if bin_residual == bin_capacity {
        // new bin: neutral residual but discourage unless item is large relative to capacity
        let tightness = item_size as f64 / cap;
        score += 20.0 * (1.0 - tightness); // small items into fresh bins are wasteful
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    // Progression: late in the stream, be greedier about closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Slight penalty for very small unusable slivers (dead space < 10 can't hold anything).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space below the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins
    let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.1);
    score += 0.05 * pressure;

    // Time horizon: late in the stream, favor filling existing bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fit_ratio;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (balancing residuals)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Mild penalty for opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let size_norm = item_size as f64 / cap;

    // Base: non-linear polynomial in post_residual (quartic-ish shaping)
    let mut score = pr * (1.0 + 0.9 * pr_norm * pr_norm);

    // Smooth coupling with stream progress: waste penalized more later
    score *= 1.0 + 0.6 * progress * pr_norm;

    // Tight fits reward: subtract when post_residual is small relative to capacity
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (1.0 + 0.5 * progress);

    // Lookahead: bonus if next item fits into the resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack).powi(2);
        } else {
            // next item won't fit: penalize proportionally to overflow gap
            score += 3.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bin: strongly reward using it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: penalize, less so early in stream or for big items
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * size_norm - 5.0 * progress;
    }

    // Mean residual coupling: prefer bins deviating from mean residual (bin packing diversity)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * 0.1;

    // Mild penalty for too many open bins
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes.
    let class = post_residual / 10;
    score += class as f64 * 2.0;

    // Dead-space penalty: residuals below 10 are nearly unusable.
    if post_residual < 10 {
        score -= 25.0; // reward perfect/complete fills
    } else if post_residual <= 20 {
        score += 8.0; // small dead space, mildly penalize
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains, scaled by how snug the future fit is.
            let snug = (post_residual - next_item_size) as f64;
            score -= 6.0 - snug / 20.0;
        } else {
            // Next item won't fit here: penalize wasted potential.
            score += 5.0;
        }
        // Harmonic pairing: next item exactly consumes the residual.
        if next_item_size == post_residual {
            score -= 15.0;
        }
        // Modulo harmony: next item leaves a multiple-of-10 residual after placement.
        if next_item_size <= post_residual && (post_residual - next_item_size) % 10 == 0 {
            score -= 4.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer bins below mean residual (tighter bins) when many bins open.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it unattractive unless it's early or the fit
    // in existing bins is hopeless (large item, no small residual bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 35.0; // opening a fresh bin for a big item is fine
        }
    }

    // Integer-division threshold: post_residual in [30,50] is a "medium class"
    // that many item sizes (10..80) can still use; keep it moderately attractive.
    if post_residual / 10 >= 3 && post_residual / 10 <= 5 {
        score -= 3.0;
    }

    // Early stream: be greedy with tight fits; late stream: consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        let threshold = 10.0_f64.min(next_item_size as f64).max(1.0);
        if gap < threshold {
            score += (threshold - gap) * 6.0;
        }
        // General dead-space pressure: quadratic in smallness of gap.
        score += (bin_capacity as f64 - gap).ln().abs() * 0.0; // no-op guard
        score += (1.0 - gap / bin_capacity as f64) * 2.0;
    }

    // Reward tight fits (post_residual near zero) strongly.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 1.5;
        // But if the item fits poorly everywhere, new bin may still win; add
        // mild bonus for lookahead compatibility.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 3.0;
        }
    } else {
        // Slight preference for bins whose residual is closest to item size.
        let waste = (bin_residual - item_size) as f64;
        score += waste * 0.5;
    }

    // Lookahead: penalize leaving a gap that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += 4.0;
    }

    // Late in stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual == next_item_size is a perfect pair.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 1000.0; // perfect pair with lookahead item
        } else if post_residual < next_item_size {
            // Dead space: next item cannot fit here; penalize proportionally.
            score += 30.0 + (next_item_size - post_residual) as f64 * 2.0;
        } else {
            // Next item fits: reward closeness of the resulting gap.
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        }
    }

    // Penalize large leftover beyond what the next item can use.
    if next_item_size > 0 && post_residual > next_item_size {
        score += (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (well-packed bins).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Early in the stream, be slightly more willing to keep bins consolidated.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    // Brand-new empty bin candidate: penalize unless it's genuinely attractive
    // (e.g., large item with no good existing fit).
    if bin_residual == bin_capacity {
        score += 60.0;
        if item_size >= bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size == post_residual {
            score -= 40.0;
        } else {
            // penalize leaving space that is too small for typical items
            if post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last chance: strongly favor using the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins relative to global mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Penalize spreading across many open bins early; encourage consolidation
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: empty bin gets a moderate penalty so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // late in the stream, opening new bins is cheaper than dead space
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Time horizon: later items favor using existing space more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linear (dead space grows quadratically)
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling with stream progress: later in stream,
    // penalize residual more strongly (waste matters more).
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr * (0.5 * p2 + 0.8 * p3);

    // Reward tight fits: subtract when post_residual is small relative to item
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * 30.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Penalize bins far from mean residual (encourage homogenized residuals)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Many open bins: slight preference to fill existing ones vs opening new
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: keep it attractive only when residual would be large
    if bin_residual == bin_capacity {
        score += 10.0 - 25.0 * norm_pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 modulate dead-space penalty.
    let residue = post_residual % 10;
    score -= match residue {
        0 => 12.0,                      // perfect decade fit: highly reusable
        1 | 9 => 3.0,                   // nearly-decade: decent
        2 | 8 => 1.0,
        3 | 7 => 0.0,
        4 | 6 => -1.5,                  // awkward residual: slight penalty
        _ => -3.0,                      // residue 5: worst dead zone
    };

    // Integer-division thresholds: large post_residual blocks are valuable.
    let block = post_residual / 25;
    score -= block as f64 * 4.0;

    // Lookahead coupling: reward if next item fits into post_residual harmonically.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_fit = (post_residual - next_item_size) % 10 == 0;
        score -= if pair_fit { 15.0 } else { 6.0 };
    } else if next_item_size > post_residual {
        score += 2.0; // next item won't reuse this bin anyway
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    score += (open_bins_count as f64) * 0.3 - mean_residual * 0.1;

    // Progress term: later in stream, prefer tighter fits (smaller post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: make it unattractive unless it would be nearly perfect.
    if bin_residual == bin_capacity {
        score += 8.0;
        if item_size % 10 == 0 {
            score -= 10.0; // opening fresh for a decade-sized item is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residual gaps (< 10, min item size)
    // are completely unusable -> heavy penalty proportional to wasted space.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Gaps too small for the next item are semi-dead unless tiny.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward near-perfect fits (post_residual small but item actually fits).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize placements that keep many bins open with
    // fragmented residuals; encourage consolidating into bins above mean residual.
    score += open_bins_count as f64 * 0.8;
    if (bin_residual as f64) > mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // or nothing fits well; otherwise keep new bins penalized.
    if bin_residual == bin_capacity {
        score += 45.0;
        if post_residual >= 10 {
            score -= 10.0; // fresh bin keeps a usable gap
        }
        if fitting_bins_count <= 1 {
            score -= 55.0; // no good alternative: opening new bin is fine
        }
    }

    // Late in the stream, prefer closing bins tightly (less need to preserve
    // flexible residuals for the future).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (20.0 - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual strongly favored.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 40.0;

    // Aggressive 2-step lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.25;
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host next item, scaled by how big the gap is.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.15;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving residual near the mean keeps bins balanced; extreme residuals penalized.
    let diff = post_residual as f64 - mean_residual;
    score += (diff * diff).sqrt() * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is huge relative to capacity and few bins fit it, opening may be fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 && fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Early in stream: slightly discourage proliferating bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && progress < 0.3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize dead space that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual <= 40 {
        score += 4.0 * (1.0 - post_residual as f64 / 40.0);
    } else {
        score += 2.0;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (next_item_size as f64 / 100.0);
        // Extra reward if next item fills post_residual exactly.
        if post_residual - next_item_size < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for stranding space.
        score += 5.0;
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * mean_residual * (1.0 - progress);

    // New-bin candidate handling: penalize opening a new bin, more so early on
    // and when other bins can fit the item.
    if bin_residual == bin_capacity {
        let new_bin_base = 30.0 + 25.0 * (1.0 - progress);
        score += new_bin_base;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
        // Opening a new bin is more attractive when open bins are crowded.
        score -= 0.2 * mean_residual;
        // If current item is large, a fresh bin gives flexibility.
        score -= 0.15 * item_size as f64;
    }

    // Slight preference for bins whose residual is close to item size band.
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight fits are rewarded more strongly as the stream progresses (non-linear coupling).
    let tightness = 1.0 - pr / cap;
    score -= 18.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: residuals too small to fit typical items, scaled smoothly by progress.
    let dead = (pr / cap).powi(3);
    score += 25.0 * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }

    // Lookahead: reward if next item fits into post_residual, penalize otherwise.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (pr / cap);
        } else {
            score += 6.0 * (next_item_size as f64 - pr) / cap;
        }
    }

    // Mild penalty when bin is far below mean residual (keeps bins balanced) with smooth coupling.
    score += 4.0 * ((pr - mean_residual) / cap).powi(2);

    // New-bin candidate: slightly penalize early, mildly favor late when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) - 3.0 * progress * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // size classes (10, 20, 25, 50) are more reusable.
    let mut bonus = 0.0;
    if post_residual == 0 {
        bonus += 12.0; // perfect fit, ideal
    } else {
        if post_residual % 10 == 0 { bonus += 4.0; }
        if post_residual % 20 == 0 { bonus += 2.0; }
        if post_residual % 25 == 0 { bonus += 2.0; }
        if post_residual % 50 == 0 { bonus += 3.0; }

        // Dead-space penalty: small unusable leftovers
        if post_residual < 10 {
            bonus -= 8.0;
        } else if post_residual < 20 {
            bonus -= 3.0;
        }

        // Lookahead: does next item fit the post-residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                bonus += 6.0;
                // harmonic match between next item and leftover
                if post_residual % next_item_size == 0 {
                    bonus += 6.0;
                }
            } else {
                bonus -= 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        bonus -= 5.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins
    // would create bad dead space.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral-ish score: full residual, but discourage unless fits are poor
        bonus -= 1.0;
        if open_bins_count == 0 {
            bonus -= 10.0; // must open first bin
        }
    }

    // Progress coupling: later in stream, be slightly more conservative
    // about wasting space (weight dead-space penalty up over time).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let waste_weight = 1.0 + progress;

    score -= bonus * if score > 0.0 { waste_weight } else { 1.0 };

    // Tie-break: prefer tighter bins when residuals are similar
    score -= (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space below the minimum item size (1..10 unusable-ish zone)
            score += (10 - post_residual) as f64 * 12.0;
        } else if post_residual <= 20 {
            // Small gap: only usable by very small future items
            score += (20 - post_residual) as f64 * 4.0;
        } else if post_residual <= 30 {
            score += (30 - post_residual) as f64 * 1.5;
        } else {
            // Large residual is flexible; reward it mildly
            score -= (post_residual - 30) as f64 * 0.3;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // prefer consolidating when few bins are open.
    let open_pressure = open_bins_count as f64;
    score += open_pressure * 1.2;

    // Mean residual coupling: if mean residual is large, discourage adding
    // more slack to already-loose bins (encourage tight fills).
    if (mean_residual - post_residual as f64).abs() > 0.0 {
        score += (mean_residual - post_residual as f64) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; make it unattractive if decent fits exist
        score += 15.0;
        // But if the item is large relative to capacity, a fresh bin may be best
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= item_size as f64 * 0.25 + progress * 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0; // would create fresh dead space for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // 2-step lookahead: strongly reward bins whose leftover matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leftovers that are too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Compare against mean residual: prefer bins below-average residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins
        score += 20.0;
        // But if many bins are open and mean residual is low (fragmented),
        // opening a fresh bin becomes attractive
        if open_bins_count > 3 && mean_residual < 30.0 {
            score -= 35.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily
        if total_items > 0 && (step_index as f64 / total_items as f64) > 0.8 {
            score += 25.0;
        }
    }

    // Slight penalty for very large leftovers that waste capacity
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Reward bins whose residual matches the item well (small slack relative to item).
    if item_size > 0 {
        let slack_ratio = post_residual as f64 / item_size as f64;
        score += slack_ratio * 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 25.0; // perfect chain fit
        } else {
            score += (gap as f64) * 0.3; // discourage wasting lookahead space
        }
    }
    // If next item would NOT fit here anyway, mild penalty is irrelevant; slight
    // reward for leaving this bin as a candidate for later larger items.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // Penalize opening a brand-new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let decent_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual - item_size) as f64 > mean_residual.max(0.0) * 0.5;
        if decent_fit_exists {
            score += 40.0 + 20.0 * (1.0 - progress);
        } else {
            score += 5.0;
        }
        // Late in the stream, opening new bins is less costly (fewer future items
        // to consolidate), so soften the penalty.
        score -= 25.0 * progress;
    }

    // Prefer using bins whose residual deviates above the mean (consolidate
    // fragmented bins, keep tight bins tight).
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += dev * 0.15;
        } else {
            score -= (-dev) * 0.1;
        }
    }

    // Mild pressure to close out nearly-full bins early.
    if post_residual <= 8 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer filling bins tightly; penalize dead space non-linearly.
    let mut score = post;

    // Quadratic dead-space penalty (smooth, grows superlinearly with wasted space).
    score += 30.0 * norm_post * norm_post;

    // Tight-fit reward: cubic coupling of fit quality with stream progress.
    let tightness = 1.0 - norm_post;
    score -= 40.0 * tightness * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item can use the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let reuse = next_item_size as f64 / cap;
        score -= 25.0 * reuse * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (0.3 + progress);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - norm_post);

    // New-bin candidate: keep neutral-to-slightly-high unless residuals are messy.
    if bin_residual == bin_capacity {
        score = post + 15.0 * norm_post - 20.0 * (1.0 - progress) * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors of capacity.
    let r = post_residual as i64;
    let m4 = (post_residual % 4) as f64;
    let m5 = (post_residual % 5) as f64;
    let m10 = (post_residual % 10) as f64;

    // Reward post-residuals in "usable" harmonic classes (multiples of 5/10).
    score -= 6.0 * (1.0 - m10 / 10.0) * (1.0 - m5 / 5.0);
    score -= 3.0 * (1.0 - m5 / 5.0);
    score -= 1.5 * (1.0 - m4 / 4.0);

    // Dead-space penalty: tiny residuals that almost nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            // Harmonic quality of the doubly-post residual.
            score -= 8.0 * (1.0 - (next_left % 10) as f64 / 10.0);
            if next_left < 10 && next_left > 0 {
                score += 10.0;
            }
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and mean residual across open bins is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 45.0 + 20.0 * fragmentation - 15.0 * progress;
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Opening a fresh bin is good if next item is large (better served empty).
            if next_item_size >= 50 {
                score -= 8.0;
            }
        }
    }

    // Mild preference for tighter bins when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size)
    // are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    }
    // Gaps that can only fit tiny items are semi-dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual tightly matches the item (item fills most of bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize alternatives implicitly by rewarding here).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing bins would leave
    // large dead space or open-bin pressure is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened when many bins are open.
        score += 30.0 - 0.5 * open_bins_count as f64;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferation of new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If current item leaves big dead space in this fresh bin and next item
        // can't use it, discourage opening.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Prefer bins whose residual is below the mean (consolidate fullness).
        let diff = mean_residual - bin_residual as f64;
        score += 0.15 * diff;
        // Lookahead synergy: if next item fits the post-residual exactly-ish, reward.
        if next_item_size > 0 && post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        }
        // If next item won't fit, penalize leaving a mid-sized unusable gap.
        if next_item_size > post_residual && post_residual > 0 {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many open bins, favor filling existing ones.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well (chain placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 500.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item fits here afterward: reward proportional to tightness
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item would NOT fit after this placement: penalize
            // creating a residual too small for the lookahead item.
            score += 40.0 + 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: avoid making this bin
    // much worse than average (unbalanced dead space).
    let pr = post_residual as f64;
    if pr < mean_residual - 30.0 {
        score += 0.6 * (mean_residual - pr);
    } else if pr >= mean_residual {
        score -= 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when item is large relative to
    // capacity or no good open-bin fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.7 {
            score -= 60.0; // large item: fresh bin is fine
        } else if fitting_bins_count > 0 {
            score += 90.0; // discourage abandoning usable open bins
        }
        // slight freshness bonus early in stream
        if total_items > 0 {
            score -= 20.0 * (1.0 - step_index as f64 / total_items as f64);
        }
    }

    // Mild preference for tighter bins overall.
    score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 {
        let usable = if post_residual >= 10 { 1.0 } else { 0.0 };
        score += (1.0 - usable) * 18.0;
        // Fragmentation penalty grows as post_residual shrinks below mid-range.
        let frag = (bin_capacity as f64 / 2.0 - post_residual as f64).max(0.0);
        score += 0.08 * frag;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.15 * (item_size as f64);
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Global state: many open bins -> prefer filling existing ones (avoid sprawl).
    score += 0.4 * (open_bins_count as f64);
    // Mean residual coupling: if this bin is far from the mean residual, mild penalty
    // (prefer bins consistent with the current residual profile).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: empty bin gets a moderate baseline so it is only
    // chosen when all open bins score poorly (bad fits / fragmentation).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * (open_bins_count as f64);
        // Late in the stream, opening new bins is more costly.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    // Smooth polynomial coupling: normalized residual (0..1) interacting with progress
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;

    // Quadratic/cubic residual shaping: penalize large dead space super-linearly
    score += 40.0 * norm_post * norm_post * (0.5 + 0.5 * progress);
    score -= 12.0 * norm_item * (1.0 - norm_post) * (1.0 + progress);

    // Exact fit reward (smooth via exp of post residual)
    score -= 25.0 * (-post_residual as f64 / 5.0).exp();

    // Last-chance bonus: strongly favor the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a new bin when residuals
    // across open bins are already large (dead space) and progress is high
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - mean_norm) - 25.0 * mean_norm * (0.5 + progress);
        // Penalize opening new bins early in the stream
        score += 20.0 * (1.0 - progress);
        // If next item is large, new empty bin is attractive
        let norm_next = next_item_size as f64 / bin_capacity as f64;
        score -= 15.0 * norm_next;
    } else {
        // Lookahead: reward bins whose post-residual can still fit the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Mild penalty for too many open bins relative to progress
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Cubic coupling term between item fraction and post-residual
    score += 8.0 * norm_item * norm_post * norm_post * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer minimal post_residual.
    score -= 40.0 * (1.0 - (post_residual as f64) / cap);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: dead space that cannot hold
    // typical items (residual < 10) is nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Next-item lookahead: if the next item fits in post_residual,
    // reward chaining; otherwise penalize leaving a misleading gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / cap);
        } else {
            score += 12.0;
        }
        // Exact next-item match: ideal packing.
        if next_item_size == post_residual {
            score -= 45.0;
        }
        // Modular class: post_residual divisible by next item size
        // suggests repeatable fills.
        if next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins when many bins are open (bin-count pressure).
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= fill_frac * 15.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Mild penalty if this residual is far above mean residual (keeps
    // homogeneous residual classes together).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large relative to remaining capacity elsewhere.
    if bin_residual == bin_capacity {
        score -= 8.0 + 20.0 * (item_size as f64 / cap);
    }

    // Stream progression: slightly tighten packing later in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small to be useful later
    // (below the smallest plausible item chunk) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps in a "danger zone" (small but nonzero) get a graded penalty.
    if post_residual > 0 && post_residual <= 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement (chains well).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item cannot fit in post_residual but the bin residual could
    // have held it, mild penalty for wasting potential.
    if next_item_size > post_residual as u32 && next_item_size <= bin_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (concentrate filling into emptier-relative bins).
    score -= (mean_residual - post_residual as f64) * 0.4;

    // New-bin candidate: neutral-ish baseline with slight early-stream bias
    // toward opening bins, but penalize when many bins are already open.
    if bin_residual == bin_capacity {
        score = 25.0 + 2.5 * open_bins_count as f64 - 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (small post_residual is already good via base).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize post-residuals that are almost-but-not-quite big enough
            // for the next item (dead space trap).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 60.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average when
    // many bins are open (encourage consolidation).
    if open_bins_count > 1 {
        let deviation = mean_residual - bin_residual as f64;
        score += 0.3 * deviation;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit well, especially early
    // in the stream where consolidation matters most.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * (1.0 - progress) + 20.0;
        // If the next item also fits in a fresh bin, opening is more tolerable.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving awkward small residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 6.0 + post_residual as f64 * 0.15;
        } else if next_item_size as u32 <= post_residual {
            score -= 4.0; // lookahead item fits: great packing
        }
        // Perfect pair: item + next item exactly fills bin
        if post_residual as u32 == next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: minimize waste directly.
        score += 3.0 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 10.0 + 8.0 * progress;
        if mean_residual > item_size as f64 {
            new_bin_penalty += (mean_residual - item_size as f64) * 0.3;
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            new_bin_penalty += 5.0; // avoid opening when alternatives exist
        }
        score += new_bin_penalty;
    } else {
        // Mild bonus for spreading load: prefer bins with larger residual among equals.
        score -= bin_residual as f64 * 0.02;
    }

    // Prefer bins whose residual is close to item size (absolute tightness).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let fitting = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: prefer small post-residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: normalized post-residual shaped by stream progress.
    // Later in the stream, dead space becomes more costly -> convex penalty grows.
    let dead_space_penalty = norm_pr * norm_pr * (0.5 + 2.5 * progress) * cap;
    score += dead_space_penalty;

    // Interaction: post-residual vs next item fit quality (smooth sigmoid-like gate)
    // If next item fits into post_residual, reward this bin (subtract).
    let next_fits = if next > 0.0 { (pr - next).max(0.0) } else { 0.0 };
    let lookahead_reward = -next_fits / cap * (1.0 + progress);
    score += lookahead_reward;

    // Penalize leaving residual that is too small for the *minimum* plausible item:
    // smooth bump around small residuals, stronger late in stream.
    let min_item = 1.0f64;
    let too_small = (-((norm_pr - min_item / cap).exp()) + 1.0) * (1.0 + 3.0 * progress) * 5.0;
    score += too_small * if pr < 10.0 { 1.0 } else { 0.0 };

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin), scaled smoothly by scarcity.
    let scarcity = 1.0 / fitting.max(1.0);
    score -= scarcity * 12.0 * (1.0 - progress * 0.5);

    // Coupling with mean residual: prefer bins below mean residual (tighter bins),
    // smooth quadratic divergence penalty.
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * dev.abs() * 8.0;

    // Mild reward for consolidating when many bins are open (pressure term).
    score -= (open / (open + 5.0)) * item * 0.05;

    // New-bin candidate: empty bin has pr == cap; make it attractive only when
    // post-residual of alternatives is hopeless (large residuals) — smooth gate.
    if bin_residual == bin_capacity {
        let openness = (norm_pr - 0.5).tanh();
        score += 15.0 + 10.0 * openness * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets create a staircase of desirability.
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space penalty grows when residual falls into "unusable" small classes.
    if pr > 0 {
        if class >= 1 && class <= 4 {
            // tiny sliver: penalize proportionally to how tiny
            score += (5 - class) as f64 * 6.0;
        } else if class >= 5 && class <= 9 {
            // mid-range residual: mild reward since many item sizes (10..80 grid) can still fit
            score -= class as f64 * 0.8;
        }
    }

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic division: how many copies of the smallest plausible item (10) fit.
    let slots = pr / 10;
    score -= slots as f64 * 2.5;

    // Lookahead coupling: reward if next item fits the post residual exactly or closely.
    if next_item_size > 0 && next_item_size <= pr {
        let gap = pr - next_item_size;
        if gap == 0 {
            score -= 45.0;
        } else if gap <= 10 {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize dead space
        score += (next_item_size - pr) as f64 * 0.5;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += cap * 0.55;
        // forgive the new-bin cost if no existing bin fits well
        let best_existing = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        if best_existing < 1.0 {
            score -= cap * 0.6; // nothing fits: new bin is fine
        } else if fitting_bins_count == 1 {
            // only one fitting bin: keep new-bin expensive to force reuse
            score += 20.0;
        }
        // early stream: allow more bins to spread load
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
        // if next item is huge, a fresh bin is attractive
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Crowding: mildly discourage stuffing a bin when many bins are open and mean residual is high.
    if open_bins_count > 3 && mean_residual > (cap * 0.5) {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residual gaps too small to hold typical future items are wasted.
    // Treat post_residual < 10 as fully dead; ramp penalty as it approaches the dead zone.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    } else {
        // Reward leaving a gap that exactly fits the lookahead item (perfect pairing).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
        // Mild reward for post_residual that can still host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Penalize large leftover gaps only mildly (they remain usable), but
        // penalize "awkward" gaps in the 10..30 range that few items fit.
        let pr = post_residual as f64;
        if pr > 10.0 && pr < 30.0 {
            score += 0.8 * (30.0 - pr);
        }
    }

    // Tight-fit reward: filling most of the bin is excellent.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 15.0 * (fill_ratio - 0.85);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // New-bin candidate handling: an empty bin has full residual. Make it attractive
    // only when the current item is large and fits would leave big awkward gaps,
    // or when no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (amortized, decreases late in stream).
        score += 30.0 + 20.0 * (1.0 - progress);
        // If the item is huge, a fresh bin is natural.
        if item_size >= 60 {
            score -= 20.0;
        }
        // If the next item is also huge, opening fresh space is valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 10 {
                score -= 250.0 - (leftover as f64) * 10.0;
            } else {
                score += leftover as f64 * 0.5;
            }
        } else {
            // Next item cannot fit here; leftover space is likely wasted.
            score += 40.0;
        }
    }

    // Penalize creating dead space relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.8;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Mild penalty for opening a new bin when many bins are already open
    // and fragmentation is low (favor consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 50.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // But if no open bin fits well (post_residual would be tiny elsewhere),
        // the new-bin penalty stays modest since base score = full capacity.
    }

    // Slight preference for tighter bins early in the stream.
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed residual dominates less.
    let tightness = 1.0 - (item_size as f64 / bin_capacity as f64);
    score *= 0.6 + 0.8 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Perfect chaining: residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0
            - 10.0 * (item_size as f64 / bin_capacity as f64)
            - 15.0 * fragmentation / bin_capacity as f64
            - 5.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> favor
    // filling existing bins aggressively.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= (mean_residual - 30.0).min(20.0) * 0.3;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: quadratic polynomial in post_residual, modulated by stream progress
    let mut score = pr * (1.0 + 0.6 * progress) - 0.35 * pr_norm * pr_norm * cap * (1.0 + 1.5 * progress);

    // Reward tight fits: low post_residual gets extra subtraction, stronger late in stream
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (0.5 + progress);

    // Penalize near-empty post_residual dead space (unusable slivers), smoothly
    let dead = (1.0 - pr_norm).max(0.0);
    score += 8.0 * (-(20.0 * pr_norm)).exp() * (0.4 + 0.6 * progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_diff = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - fit_diff).powi(2) * (0.6 + 0.4 * progress);
    } else if next_item_size > 0 {
        // next item won't fit here: mild penalty proportional to wasted potential
        score += 3.0 * pr_norm * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        // Many fitting bins: mild competition pressure toward tighter bins
        score += 0.8 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Interaction with mean residual: prefer bins whose residual deviates favorably
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev - 3.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening new bins unless existing bins are bad fits
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * (1.0 - (item_size as f64) / cap);
    }

    // Open-bin count pressure: many open bins -> favor consolidation
    score += 0.5 * (open_bins_count as f64).powf(1.2) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: dead-space classes.
    // Post-residuals in [0,10) are near-perfect fits; reward strongly.
    if post_residual < 10 {
        score -= 25.0 - (post_residual as f64) * 2.0;
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual >= 90 {
        // Bin nearly empty after placement -> wasted a bin opening on small item.
        score += 15.0;
    }

    // Modulo-10 harmonic class of post_residual: residuals that are multiples
    // of 10 align with common item sizes (10..80 grid), making them reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else {
        score += (post_residual % 10) as f64 * 0.4;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nr = post_residual - next_item_size;
            // Exact match (nr small or harmonic multiple of 10) is excellent.
            if nr == 0 {
                score -= 30.0;
            } else if nr < 10 {
                score -= 12.0;
            } else if nr % 10 == 0 {
                score -= 7.0;
            } else {
                score += (nr % 10) as f64 * 0.3;
            }
        } else {
            // Next item cannot use this residual: mild penalty, but residual
            // may still serve later items; scale by residual size.
            score += 4.0;
            if post_residual >= 10 {
                score -= 2.0;
            }
        }
    }

    // Integer-division threshold: residual / 10 gives usable "slots" of size 10.
    let slots = post_residual / 10;
    score -= slots as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual < 15 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a neutral-ish score so that
    // only genuinely bad fits in open bins cause a new bin to open.
    if bin_residual == bin_capacity {
        score = 45.0
            - (fitting_bins_count as f64) * 3.0
            + (item_size as f64) * 0.1;
        // Open a fresh bin early in the stream to build a portfolio of bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
    }

    // Mean-residual coupling: if this bin is far below mean residual, its
    // leftover space is scarcer; prefer keeping large residuals available.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05;
    }

    // Late-stream tightening: as the stream ends, minimize waste aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    // Many open bins: discourage spreading; reward consolidating into fuller bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.10);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward very tight fits (waste near zero).
    if post_residual == 0 {
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold {
        // already penalized above
    } else {
        // mild reward for leaving space usable by typical next items
        score -= 8.0 * ((post_residual as f64) / bin_capacity as f64);
    }

    // Lookahead: bonus if post_residual exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // post_residual cannot host next item: penalize proportionally
            score += 10.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Encourage filling bins below mean residual (denser bins first).
    score -= 2.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Slight default penalty so tight fits into open bins win;
        // but if many open bins and item is large, opening may be better.
        score += 12.0 - 0.05 * (open_bins_count as f64);
    }

    // Stream progression: late in stream, prefer closing gaps tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (waste grows super-linearly).
    let dead = post_residual as f64;
    score += 0.02 * dead * dead / bin_capacity as f64;

    // Lookahead coupling: if next item fits into this bin's post-residual,
    // reward this bin strongly (chained placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    }
    // If next item would leave this bin nearly empty anyway, slight penalty
    // for consuming it now with a big gap.
    if next_item_size > post_residual && post_residual < next_item_size {
        score += 0.05 * next_item_size as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Relative fit: reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Global state: when many bins are open with scattered residuals,
    // prefer consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_f = open_bins_count as f64;
    score += 0.05 * open_f * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a "small hole" — use it before it becomes dead space.
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev;

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and no tight fit exists.
    if bin_residual == bin_capacity {
        let big = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 20.0 * big;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual, with non-linear penalty on small-but-nonzero waste
    let mut score = pr - 6.0 * (pr * pr) / cap + 4.0 * (pr_norm * pr_norm * pr_norm) * cap;

    // Smooth coupling: residual value depends on stream progress
    // Early on, tight fits matter less; late, prefer near-perfect fills
    score -= 12.0 * (1.0 - progress) * (pr_norm * (1.0 - pr_norm)) * cap;

    // Lookahead: reward residual that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let d = (pr - n) / cap;
        score -= 15.0 * (-d * d * 8.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (smoothly)
    score += 0.05 * (mean_residual - pr) * (mean_residual - pr).tanh();

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Brand-new bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (1.0 - progress) + 3.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose post-residual falls into
    // "small residue" classes (0..10, 20..30, ...) leave dead space that is
    // hard to fill with typical items.
    let pr = post_residual;
    let residue_class = pr % 20; // 20-wide harmonic class
    if pr > 0 {
        // Penalize awkward residues: 1..=9 and 11..=19 are hard slots
        if residue_class >= 1 && residue_class <= 9 {
            score += (10 - residue_class) as f64 * 1.5;
        } else if residue_class >= 11 && residue_class <= 19 {
            score += (residue_class - 10) as f64 * 1.2;
        }
        // Perfect-ish fits get strong reward
        if pr <= 5 {
            score -= 8.0;
        }
    } else {
        // Exact fill is ideal
        score -= 15.0;
    }

    // Integer-division threshold on post_residual: does the next item fit?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Next item chains into this bin: big reward, scaled by tightness
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 5.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers
            // that will be stranded, especially when the leftover is "just barely"
            // below next_item_size (worst harmonic mismatch).
            let gap = (next_item_size - pr) as f64;
            if pr > 0 && gap <= 10.0 {
                score += 6.0 + (10.0 - gap) * 0.8; // near-miss is painful
            }
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when item is large
    // relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a bin decays as stream progresses (sunk bins dominate)
        let open_cost = 25.0 * (1.0 - 0.5 * progress);
        score = open_cost
            + post_residual as f64
            - (fill_frac * 20.0)
            + if open_bins_count == 0 { 0.0 } else {
                // prefer new bin if mean residual is small (existing bins are tight)
                (mean_residual / cap) * -10.0
            };
        // If item nearly fills a fresh bin, opening is attractive
        if item_size >= 80 {
            score -= 15.0;
        }
    }

    // Mild preference for filling fuller bins first (best-fit core), modulated
    // by harmonic class of bin_residual itself.
    let br_class = (bin_residual % 10) as f64;
    score += br_class * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable dead space: small positive gaps (below min item size 1..10)
    // that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 5.0;
    }

    // Penalize gaps that are too small for the lookahead item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward leaving gaps that exactly fit the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins exist;
    // but if this is the last fitting bin, reward using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more when many bins already open.
        score += 10.0 + open_bins_count as f64 * 2.0;
        // But if no open bin fits well (this item leaves dead space everywhere else),
        // the base post_residual (full remaining capacity) already favors it.
    }

    // Mild preference for filling bins with residuals close to mean (balance avoidance of fragmentation).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chaining).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 60.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // penalize wasted slack relative to what next item would consume
            let slack = post_residual as f64 - next;
            score -= 25.0 * (-slack / 30.0).exp(); // tight-but-fitting bonus
        } else {
            // next item cannot fit here -> dead space unless post_residual is tiny
            let waste = next - post_residual as f64;
            score += 8.0 * (waste / 20.0).min(3.0);
        }

        // 3-step chain bonus: if residual after next item also chains
        let chain2 = post_residual as f64 - next;
        if chain2 >= 10.0 && chain2 <= 80.0 {
            score -= 4.0;
        }
    }

    // Penalize very small unusable post_residual (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Prefer bins tighter than the mean residual (fill full bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);

    // Mild preference for opening new bins early in the stream when many
    // open bins already exist (avoid spreading too thin)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 - 20.0 * progress; // cheaper to open bins later
        score += 1.5 * open_bins_count as f64;
    }

    // Small tie-break toward fuller bins
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 120.0;

    // Perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving dead space that cannot fit typical future items
    // (small residuals below ~10 are wasted; moderate residuals are useful).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here: penalize proportionally to wasted space
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // residual of typical open bins, or when open bins are quite full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Prefer new bin when item is big and existing bins are crowded.
        score += 30.0 - fill_ratio * 40.0 - mean_fullness * 25.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean
    // (use the bin that is tighter than average).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: penalize large residuals more as stream advances
    let progress_coupling = progress * (1.0 - progress * 0.5);
    score += 20.0 * progress_coupling * norm_post * norm_post;

    // Perfect fit reward (smooth quadratic)
    let fit_quality = 1.0 - norm_post;
    score -= 15.0 * fit_quality * fit_quality * (1.0 + progress);

    // Dead-space penalty: residuals too small to fit typical future items
    if post > 0.0 {
        let dead = (1.0 - (post / 80.0)).max(0.0);
        score += 12.0 * dead * dead * (0.5 + progress);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fits = if (post_residual as f64) >= next_item_size as f64 { 1.0 } else { 0.0 };
        let slack = (post - next_item_size as f64) / cap;
        score -= 8.0 * fits * (1.0 - slack.abs()).max(0.0);
        score += 4.0 * (1.0 - fits) * progress;
    }

    // Last-chance bin bonus: avoid opening new bins when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate: mild penalty so it's chosen only for genuinely poor fits
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
    }

    // Fragmentation pressure via mean residual
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify dead space by capacity fractions.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Perfect fit: zero residual is ideal.
    if post == 0 {
        score -= 60.0;
    } else {
        // Modulo-class penalty: residual in the "dead zone" (1..=eighth) is nearly unusable.
        if post <= eighth {
            score += 35.0;
        } else if post <= quarter {
            score += 12.0;
        } else if post <= bin_capacity / 2 {
            score -= 8.0;
        } else {
            // Large post-residual: very reusable, strong reward.
            score -= 25.0;
        }
        // Harmonic divisibility bonus: post_residual divisible by common item granularities.
        if post % 10 == 0 {
            score -= 6.0;
        } else if post % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 50.0;
        } else if next_item_size < post {
            let nxt = next_item_size as f64;
            score -= 10.0 * (1.0 - (post as f64 - nxt) / cap);
        } else {
            // Next item cannot follow here: mild penalty scaled by how far off.
            score += 5.0 * ((next_item_size - post) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer tight bins when many bins are open (consolidation pressure).
    score -= (bin_residual as f64 / cap) * 5.0 * (open_bins_count as f64).sqrt();

    // Late in the stream, be more conservative: penalize small residuals more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / cap) * 10.0;

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual matches the next item's needs (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0; // residual too small for next item
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (packing dense bins first).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Mild bias toward filling fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect or near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.5;
        if post_residual == next_item_size {
            score -= 300.0;
        }
        // Penalize if next item cannot fit into this bin after placement
        if post_residual < next_item_size && post_residual > 0 {
            score += 50.0;
        }
        // Bonus if next item fits exactly into the remaining space chain
        if post_residual >= next_item_size {
            let second = post_residual - next_item_size;
            if second <= 10 {
                score -= 100.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    if (bin_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 120.0;
        // Allow new bin if current item is large and lookahead is large
        if next_item_size >= 70 && item_size >= 50 {
            score -= 100.0;
        }
    }

    // Penalize large dead space relative to smallest possible item
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0;
    }

    // Mild late-stream conservatism: keep bins tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space that blocks the next item; penalize more if next item is large.
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
        // If next item is huge, prefer keeping this bin's residual large... handled above.
    }

    // New-bin candidate logic: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: penalize so it only wins when alternatives are bad.
        score += 45.0;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 30.0;
        // If many bins are open with high mean residual, discourage another bin.
        score += (open_bins_count as f64).sqrt() * 3.0;
        score += mean_residual * 0.25;
        // Very large items fit anywhere in a fresh bin; encourage it.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins proportional to how full they'd become.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= fill * 15.0;
        // Discard bins with tiny residual that will likely become dead space anyway.
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Global pressure: many open bins with low mean residual -> consolidate into fuller bins.
    if open_bins_count > 3 && mean_residual < 20.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + progress * progress * 0.8) + pr_norm * pr_norm * 40.0 * (1.0 - progress);

    // Penalize large dead space more than linearly (quartic-ish smooth term).
    score += 12.0 * pr_norm * pr_norm * pr_norm * pr_norm * cap;

    // Reward tight fits smoothly (small post residual).
    score -= 25.0 * (-pr_norm * 6.0).exp();

    // Last-chance bonus: only one bin fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * progress;
    }

    // Lookahead: if next item can use the post residual, reward this placement smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 15.0 * (-gap / cap * 4.0).exp();
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mild pressure toward consolidating into existing bins vs opening new ones.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * open_bins_count as f64 + 20.0 * (1.0 - progress);
    }

    // Slight preference for bins with residuals near the mean (smooth coupling).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are less reusable, penalize them.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize dead space: leftover too small for typical future items.
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 * (20.0 - post_residual as f64);
    }

    // Reward tight fits (perfect packing classes via modulo).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let rem2 = post_residual - next_item_size;
            score -= 20.0 - (rem2 as f64) * 0.2;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + frac * 10.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // no good fit exists; discourage opening new bins when mean residual
    // across open bins is still large.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post_residual as f64).max(0.0);
        score += 15.0 + mean_gap * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for bins below mean residual (concentrate waste).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late-stream consolidation: as the stream progresses, tighten
    // threshold on usable leftovers via integer division classes.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let class = post_residual / 25; // harmonic class 0..4
    score += class as f64 * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward leaving a gap that the known next item can still use.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 {
            // Gap too small for next item: penalize proportionally.
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when it beats poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
        // Opening a new bin is fine if the next item is large and gaps are bad.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Reward bins tighter than the current mean residual (well-utilized bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + 0.5 * progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Next item fits into post_residual: mild reward (chain placements)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space for the next item: penalize proportionally to wasted capacity
        let waste = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.15 * waste;
    }

    // Compare post_residual against mean residual: leaving near-mean residual keeps flexibility
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize creating very small unusable residuals (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins for large items
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - progress);
    }

    // Discourage spreading across many bins when residuals are already tight
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward small dead space super-linearly
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64).powi(3) * 40.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 10.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space penalty if leftover can't fit next item
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin generally, but allow it
    // when the item is large and no good fit likely (poor current fit)
    if is_new_bin {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        let poor_fit_elsewhere = (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;
        let penalty = 30.0
            - 20.0 * (1.0 - fit_quality)               // big items justify new bins
            - 15.0 * poor_fit_elsewhere.max(0.0)        // if existing bins fit poorly
            + 10.0 * progress;                          // late stream: consolidate instead
        score += penalty.max(2.0);
    }

    // Mild consolidation pressure: fewer open bins -> prefer reusing existing bins
    if !is_new_bin {
        score -= 2.0 * (open_bins_count as f64).sqrt().min(6.0) * (1.0 - progress);
    }

    // Prefer bins below mean residual (keeps residual distribution tight)
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress * (1.0 - progress) * 4.0);
    score += 20.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next > 0.0 {
        let waste = (pr - next).max(0.0) / cap;
        score += 10.0 * waste * waste * (1.0 + progress);
        // Bonus if next item fits exactly-ish
        let fit_next = (pr - next).abs() / cap;
        score -= 8.0 * (1.0 - fit_next.min(1.0)) * (1.0 - norm_pr);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this placement fragments capacity
    let frag = (norm_pr - mean_residual / cap).abs();
    score += 5.0 * frag * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: penalize opening new bins early, relax late
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) * (1.0 - item);
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: harmonic class 0 (post_residual divisible by capacity quarters)
    let quarter = bin_capacity / 4;
    if post_residual % quarter == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // Penalize small dead-space classes (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Next-item lookahead: reward if next item fits the post residual exactly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic class of the pair
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: neutral baseline, open new bin only if
    // no good harmonic fit exists among open bins
    if bin_residual == bin_capacity {
        score = 45.0 - (mean_residual / bin_capacity as f64) * 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big-first strategy benefits from fresh bin
        }
        if fitting_bins_count <= 1 {
            score += 10.0; // keep using existing bins when they are scarce fits
        }
    }

    // Late-stream consolidation: prefer tight fills as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += (post_residual as f64 / bin_capacity as f64) * 10.0 * (1.0 - progress);

    // Mean-residual coupling: penalize bins far from the fleet mean (harmonic balance)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than moderate ones.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += pressure * 3.0;
        // But allow new bins early or when mean residual is low (existing bins are full-ish).
        score -= (mean_residual - 10.0).max(0.0) * 2.0;
    } else {
        // Reward placing into existing bins proportional to how full they already are.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= fullness * 15.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    }
    // If next item would exactly fill post-residual, extra reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: if the next item exactly matches the post_residual,
    // strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits in leftover space: reward proportionally to how much
            // of the leftover it consumes (tight chain).
            let consumption = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * consumption;
        } else {
            // Next item cannot use the leftover: penalize dead space, more so
            // when the leftover is small (unusable sliver).
            let sliver = post_residual as f64 / bin_capacity as f64;
            if sliver < 0.15 {
                score += 20.0 * (0.15 - sliver) * 100.0;
            }
        }
    } else {
        // Last item: pure tightness, no future to plan for.
        score -= 10.0;
    }

    // Reward bins whose residual is below the mean (they are the "tight" ones),
    // penalize bins with residual well above the mean (wasteful to touch them).
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        // But if the fit leaves a tiny dead sliver and the next item is large,
        // soften the bonus so a new bin can win.
        if next_item_size > post_residual && post_residual < 10 {
            score += 30.0;
        }
    }

    // New-bin candidate: make it attractive only when the item is large relative
    // to capacity or very late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let new_bin_bias = 15.0 + 40.0 * large_item + 10.0 * progress;
        score += new_bin_bias;
        // If next item is huge, opening a fresh bin is often better.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight preference to fill older/more crowded bin sets early in the stream.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to how well the item fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space that nothing can use (sizes >= 1, so residual 0 is perfect).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 12.0; // nearly-useless sliver
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive
    // when existing bins fit poorly or this is a near-perfect fresh start.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_bins_count as f64 };
        // Base cost of opening a bin, reduced when fits are scarce or stream is early.
        let mut open_cost = 30.0 + 20.0 * (1.0 - progress);
        open_cost -= 25.0 * (1.0 - scarcity.min(1.0));
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            let la = next_item_size as f64;
            if la as u32 >= bin_residual && la <= bin_capacity {
                open_cost -= 15.0; // next item won't fit residual anyway
            }
            open_cost -= 0.05 * la;
        }
        // Few open bins => consolidation matters less, opening is cheaper.
        open_cost -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        score += open_cost;
    } else {
        // Existing bin: last-chance bonus — if this is the only fitting bin, prefer it.
        if fitting_bins_count == 1 {
            score -= 20.0;
        } else if fitting_bins_count == 2 {
            score -= 6.0;
        }

        // Lookahead synergy: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            let la = next_item_size as f64;
            let pr = post_residual as f64;
            if la == pr {
                score -= 30.0;
            } else if la < pr {
                score -= 10.0 * (la / pr.max(1.0));
            } else {
                // Next item won't fit here; leaving large residual is less valuable.
                score += 6.0 * ((la - pr) / bin_capacity as f64);
            }
        }

        // Prefer bins below mean residual (consolidate emptier bins' contents).
        score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

        // Mild preference for using bins with more residual (balance across bins).
        score -= 0.03 * bin_residual as f64;
    }

    // Time-horizon modulation: late in the stream, avoid spreading across many bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        score += 0.05 * open_bins_count as f64 * post_residual as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post residual with stream progress
    let mut score = pr as f64;
    score += 12.0 * (x - 0.5) * (x - 0.5) * (1.0 + progress);
    score -= 20.0 * x * (1.0 - x) * (1.0 + 0.8 * progress);

    // Reward tight fits, penalize dead space more strongly as stream progresses
    let tightness = 1.0 - x;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0 + 25.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
    }

    // Prefer bins below mean residual (denser bins) with smooth coupling
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap) * (1.0 + progress);

    // Mild penalty on many open bins to discourage spreading
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it competitive only when it looks clean
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits: post_residual in low harmonic classes
    let class = (post_residual % (bin_capacity / 4).max(1)) as f64;
    score -= 6.0 * (1.0 - class / (bin_capacity / 4).max(1) as f64);

    // Penalize dead space that no realistic item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual > 50 {
        score += 0.35 * (post_residual as f64 - 50.0); // large leftover is reusable
    } else {
        score += 0.9 * post; // mid-range leftover: penalize proportionally (Best-Fit-like)
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 14.0;
        // extra reward for exact harmonic pairing
        if post_residual % next_item_size.max(1) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty scaled by gap
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 20.0 + 10.0 * progress;
        if item_size > bin_capacity / 2 {
            open_penalty -= 12.0; // big items are fine to start fresh
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            open_penalty += 8.0; // pairing opportunity wasted if not used
        }
        score += open_penalty;
    }

    // Mild preference for bins below mean residual (keeps balance)
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward zone" residuals: too small for medium items, likely dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: more open bins -> prefer filling existing ones,
    // penalize opening new bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is small or the item is large relative to it.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Mild baseline so it usually loses to decent fits...
        score += 30.0 + progress * 10.0;
        // ...but wins when existing bins are badly fragmented.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
        }
    }

    // Lookahead: if the next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and post-residual is a tiny unusable sliver, penalize more.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item can still fit after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space: next item cannot use the leftover space.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.8 * waste;
    }

    // Penalize very small unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer not opening new bins when many bins are open and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (1.0 - progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Penalize dead space that can't fit typical small items
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: prefer bins whose post_residual fits next item well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 - (slack / 40.0).min(6.0);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // existing residuals are all poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_state = (mean_residual - item_size as f64).max(0.0);
        score += 15.0 - poor_state * 0.3 - progress * 5.0;
        if open_bins_count == 0 {
            score -= 30.0;
        }
        // avoid opening new bin when a near-perfect fit exists elsewhere
        if mean_residual < item_size as f64 + 10.0 {
            score += 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.15;

    // Time horizon: early on, be slightly conservative; later, pack tighter
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits, with progress-dependent curvature
    let mut score = x * (1.0 + 0.8 * progress * (1.0 - x));

    // Quadratic coupling: as stream advances, penalize large leftovers more sharply
    score += 1.5 * progress * x * x;

    // Dead space penalty: unusable space for typical next items
    if next_item_size > post_residual && next_item_size > 0 {
        score += 0.5 + 0.6 * progress;
    } else if next_item_size > 0 {
        // reward bins that can also host the lookahead item if slack allows
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 0.4 * slack * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * x;

    // Deviation from mean residual: prefer bins close to average (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // New-bin candidate: keep it neutral-slightly high so it wins only for poor fits
    if bin_residual == bin_capacity {
        score += 0.5 + 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual)
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64).max(0.0);

    // Harmonic class of post_residual: residuals that are multiples of common
    // size classes (10,20,25,50) are more reusable; odd/prime-like residuals are dead space.
    let pr = post_residual;
    if pr > 0 {
        let reusable = (pr % 10 == 0) as f64 * 6.0
            + (pr % 20 == 0) as f64 * 4.0
            + (pr % 25 == 0) as f64 * 3.0
            + (pr % 50 == 0) as f64 * 5.0;
        score -= reusable;
        // Penalize unusable slivers: post_residual below typical min item size
        if pr < 10 {
            score += 12.0;
        } else if pr < 20 {
            score += 5.0;
        }
    } else {
        // Perfect fill is excellent
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty scaled by leftover
            score += 0.15 * pr as f64;
        }
        // Harmonic coupling: next_item and post_residual share a divisor class
        if pr > 0 && next_item_size % 10 == pr % 10 {
            score -= 3.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    if bin_residual == bin_capacity {
        // Base cost of a new bin
        score += 40.0;
        // Opening a bin early in the stream or when few bins exist is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // item wouldn't fit anywhere anyway
        }
    }

    // Prefer bins with below-mean residual (keeps variety of residual classes alive)
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Slight preference to fill older/more crowded bin sets
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty: residuals too small to hold the smallest item (1)
        // are pure waste, but any residual below the next item's need is
        // likely unusable soon; penalize super-linearly for tiny gaps.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 60.0; // tiny gap: nearly dead space
        } else if next_item_size > 0 && (pr as u32) < next_item_size {
            score += 25.0; // can't host the lookahead item
        }

        // Reward leaving room for the lookahead item if it fits snugly.
        if next_item_size > 0 && (pr as u32) >= next_item_size {
            let gap_after_next = pr - next_item_size as f64;
            if gap_after_next < 10.0 {
                score -= 30.0; // two-item snug fit chain
            } else {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    // unless the fit is poor; mild term scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins tighter than average (packing density).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced if many bins already open and
        // current fit options are bad is handled implicitly by other terms.
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward if the next item exactly matches post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin completely
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64)); // next item fits reasonably well
        } else {
            // next item won't fit here; penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    } else {
        // last item: prefer filling bins as tightly as possible
        score += 2.0 * (post_residual as f64);
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (compact bins), but avoid extreme fragmentation.
    score += 0.25 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        // extra bonus if next item also can't use the leftover space anyway
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Penalize opening a new bin when many bins are open and one fits decently.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 * (1.0 - (item_size as f64) / (bin_capacity as f64));
        if open_bins_count == 0 {
            score -= 100.0; // no alternative: must open a bin
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Small penalty for very small unusable leftovers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 8.0 * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item can't fit anywhere else, also favor this bin.
    if next_item_size > 0 {
        if (post_residual as u32) == next_item_size {
            score -= 15.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 4.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer filling
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins already have slack
        // and late in the stream.
        score += 6.0 + 10.0 * (mean_residual / bin_capacity as f64) + 8.0 * progress;
        score += 0.5 * open_bins_count as f64;
    } else {
        // Reward using bins whose residual is close to the mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
        score -= 0.3 * open_bins_count as f64;
    }

    // Time horizon: early in stream, be slightly conservative (favor good fits
    // for future flexibility); late in stream, just minimize waste.
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) shaping.
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 25.0 * norm_pr * norm_pr * norm_pr;

    // Stream-progress coupling: dead space becomes more costly later in the stream.
    let progress_penalty = norm_pr * norm_pr * (0.5 + 1.5 * progress * progress);
    score += 30.0 * progress_penalty;

    // Perfect fit reward (smooth via exponential decay of residual).
    score -= 20.0 * (-norm_pr * 8.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let next_fits = if (post_residual as u64) >= (next_item_size as u64) { 1.0 } else { 0.0 };
        let gap = ((post_residual as i64 - next_item_size as i64).abs() as f64) / cap;
        score += next_fits * (-10.0 * gap) * 0.5 - next_fits * 5.0;
        score -= (1.0 - next_fits) * 0.0;
    } else {
        // Last item: strongly prefer filling bins tightly.
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Dispersion from mean residual: bins far below mean residual (wasteful) penalized.
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for proliferating open bins early (encourages consolidation),
    // relaxing as stream progresses.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: bins whose leftover lands on
    // "usable" residue classes (multiples of 10, or >= next item size) are favored.
    let pr = post_residual;
    let residue_class = pr % 10;
    let class_bonus = match residue_class {
        0 => 6.0,                      // perfectly aligned leftover
        1 | 2 | 3 => -2.0,             // awkward slivers -> penalize slightly
        _ => 0.0,
    };
    score += class_bonus;

    // Fraction-of-capacity coupling: leftover as fraction of capacity
    let frac = pr as f64 / cap;
    if frac < 0.05 {
        score -= 8.0;                  // near-perfect packing
    } else if frac > 0.5 {
        score += 4.0;                  // wasted more than half the bin
    }

    // Lookahead: reward if leftover can host the next item (mod-aware)
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 5.0;
            // integer division threshold: leftover can host next item twice
            if pr / next_item_size.max(1) >= 2 {
                score -= 3.0;
            }
        } else {
            score += 6.0;              // creates dead space w.r.t. lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when the item fits poorly
    // everywhere else (large item relative to capacity) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 > 0.6 * cap;
        if big_item || open_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 15.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mean-residual coupling: when open bins are generally full, prefer
    // consolidating into this one (keeps other bins' residuals larger).
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 2.0;
    }

    // Small tie-breaker by item size class (mod 20 harmonic band)
    score += (item_size % 20) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (bin closes, zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable gaps (1..=12) are wasted capacity
    // since future items are >= 1 but small gaps rarely fit anything useful.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (13.0 - post_residual as f64);
    }

    // Tight fit bonus: reward small post_residual generally (best-fit flavor).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mild encouragement to consolidate into existing bins.
    score += open_bins_count as f64 * 1.5;

    // New empty bin candidate: penalize opening a new bin, scaled by how
    // much residual it would carry and stream progression.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * post_residual as f64
            + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
        // If the item would leave a large residual in the new bin and the
        // next item could use it, soften the penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    } else {
        // Placing into an existing bin: bonus if next item still fits after.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > 0 && post_residual > 0 {
            // Next item won't fit here; slightly penalize leaving a stub.
            score += 8.0;
        }
    }

    // Prefer bins with below-mean residual (denser bins absorb waste better).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect fit (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 100.0;
            // extra reward for tight-but-fitting residual
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use the residual: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize residuals too small for typical items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let crowdedness = mean_residual / bin_capacity as f64;
        // penalize new bins when open bins still have room on average
        score += 150.0 + crowdedness * 100.0;
        if post_residual >= item_size {
            score -= 50.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Prefer filling bins that are already relatively empty vs mean residual.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Mild stream-progression pressure: later in stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 {
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // Next item fits exactly into leftover: reward.
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / post_residual as f64);
        } else {
            // Leftover unusable by lookahead: penalize, scaled by how dead it is.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 20.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins near the mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, be more willing to open fresh bins for large items;
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * tightness;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin is a good fit.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_alternatives = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 18.0 - 14.0 * large_item - 10.0 * poor_alternatives - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: tight fits win, with super-linear penalty on wasted space.
    let mut score = post * post / cap + 0.35 * post;

    // Smooth non-linear coupling of wasted space with stream progress:
    // late in the stream, dead space matters more (fewer chances to fill it).
    let late = progress * progress;
    score += 12.0 * late * (post / cap) * (1.0 - post / cap).max(0.0) * cap * 0.1;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: reward if the next item exactly fills the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if next_item_size as f64 <= post {
            score -= 25.0 * (1.0 - gap / cap);
        } else {
            score += 8.0 * (gap / cap);
        }
    }

    // Prefer bins with residual already below the mean (consolidating waste),
    // smoothly scaled by the number of open bins.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score -= 10.0 * mean_gap * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Penalize the brand-new empty bin candidate smoothly, but relax it late
    // when remaining open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 - 30.0 * progress * (1.0 / (1.0 + fitting_bins_count as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that align with
    // common small-item sizes (multiples of 10 and 25 divide capacity nicely).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual % 10 == 0 {
            score -= 6.0; // perfectly harmonic dead space
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
        if post_residual % 25 == 0 {
            score -= 2.0;
        }
        // Penalize awkward residuals that are hard to fill (small prime-ish gaps)
        if post_residual < 10 {
            score += 8.0; // nearly dead space
        } else if post_residual < 20 {
            score += 3.0;
        }
        // Fractional capacity coupling: prefer leaving near-half or near-full fills
        let frac = pr / cap;
        if (frac - 0.5).abs() < 0.05 {
            score -= 4.0;
        }
    } else {
        score -= 10.0; // perfect closure, strongly favored
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 4.0 - (leftover as f64) * 0.05;
        } else {
            score += 2.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New-bin candidate: penalize unless current fit is bad or bin is fresh
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin costs; only attractive when mean residual is fragmented
        score += 15.0 - 10.0 * (mean_residual / cap).min(1.0) - 5.0 * progress;
        if item_size > 60 {
            score -= 8.0; // big items like fresh bins
        }
    }

    // Tight fits are good: reward small post_residual relative to item
    if post_residual > 0 {
        score -= (item_size as f64) / (post_residual as f64 + 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-exact fills are excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Strict dead-space avoidance: gaps too small for the minimum item size
    // (1 here, but practically small gaps) are wasted. Penalize unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0; // tiny sliver: near-wasted space
    }

    // Gap usability relative to the lookahead item (k=2): a gap that exactly
    // or nearly fits the next item is valuable; a gap that cannot hold the
    // next item but could hold nothing useful is penalized.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 3.0 {
                score -= 30.0; // gap is a near-perfect match for next item
            } else {
                score -= 8.0; // gap still usable by next item
            }
        } else {
            score += 15.0; // gap cannot host the next item: potential dead space
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage scattering across many bins; opening a
    // new bin (residual == capacity) should carry a surcharge that grows with
    // the number of already-open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 6.0 * open_bins_count as f64;
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 2.0 * open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    }

    // Prefer bins whose residual is below the mean (filling the emptier
    // leftovers keeps a pool of large-residual bins flexible).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Early in the stream, allow new bins more freely; late, be frugal.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score -= 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain_fit; // next item can follow into this bin
        } else {
            // next item won't fit here; penalize leaving awkward residual
            let waste = post_residual as f64;
            let awkward = if waste < next_item_size as f64 && waste > 0.0 {
                // residual smaller than next item = dead space unless small
                if waste < 10.0 { 5.0 } else { 15.0 }
            } else { 0.0 };
            score += awkward;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score -= 8.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (fitting_bins_count as f64).ln() / 3.0
        };
        let early = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 30.0 * pressure * (1.0 - 0.5 * early);
        // if the item is huge relative to capacity, opening fresh is less bad
        score -= 10.0 * fit_ratio;
    }

    // Slight preference for using more open bins when many are nearly full
    if open_bins_count > 0 {
        score += 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Penalize small dead space that nothing (min size 1... but practically small items) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving medium post-residuals that trap nothing.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin.
        score += 15.0;
        // If no open bin fits well (post_residual large relative to capacity), new bin becomes better.
        let waste = post_residual as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 10.0 * waste;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins with high mean residual: reuse them instead.
        score += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.05;
    } else {
        // Favor bins with low residual (best-fit bias) scaled by how many alternatives exist.
        score += 4.0 * (bin_residual as f64 / bin_capacity as f64);
        if fitting_bins_count > 2 {
            // With many options, be picky: prefer near-exact fits.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global pressure: when mean residual is low, conserve space aggressively.
    score += 0.03 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual, with non-linear amplification of tight fits
    let mut score = pr * (1.0 + 2.0 * pr_norm * pr_norm);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, dead space becomes costlier
    score += 20.0 * pr_norm * pr_norm * (progress * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * (1.0 - pr_norm);
    }

    // Penalize bins whose residual deviates from the mean (fragmentation signal)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev;

    // Lookahead: reward bins whose post residual can host the next item,
    // with smooth quadratic falloff as slack shrinks
    if next_item_size > 0 {
        let slack = pr as i64 - next_item_size as i64;
        if slack >= 0 {
            let s = slack as f64;
            score -= 12.0 * (1.0 - (s / cap) * (s / cap));
        } else {
            let s = (-slack) as f64;
            score += 0.15 * s;
        }
    }

    // Mild penalty for over-spreading across many open bins
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: keep it unattractive unless the fit in open bins is poor
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and tiny residuals are gold.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 200.0;  // near-perfect, unusable dead space anyway
    } else if post_residual <= 10 {
        score -= 50.0;
    }

    // Integer division classes: residual buckets by 20 (capacity / 5)
    let class = post_residual / 20;
    score += class as f64 * 15.0;

    // Modulo arithmetic: residual mod 10 — small remainders are less reusable
    let rem = post_residual % 10;
    score += rem as f64 * 1.5;

    // Lookahead: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let next_fit_class = (post_residual - next_item_size) / 10;
            score -= 60.0 - next_fit_class as f64 * 10.0;
        } else {
            // next item cannot use this bin's remainder: penalize large leftover
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residual would be large waste
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size >= 50 {
            score -= 100.0; // big items are fine in a fresh bin
        }
    }

    // Tightness reward: the tighter the fit relative to residual, the better
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 80.0;

    // Late in stream: consolidate harder, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 120.0;
    } else {
        score -= progress * 30.0;
    }

    // Prefer bins below mean residual (fill emptier bins first to consolidate)
    if (bin_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Penalize many open bins: encourage closing them out
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps smaller than the minimum item size are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit — strongly rewarded
    } else if post_residual <= 10 {
        // small gap: likely dead space unless next item fits it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // lookahead can use the gap
        } else {
            score += 60.0; // dead space penalty
        }
    } else {
        // usable gap: mild reward for tightness, small lookahead bonus
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Reward tight fits relative to item size (small post_residual relative to item).
    score += 0.5 * (item_size as f64) * (post_residual as f64 / (item_size as f64 + 1.0));

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but allow new bins when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: neutral baseline; penalize slightly unless current bins are very full.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fullness < 0.85 {
            score += 40.0 * (0.85 - avg_fullness); // discourage premature new bins
        } else {
            score -= 15.0; // bins nearly full: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: item then next item fills bin exactly or near-exactly.
            let chain_gap = post_residual - next_item_size;
            if chain_gap == 0 {
                score -= 60.0; // perfect two-item fill
            } else {
                // Reward small chain gaps, penalize large leftover dead space.
                score -= 40.0 * (1.0 - chain_gap as f64 / bin_capacity as f64);
                score += 0.25 * chain_gap as f64;
            }
        } else {
            // Next item cannot fit here; post_residual becomes dead space unless tiny.
            if post_residual < 10 {
                score -= 15.0; // near-full bin is fine
            } else {
                score += 0.5 * (post_residual as f64 - next_item_size as f64).abs();
            }
        }
    } else {
        // Last item: just minimize residual.
        score -= 20.0;
    }

    // Compare post_residual against mean residual: prefer bins left closer to average
    // (balanced packing) when not chaining.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists (large item,
    // tight open bins) or item is huge and would leave fragmented bins.
    if bin_residual == bin_capacity {
        if item_size > 60 || (fitting_bins_count <= 1 && next_item_size > 50) {
            score -= 30.0;
        } else {
            score += 45.0; // prefer existing bins generally
        }
    }

    // Slight preference for tight fits overall.
    score += 0.1 * post_residual as f64 * (1.0 - item_size as f64 / bin_capacity as f64);

    // Mild stream-aware pressure: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}
